const CURRICULUM={"respiratory":{"title":"呼吸系统：先看气道，再看氧合与通气","intro":"用咳痰、气促、咯血三条主线识别病种，把气道清除、气体交换和循环风险分别回答。","framework":[{"id":"resp-airway","title":"气道清除四步","cue":"咳痰、痰黏、咳嗽无力","answer":"先看意识、咳嗽力量和痰能否排出，再记录痰量、颜色、黏稠度、气味；能配合者指导深呼吸与有效咳嗽。痰黏时配合湿化和处方治疗；排出仍困难时评估吸引或人工气道支持，最后比较排痰与呼吸是否改善。","why":"分泌物增多与清除能力下降均可堵塞气道；手段必须与排痰能力匹配。","source":"D05:P0062–P0064、P0080、P0100–P0105"},{"id":"resp-monitor","title":"呼吸观察六项","cue":"气促、发绀、意识变化","answer":"连续观察频率、节律、深度、呼吸功、血氧及意识；结合血气区分低氧与通气不足。突发胸痛查气胸或栓塞线索，昼睡夜醒和嗜睡复评二氧化碳及其他意识异常原因。","why":"病情恶化可来自气道、肺实质、胸膜或血流问题，不能只增加吸氧流量。","source":"D05:P0037–P0046、P0078–P0084"},{"id":"resp-position","title":"体位与进食先看两条边界","cue":"呼吸费力、咯血或吞咽不安全","answer":"气促者在循环允许下取有利呼吸的坐位或半卧位；咯血且出血侧明确时注意保护健侧。进食前评估呼吸与吞咽，明显气道危险时先处理危险；少量多餐，心肾受限者单独核算水盐。","why":"体位影响通气、血液流向和回心血量，饮食途径影响误吸风险。","source":"D05:P0068–P0089"},{"id":"resp-closed-loop","title":"按问题写护理诊断并复评","cue":"题目要求主要护理诊断及措施","answer":"痰黏难排对应清理呼吸道无效，低氧或血气异常对应气体交换受损，活动诱发气促乏力对应活动无耐力；每条写出题干证据与相关因素。措施按气道、监测、体位营养、用药、并发症和康复整体组织，评价排痰、氧合和耐量变化。","why":"护理诊断名称相同，相关因素和评价指标仍随疾病变化。","source":"D05:P0003–P0018、P0058–P0067"}],"contrasts":[{"id":"resp-disease","title":"病史和表现怎样指向疾病","axis":"diagnosis","common":"先分慢性基础、急性诱因和危险并发症。","rows":[{"name":"慢阻肺","cues":"长期咳痰气促，本次加重","content":"问清平时活动耐量及本次痰量、痰色和气促变化。桶状胸、过清音只是支持线索，仍需肺功能等证据。","mechanism":"持续气流受限造成呼气受阻及气体潴留。","avoid":"不能用外观单独确诊，也不能自动判为Ⅱ型呼衰。","numbers":"","source":"D05:P0022–P0046","id":"row-1"},{"name":"支气管扩张","cues":"反复脓痰、咯血，可能幼年起病","content":"把反复感染史、痰和血的变化与影像对应。出现大咯血时先评价排血能力及气道危险。","mechanism":"扩张支气管分泌物潴留，局部血管受损可出血。","avoid":"咯血阶段不能机械套用叩击或头低引流。","numbers":"","source":"D05:P0022–P0046","id":"row-2"},{"name":"支气管哮喘","cues":"诱因后阵发呼气困难，夜间或凌晨发作","content":"关注症状波动、诱因和既往缓解方式。以可变气流受限检查支持诊断，严重气促而呼吸音变弱也需警惕。","mechanism":"气道炎症、收缩和黏液堵塞共同增加阻力。","avoid":"哮鸣音缺如不能排除严重发作。","numbers":"","source":"D05:P0022–P0046","id":"row-3"},{"name":"肺炎链球菌肺炎","cues":"急性高热胸痛，可能铁锈色痰","content":"把感染表现与肺实变影结合，再以合适标本帮助病原判断。观察呼吸恶化及循环灌注，不只记录体温。","mechanism":"肺泡炎症渗出减少有效气体交换。","avoid":"痰色不是病原学确诊。","numbers":"","source":"D05:P0022–P0046","id":"row-4"},{"name":"肺脓肿","cues":"误吸风险、高热、脓臭痰及空洞液平","content":"追问口腔感染、意识障碍和误吸背景。记录痰液变化，结合病原和影像评价病灶。","mechanism":"局部化脓坏死形成含液空腔。","avoid":"所有空洞不都属于脓肿。","numbers":"","source":"D05:P0022–P0046","id":"row-5"},{"name":"肺结核","cues":"低热盗汗消瘦、咳嗽或咯血","content":"结合接触史、影像和结核相关病原检查。关注隔离与感染管理要求，并把咯血另列气道风险。","mechanism":"结核感染可有慢性消耗及肺组织损伤。","avoid":"典型全身症状缺失不排除，不能只靠上肺阴影确诊。","numbers":"","source":"D05:P0022–P0046","id":"row-6"},{"name":"肺栓塞","cues":"制动或DVT背景后突发气促胸痛、晕厥","content":"先识别突发呼吸与循环异常并及时升级评估。检查选择与临床概率配合，观察下肢肿痛及低灌注。","mechanism":"肺血流突然受阻导致通气血流失衡并可增加右心负荷。","avoid":"D二聚体升高不能单独确诊；影像征象须对应正确检查。","numbers":"","source":"D05:P0022–P0046","id":"row-7"},{"name":"呼吸衰竭与肺性脑病","cues":"低氧、通气异常或意识改变","content":"用血气辨别以低氧为主或合并二氧化碳升高。意识变化须联系通气、感染、低糖及药物等原因。","mechanism":"氧合障碍与肺泡通气不足不是同一问题。","avoid":"不能凭慢阻肺病名分型，也不能把所有嗜睡都归肺性脑病。","numbers":"","source":"D05:P0022–P0046","id":"row-8"},{"name":"ARDS","cues":"严重诱因后进行性氧合障碍","content":"把起病时间、氧合、双肺影像及循环因素共同评价。俯卧位或通气支持时关注管路固定、受压处与耐受。","mechanism":"炎症性肺损伤可使肺泡渗漏并降低肺顺应性。","avoid":"氧合指数一个数字不能独立完成诊断。","numbers":"","source":"D05:P0022–P0046","id":"row-9"},{"name":"肺心病与自发性气胸","cues":"慢性肺病伴水肿，或突然单侧胸痛气促","content":"水肿、颈静脉充盈提示右心负荷，需记录容量和心律。突发单侧呼吸音减弱时重新排查胸膜积气，不能仍只当痰多。","mechanism":"肺血管阻力增高可累及右心，胸膜积气则压缩肺。","avoid":"水肿不都等于肺心病；突发气促先找新危险。","numbers":"","source":"D05:P0022–P0046","id":"row-10"}],"question":"哪些线索能把普通气促分到不同疾病？"},{"id":"resp-tests","title":"检查要回答什么问题","axis":"labs","common":"每项检查配一个目的，再说结果对护理有何影响。","rows":[{"name":"血气与床旁血氧","cues":"呼吸衰竭或意识变化","content":"血氧反映氧合趋势，血气还提供二氧化碳及酸碱信息。记录采样时吸氧条件，并比较治疗前后变化。","mechanism":"单看氧饱和度不能反映二氧化碳潴留。","avoid":"吸氧条件不清的血气不能机械套室内空气标准。","numbers":"","source":"D05:P0047–P0057","id":"row-1"},{"name":"感染指标与标本","cues":"痰变化、高热或寒战","content":"血常规、CRP和PCT提供炎症线索；痰标本帮助病原判断。寒战高热时按指征配合血培养，标本质量与既往抗菌药均影响解释。","mechanism":"炎症强度与病原种类是两个问题。","avoid":"不能用一种炎症指标直接决定全部治疗。","numbers":"","source":"D05:P0047–P0057","id":"row-2"},{"name":"肺功能和可变性试验","cues":"慢阻肺或哮喘鉴别","content":"肺功能评价气流受限，舒张或激发相关试验帮助评价可变性。先判断急性不稳定者是否适宜检查，并核对检查前用药要求。","mechanism":"同为气促，气流受限机制和可变程度不同。","avoid":"不能为完成检查而延误急性处理。","numbers":"","source":"D05:P0047–P0057","id":"row-3"},{"name":"影像与取样","cues":"实变、空洞、胸膜液体或肿块","content":"胸片和CT定位病变并找气胸等并发症。胸水分析、支气管镜或穿刺取样各回答液体性质、病原或病理问题，配合项目准备与术后观察。","mechanism":"结构影像和病原/病理提供不同层次证据。","avoid":"不能把一种影像词跨检查方式套用。","numbers":"","source":"D05:P0047–P0057","id":"row-4"}],"question":"感染、气流受限和气体交换分别用什么检查？"},{"id":"resp-drugs","title":"药物目的和用后观察","axis":"treatment","common":"先写药物解决哪一环，再写护士观察什么。","rows":[{"name":"支气管扩张与吸入技巧","cues":"哮喘、慢阻肺存在气道阻力","content":"支气管扩张药改善气流，护士核对吸入装置并让患者演示操作。观察气促、心悸、震颤或口干等反应，避免只问是否按时喷药。","mechanism":"药物到达气道依赖吸入配合与装置使用。","avoid":"不同制剂起效和持续时间不同，不能互换为同一用法。","numbers":"","source":"D05:P0090–P0104；GINA哮喘指南；NICE NG115","id":"row-1"},{"name":"哮喘抗炎与缓解分工","cues":"反复发作或需持续管理","content":"含吸入激素的治疗用于降低炎症与发作风险，缓解药用于相应症状路径。核对处方中的控制和缓解职责，并观察吸入后口咽不适和用量增加。","mechanism":"仅放松平滑肌不能消除气道炎症。","avoid":"哮喘不能长期只依赖短效β受体激动剂；LABA不能脱离ICS单独用于哮喘。","numbers":"","source":"D05:P0090–P0104；GINA哮喘指南；NICE NG115","id":"row-2"},{"name":"抗感染和祛痰","cues":"有感染依据或分泌物黏稠","content":"抗感染按感染类型和病原证据选择，观察体温、痰和耐受。祛痰或湿化后评价能否实际排出，咳嗽无力者需同步清除支持。","mechanism":"稀释分泌物与清除分泌物必须配合。","avoid":"病毒性诱因或单纯痰多不自动等于需要抗菌药。","numbers":"","source":"D05:P0090–P0104；GINA哮喘指南；NICE NG115","id":"row-3"},{"name":"肺心病相关药物","cues":"水肿或右心功能异常","content":"利尿后比较尿量、体重、血压和电解质，扩血管或正性肌力治疗后观察灌注与心律。心悸、乏力或心律变化应联系药物和电解质共同分析。","mechanism":"去液、循环支持和心肌电活动相互影响。","avoid":"不能把尿量越大或心率越慢当作疗效越好。","numbers":"","source":"D05:P0090–P0104；GINA哮喘指南；NICE NG115","id":"row-4"},{"name":"氧疗和镇静风险","cues":"低氧或存在高碳酸血症风险","content":"给氧需以目标血氧和血气复评，记录装置、流量及反应。通气不足或意识异常时审慎核对镇静、镇咳等可能影响呼吸的药物。","mechanism":"给氧改善氧合，但不能代替通气和气道清除。","avoid":"不按一个固定流量用于所有呼吸疾病。","numbers":"慢阻肺急性加重接受紧急氧疗时常以SpO₂ 88%—92%为目标，结合血气及处方调整。","source":"D05:P0090–P0104；GINA哮喘指南；NICE NG115","id":"row-5"}],"question":"缓解支气管痉挛能否替代控制气道炎症？"},{"id":"resp-care","title":"共性护理中填入疾病差异","axis":"nursing","common":"写P-E时用疾病机制，写措施时用当前证据。","rows":[{"name":"清理呼吸道无效与气体交换受损","cues":"痰难排，或低氧血气异常","content":"前者把分泌物与咳嗽能力列为相关因素，评价痰能否排出。后者把通气、肺泡病变或通气血流失衡与低氧证据连接，评价氧合及呼吸功。","mechanism":"堵塞与交换异常可共存，但不是同义词。","avoid":"不能一项措施重复抄成全部护理诊断的答案。","numbers":"","source":"D05:P0062–P0067、P0068–P0089、P0105–P0134","id":"row-1"},{"name":"咯血与窒息危险","cues":"血量增加、排血不畅、意识变化","content":"记录出血量和频次，同时看气道是否被血块影响。准备吸引和急救配合，出血侧明确时注意保护健侧；饮食随出血及吞咽状态安排。","mechanism":"少量血也可能因排不出而威胁气道。","avoid":"不能仅用出血量判断全部危险，也不能常规叩背排痰。","numbers":"","source":"D05:P0062–P0067、P0068–P0089、P0105–P0134","id":"row-2"},{"name":"发热、口腔与皮肤","cues":"肺炎高热、脓臭痰、水肿或卧床","content":"高热者兼顾体温、汗液丢失与摄入，换除湿衣并评价降温反应。口腔清洁减少不适，水肿及卧床者检查受压处、保持皮肤完整。","mechanism":"发热增加耗氧，分泌物与受压增加感染和损伤风险。","avoid":"心肾受限者不能只因发热就大量补水。","numbers":"","source":"D05:P0062–P0067、P0068–P0089、P0105–P0134","id":"row-3"},{"name":"活动与饮食条件","cues":"气促进食费力，或合并右心水肿","content":"急性危险时协助生活，缓解后逐级活动并观察气促、心率和疲劳。营养按摄入能力安排，水盐是否限制取决容量与心肾状态；哮喘回避已证实诱发物。","mechanism":"呼吸肌耗能与活动耗氧增加，过饱也影响呼吸舒适。","avoid":"不把所有肺病统一为大量饮水或固定低盐。","numbers":"","source":"D05:P0062–P0067、P0068–P0089、P0105–P0134","id":"row-4"},{"name":"气胸、休克与DVT","cues":"突发胸痛、冷汗低压或下肢肿痛","content":"气胸关注单侧呼吸变化并配合胸膜处理；休克记录意识、末梢、血压及尿量。卧床者落实活动及血栓预防，出现疑似血栓及时报告并避免按摩。","mechanism":"三个分支分别威胁通气、灌注或肺血流。","avoid":"不能把不同急变都继续归为原病气促。","numbers":"","source":"D05:P0062–P0067、P0068–P0089、P0105–P0134","id":"row-5"},{"name":"呼吸康复和居家氧疗","cues":"病情稳定准备出院","content":"示范缩唇呼气和腹式呼吸，让患者回演；在能耐受范围安排练习。家庭用氧核对处方、装置与安全，远离火源，说明气促痰量改变等复诊信号。","mechanism":"延长呼气有助于呼气控制，安全用氧依赖持续正确操作。","avoid":"家庭氧疗不是所有慢阻肺的统一处方，复查和器材维护按具体安排。","numbers":"","source":"D05:P0062–P0067、P0068–P0089、P0105–P0134","id":"row-6"}],"question":"同样气促、咯血或水肿，护理重点有什么不同？"},{"id":"resp-medical-details","title":"吸入与辅助药物逐类回忆","axis":"treatment","common":"区分药类、控制与缓解职责、装置和不良反应。","rows":[{"name":"SABA与LABA","cues":"需缓解支气管痉挛或长期处方","content":"沙丁胺醇等短效药与长效β受体激动剂有不同起效和持续时间，核对处方职责。观察心悸、震颤及相关电解质变化，反复加量提示需复评控制。","mechanism":"β受体作用使支气管平滑肌舒张，也可产生全身作用。","avoid":"哮喘LABA不脱离ICS单用，不把SABA频繁使用当长期控制良好。","numbers":"","source":"D05:P0097–P0099；M017/M018逐图核查；GINA；NHS；FDA","id":"row-1"},{"name":"ICS与全身糖皮质激素","cues":"长期抗炎，或急性阶段处方","content":"吸入抗炎后按装置要求清洁口腔，观察声音和口腔真菌感染。全身治疗额外关注血糖、感染及长期代谢骨骼风险，按疗程减量安排执行。","mechanism":"局部与全身暴露不同，不能互相视为等剂量替换。","avoid":"不能把吸入制剂或全身激素统一成固定重叠两周方案。","numbers":"","source":"D05:P0097–P0099；M017/M018逐图核查；GINA；NHS；FDA","id":"row-2"},{"name":"SAMA与LAMA","cues":"抗胆碱支气管扩张处方","content":"异丙托溴铵等短效药与长效药核对装置和使用安排。观察口干、排尿困难和眼部不适，雾化时避免药液进入眼睛。","mechanism":"抑制胆碱能收缩可扩张气道，也影响腺体和其他平滑肌。","avoid":"青光眼或尿潴留风险者需专门评估，不能仅凭前列腺增大一律禁掉所有吸入药。","numbers":"","source":"D05:P0097–P0099；M017/M018逐图核查；GINA；NHS；FDA","id":"row-3"},{"name":"茶碱类","cues":"专科安排的附加治疗","content":"核对缓释剂型不能随意碾碎，并观察恶心、失眠、心悸或心律改变。新增抗菌药、吸烟变化或其他相互作用时复核，必要时配合血药浓度。","mechanism":"治疗范围较窄，清除受药物及生理状态影响。","avoid":"不按图上固定浓度或静脉速度自行执行，不当作人人常规首选。","numbers":"","source":"D05:P0097–P0099；M017/M018逐图核查；GINA；NHS；FDA","id":"row-4"},{"name":"白三烯调节剂","cues":"特定哮喘控制方案","content":"孟鲁司特等用于相应控制情境，仍需评价症状及发作风险。观察睡眠、情绪和行为改变，出现异常联系治疗团队。","mechanism":"阻断白三烯相关通路与直接支气管扩张作用不同。","avoid":"不能替代所有ICS方案，不能因可口服就忽略神经精神不良反应。","numbers":"","source":"D05:P0097–P0099；M017/M018逐图核查；GINA；NHS；FDA","id":"row-5"}],"question":"心悸、口干和口腔白斑分别首先联系哪类药？"},{"id":"resp-gas-numbers","title":"呼吸衰竭数值与采样条件","axis":"labs","common":"成人、海平面、安静休息并呼吸空气的动脉血气，先核对条件。","rows":[{"name":"Ⅰ型与Ⅱ型呼吸衰竭","cues":"低氧或疑二氧化碳潴留","content":"Ⅰ型以氧合不足为主，Ⅱ型合并通气不足所致二氧化碳升高。采样时若已吸氧需记录浓度并结合临床和血气复评，不能为取得室内空气值擅停所需氧疗。","mechanism":"吸入氧改变PaO₂，PaCO₂又反映通气，两个维度要分开。","avoid":"这些阈值不是机械通气或急救的唯一启动条件。","numbers":"Ⅰ型：PaO₂＜60 mmHg，PaCO₂正常或降低；Ⅱ型：PaO₂＜60 mmHg且PaCO₂＞50 mmHg。","source":"D05:P0039–P0042；既有DETAIL respiratory-labs；AHRQ通气证据表","id":"row-1"},{"name":"血气变化与给氧评价","cues":"使用氧疗后或意识变化","content":"同看pH、PaCO₂、PaO₂与碳酸氢根趋势，联系呼吸功和意识。血氧改善而二氧化碳及酸中毒恶化时不能只以氧饱和度达标判断恢复。","mechanism":"氧合改善不等于肺泡通气改善。","avoid":"脉搏血氧不能取代血气中的二氧化碳和酸碱信息。","numbers":"慢阻肺急性加重紧急氧疗常用SpO₂目标88%—92%，需按处方及血气调整。","source":"D05:P0039–P0042；既有DETAIL respiratory-labs；AHRQ通气证据表","id":"row-2"}],"question":"为什么吸氧后的PaO₂不能直接与未吸氧分型阈值比较？"}],"drills":[{"id":"resp-drill-change","title":"病情变了要换分支","stem":"慢性咳痰者原本痰黏，午后突然右胸疼痛，气促明显加重，右侧呼吸音变弱。","prompt":"原来的排痰框架需要补什么？","answer":["先重评气道、氧合和灌注，识别突然新发的胸膜危险。","列出气胸等方向，配合影像及急救评估，不只增加排痰动作。","体位和氧疗依据当时状态，并连续记录变化。"],"source":"D05:P0024、P0119–P0121；原创变式"},{"id":"resp-drill-recall","title":"同名诊断怎样写不同依据","stem":"两位患者都气促：甲痰黏且咳嗽无力，乙痰少但氧合明显下降。","prompt":"分别写首要护理问题、相关因素及一个评价指标。","answer":["甲优先看气道清除，相关因素为痰黏和咳嗽能力不足，评价排痰是否有效。","乙重点评价气体交换，相关因素需结合肺部或通气证据，评价血氧、血气和呼吸功。","两类问题可并存，排序以当时气道和氧合危险决定。"],"source":"D05:P0059–P0067；原创变式"},{"id":"resp-drill-info","title":"整体护理前还要问什么","stem":"反复咳痰者这次痰更黏，轻微活动便气促；现有资料只有体温和胸片。","prompt":"按健康史、身体、心理社会三个层次补资料。","answer":["健康史补吸烟职业暴露、既往疾病与用药过敏、平时与本次发作差别。","身体补意识、呼吸血氧血气、咳嗽排痰能力、营养容量及并发症线索。","心理社会补理解程度、焦虑与家庭支持，决定教育及出院安排。"],"source":"D05:P0078–P0084、P0126–P0133；M024题型目标；原创变式"},{"id":"resp-drill-brain","title":"从昼夜颠倒解释通气问题","stem":"慢性肺病患者感染后出现昼睡夜醒、烦躁，家属只要求加大吸氧。","prompt":"解释评估顺序及为什么不能只调大流量。","answer":["先看意识、气道、呼吸功和灌注，复查血气并记录当前吸氧条件。","考虑通气不足及二氧化碳相关影响，同时排查药物和低糖等原因。","给氧按目标与血气调整，必要时配合通气支持，不以吸氧代替通气。"],"source":"D05:P0082、P0095–P0096、P0103、P0117–P0118；M023/M030题型目标；原创变式"},{"id":"resp-drill-blood","title":"咯血时护理诊断怎样排序","stem":"反复脓痰者本次咯血增加，出现胸闷，血液不易咳出，尚能交流。","prompt":"先关注什么，并给出一个护理问题与相关因素。","answer":["先看气道排血、呼吸和循环，不仅统计血量。","清理呼吸道无效可联系血液或血块及排出困难；窒息风险依据气道受威胁另列。","出血侧明确时保护健侧，准备急救配合，评价排血和氧合变化。"],"source":"D05:P0027–P0028、P0081、P0115–P0116；M031题型目标；原创变式"},{"id":"resp-drill-nebulizer","title":"雾化药物按目的比较","stem":"一位患者拿到几种不同雾化或吸入处方，问这些药是不是都只是化痰。","prompt":"分别解释舒张、抗炎和分泌物处理，并列两个观察。","answer":["支气管扩张解决痉挛及阻力，激素控制炎症，祛痰或湿化处理分泌物性状。","核对装置和吸入技巧，观察心悸震颤、口腔及排尿眼部等与药类对应反应。","评价实际排痰与呼吸变化，不能把所有制剂混入同一装置或互换时点。"],"source":"D05:P0097–P0105；M023/M024题型目标；原创变式"}],"references":[{"title":"NICE 慢阻肺急性加重氧疗质量标准","url":"https://www.nice.org.uk/guidance/qs10/resources/chronic-obstructive-pulmonary-disease-in-adults-2098478592709"},{"title":"NICE 慢阻肺诊疗","url":"https://www.nice.org.uk/guidance/ng115/chapter/Recommendations"},{"title":"GINA 哮喘管理概要","url":"https://ginasthma.org/wp-content/uploads/2025/06/GINA-Summary-Guide-2025-WEB_FINAL-WMS.pdf"},{"title":"NHS 茶碱监测与相互作用","url":"https://www.rightdecisions.scot.nhs.uk/tam-treatments-and-medicines-nhs-highland/formularies/highland-formulary/respiratory-system/bronchodilators-formulary/theophylline-formulary/"},{"title":"FDA 孟鲁司特神经精神反应警示","url":"https://www.fda.gov/drugs/fda-requires-boxed-warning-about-serious-mental-health-side-effects-asthma-and-allergy-drug"},{"title":"AHRQ 家庭无创通气证据：COPD","url":"https://www.ncbi.nlm.nih.gov/books/NBK575989/table/appf.tab1/"}]},"cardiac":{"title":"循环系统：呼吸与灌注并看","intro":"用肺循环淤血、体循环淤血、心肌缺血、节律与瓣膜结构五条线组织识别，再把药物和活动护理填入对应分支。","framework":[{"id":"card-monitor","title":"循环观察七项","cue":"心衰、胸痛、心律异常或血压突变","answer":"同步记录意识、血压、心率心律、呼吸血氧、末梢皮温、尿量与体重出入量；联系心电、电解质和肾功能。观察恶化发生在用药、活动还是进食前后，报告低灌注和恶性心律线索。","why":"循环问题可能同时影响泵功能、节律和器官灌注。","source":"D06:P0058–P0062、P0121–P0123"},{"id":"card-load","title":"淤血与低灌注分开答","cue":"水肿、湿啰音、低压冷汗或少尿","answer":"肺淤血看气促和湿啰音，体循环淤血看颈静脉、水肿及腹水；低灌注看冷汗、意识、血压与尿量。体位、给氧和用药配合均以这三组状态为依据，治疗后再复评。","why":"淤血不等于血管内有效灌注充分，强行去液或固定端坐都可能不合适。","source":"D06:P0007–P0009、P0053、P0120–P0123"},{"id":"card-pain","title":"胸痛记录与再灌注线索","cue":"胸痛新发、持续或反复","answer":"记部位、性质、强度、起止时间、诱因、放射、伴随症状及缓解方式。同步配合心电和心肌损伤标志物动态评价，持续或恶化时及时升级，记录治疗与疼痛反应。","why":"疼痛缓解不能代替心肌缺血评估，时间影响再灌注策略。","source":"D06:P0017–P0018、P0035–P0038、P0061、P0112"},{"id":"card-rehab","title":"按耐量组织生活和康复","cue":"病情稳定或准备出院","answer":"急性危险期协助生活并减少耗氧，稳定后从可耐受的日常活动递进；活动前后比较心率、血压、气促和疲劳。新发胸痛、明显头晕、异常心律或血压反应时停止并复评，同时教会体重、血压和症状记录。","why":"相同诊断可处于不同心功能阶段，活动计划需由症状与监测连接。","source":"D06:P0082–P0109、P0140–P0145"}],"contrasts":[{"id":"card-disease","title":"淤血、缺血与血压病种对照","axis":"diagnosis","common":"用主诉、体征和检查组成依据，不靠一个症状定病。","rows":[{"name":"左心衰与急性肺水肿","cues":"气促、湿啰音，急性时端坐及粉红泡沫痰","content":"慢性看活动或卧位相关气促，急性突变先评估呼吸和灌注。查找缺血、节律、感染或容量等诱因，并比较治疗反应。","mechanism":"左侧压力升高可导致肺淤血及肺泡液体增加。","avoid":"不能仅凭肺水肿认定全身体液过多。","numbers":"","source":"D06:P0007–P0009、P0016–P0033","id":"row-1"},{"name":"右心衰","cues":"颈静脉充盈、肝大、下肢水肿与腹胀","content":"评估水肿范围、体重、尿量和腹水，并询问食欲及摄入。与肾病、肝病等水肿原因结合鉴别。","mechanism":"体循环静脉压升高可累及肝脏和胃肠。","avoid":"不能把所有下肢水肿都归为右心衰。","numbers":"","source":"D06:P0007–P0009、P0016–P0033","id":"row-2"},{"name":"心绞痛与心肌梗死","cues":"诱发短暂胸痛，或持续剧痛难缓解","content":"心绞痛常随负荷诱发，心梗可持续并伴自主神经及循环表现。两者均结合动态心电及标志物，不以含药反应单独排除心梗。","mechanism":"短暂供需失衡与心肌坏死的证据层次不同。","avoid":"疼痛不典型或减轻也不能排除急性冠脉问题。","numbers":"","source":"D06:P0007–P0009、P0016–P0033","id":"row-3"},{"name":"高血压与高血压急症","cues":"反复血压高，或骤升伴神经/心肾损害","content":"一般高血压需规范重复测量及风险评估，不能一次定性。急症重点是新发靶器官损害表现，持续监测神志、胸痛、呼吸和尿量。","mechanism":"过高压力与过快降压均可能影响重要器官灌注。","avoid":"不是所有高数字都同一急症，不能把一个降压目标用于全部情境。","numbers":"","source":"D06:P0007–P0009、P0016–P0033","id":"row-4"},{"name":"感染性心内膜炎","cues":"发热、杂音、栓塞或周围体征","content":"联系瓣膜病、感染及可能的栓塞表现，配合病原和超声评估。记录体温、营养消耗及神经、皮肤等新变化。","mechanism":"心内膜感染可破坏瓣膜并产生栓塞。","avoid":"不能只用发热或某一病原先验确诊。","numbers":"","source":"D06:P0007–P0009、P0016–P0033","id":"row-5"},{"name":"扩张与肥厚型心肌病","cues":"心腔扩大泵力差，或肥厚伴晕厥家族史","content":"前者常以心衰和节律问题为线索，后者关注劳力性症状、梗阻及猝死风险。结合超声结构与功能，不把两类的用药方向混写。","mechanism":"收缩功能减弱与流出道梗阻并非同一机制。","avoid":"梗阻性肥厚型不能套用所有减负荷或强心方案。","numbers":"","source":"D06:P0007–P0009、P0016–P0033","id":"row-6"},{"name":"心肌炎、心包炎与压塞","cues":"上感后心悸，或胸痛摩擦音，或低压静脉充盈","content":"心肌炎结合心律和损伤标志物，心包炎结合疼痛、摩擦音及心电。积液伴灌注异常时优先警惕压塞并配合超声和紧急评估。","mechanism":"心肌受损影响泵和节律，心包压力升高限制心室充盈。","avoid":"压塞三联征不全也不能排除，心电改变不是单项确证。","numbers":"","source":"D06:P0007–P0009、P0016–P0033","id":"row-7"}],"question":"左心、右心及胸痛病变的关键差异是什么？"},{"id":"card-valves","title":"四类瓣膜病怎样比较","axis":"diagnosis","common":"先确定瓣膜与狭窄/关闭不全，再联系杂音时相和负荷。","rows":[{"name":"二尖瓣狭窄","cues":"风湿背景、舒张期隆隆样杂音","content":"心尖部舒张期杂音是识别线索，结合超声确认瓣口情况。关注房颤、肺淤血和栓塞相关风险。","mechanism":"左房向左室流入受阻，左房负荷增加。","avoid":"不能只靠面容或心影确诊。","numbers":"","source":"D06:P0019–P0024","id":"row-1"},{"name":"二尖瓣关闭不全","cues":"心尖部收缩期吹风样杂音","content":"把收缩期反流与气促及心腔变化联系。超声评价反流程度与心功能，并观察心衰表现。","mechanism":"心室收缩时血液可逆流至左房，形成容量负荷。","avoid":"无症状不代表反流不需随访。","numbers":"","source":"D06:P0019–P0024","id":"row-2"},{"name":"主动脉瓣狭窄","cues":"劳力性气促、胸痛或晕厥，收缩期杂音","content":"三联表现提示流出受阻，需超声评价严重度。活动与用药配合特别关注头晕、胸痛和灌注。","mechanism":"固定流出障碍限制心排量增加。","avoid":"不能以勉强完成运动作为康复目标。","numbers":"","source":"D06:P0019–P0024","id":"row-3"},{"name":"主动脉瓣关闭不全","cues":"舒张期叹气样杂音、脉压增大","content":"联系舒张期反流与周围血管体征，再用超声评价。长期观察容量负荷、心腔和心衰症状变化。","mechanism":"主动脉血在舒张期回流左室，增加左室容量负荷。","avoid":"周围体征不能替代瓣膜影像评价。","numbers":"","source":"D06:P0019–P0024","id":"row-4"}],"question":"杂音发生在何时、何处，与哪种负荷有关？"},{"id":"card-rhythm","title":"节律与检查配对","axis":"labs","common":"描述心电形态，同时看患者有无灌注异常。","rows":[{"name":"窦性心动过速与过缓","cues":"窦性P波与心率变化","content":"确认节律来源后联系发热、疼痛、药物和灌注。记录症状与心率变化是否同步，不能仅因快慢就套抗心律药。","mechanism":"心率变化可能是代偿，也可能降低有效心排量。","avoid":"未结合症状与心电不能仅触脉决定治疗。","numbers":"","source":"D06:P0010–P0015、P0034–P0048、P0061","id":"row-1"},{"name":"房性与室性期前收缩","cues":"提前P波，或提前宽大QRS","content":"房早关注提前的异形P波，室早关注宽大提前QRS及其前P波关系。频发、多源、成对等模式应结合基础心病和症状报告。","mechanism":"异位激动部位不同产生不同心电形态。","avoid":"不能把全部早搏都等同室颤前兆，也不能忽略危险组合。","numbers":"","source":"D06:P0010–P0015、P0034–P0048、P0061","id":"row-2"},{"name":"房颤与脉搏短绌","cues":"绝对不齐、f波、心率与脉率不同","content":"同步评价心室率、血压和症状，并按要求同时测心率和脉率。长期另关注血栓栓塞和抗凝治疗的出血观察。","mechanism":"不规则心室充盈使部分收缩不能形成可触脉搏。","avoid":"只摸脉不能最终确诊房颤。","numbers":"","source":"D06:P0010–P0015、P0034–P0048、P0061","id":"row-3"},{"name":"室颤和不稳定心律","cues":"意识突失、循环消失或严重低灌注","content":"先按反应、呼吸和循环状态启动专业急救配合，准备除颤等设备。心电判读与救治并行，连续记录恢复和复发。","mechanism":"无效心室电活动不能维持有效泵血。","avoid":"不能等待完整图纸或常规查房再处理。","numbers":"","source":"D06:P0010–P0015、P0034–P0048、P0061","id":"row-4"},{"name":"心肌标志物、BNP与超声","cues":"胸痛、心衰或结构病变","content":"肌钙蛋白看动态与缺血证据，CK-MB等可提供补充信息；BNP反映负荷并受肾功能等影响。超声看结构、瓣膜及功能，不能拿一个舒张参数定全部心功能。","mechanism":"损伤、负荷和结构是不同证据维度。","avoid":"标志物升高不都来自同一病因。","numbers":"","source":"D06:P0010–P0015、P0034–P0048、P0061","id":"row-5"},{"name":"造影、CVP与心包检查","cues":"冠脉病变、容量灌注或压塞疑问","content":"冠脉造影回答病变位置程度，CVP需与血压、尿量及临床共同解释。心包超声及必要穿刺分别用于识别积液和相关诊疗配合。","mechanism":"单项压力不能完整反映血容量及泵功能。","avoid":"不以一个CVP数值独立决定补液或去液。","numbers":"","source":"D06:P0010–P0015、P0034–P0048、P0061","id":"row-6"}],"question":"同样心悸，哪些改变需要先看循环而不是只数心率？"},{"id":"card-medicines","title":"循环药物与观察矩阵","axis":"treatment","common":"按强心、去淤血、血管、神经激素和抗栓目的区分。","rows":[{"name":"利尿剂","cues":"心衰淤血或水肿","content":"观察尿量与体重变化，同时复查血压、肾功能和电解质。乏力、口渴、头晕或心律变化应同时考虑容量与电解质偏移。","mechanism":"去液缓解淤血，但过量可减少灌注。","avoid":"不能只按尿量判断全部疗效。","numbers":"","source":"D06:P0068–P0075、P0112、P0116、P0120–P0137；NICE CG187","id":"row-1"},{"name":"RAAS相关药、MRA与SGLT类","cues":"慢性心衰长期治疗","content":"明确处方类别与目的，观察血压、肾功能和血钾。SGLT类还需关注容量、感染及相关代谢风险，出现不适及时联系治疗团队。","mechanism":"长期治疗不仅缓解症状，还调节病理性负荷与代谢通路。","avoid":"ACEI与ARB不能因都在同一框架就当作必须合用。","numbers":"","source":"D06:P0068–P0075、P0112、P0116、P0120–P0137；NICE CG187","id":"row-2"},{"name":"β阻滞剂和降压药","cues":"稳定长期管理或血压控制","content":"核对心率、血压、症状及是否处于急性失代偿阶段。变换体位缓慢，解释不可自行停改药，并比较用药后的头晕及灌注。","mechanism":"心率与血管阻力改变可影响心排量和耐受。","avoid":"急性不稳定阶段不能机械沿用稳定期加药思路。","numbers":"","source":"D06:P0068–P0075、P0112、P0116、P0120–P0137；NICE CG187","id":"row-3"},{"name":"硝酸酯、急性心衰支持","cues":"缺血胸痛或急性淤血","content":"硝酸酯等用后观察血压、头痛及胸痛变化；有低氧时配合氧疗或必要通气。急性支持同步关注循环，不能只追求症状暂时缓解。","mechanism":"降低负荷可减轻缺血或淤血，但低压时可能降低灌注。","avoid":"急性心衰不常规使用阿片类，酒精湿化不作人人必选。","numbers":"","source":"D06:P0068–P0075、P0112、P0116、P0120–P0137；NICE CG187","id":"row-4"},{"name":"抗血小板、抗凝与再灌注","cues":"急性冠脉或房颤栓塞风险","content":"区分抗血小板、抗凝及再灌注的治疗目的。观察出血、穿刺部位、胸痛和再灌注相关心律变化，记录给药与病程时间。","mechanism":"血栓形成环节和治疗时机决定不同路径。","avoid":"不能把溶栓写成全部胸痛必做。","numbers":"","source":"D06:P0068–P0075、P0112、P0116、P0120–P0137；NICE CG187","id":"row-5"},{"name":"洋地黄相关观察","cues":"服用后胃肠不适、视物或心律改变","content":"联系用药史、肾功能及电解质，记录脉搏和心电变化并及时报告。怀疑毒性时配合核查药物及相应检查，不能自行追加给药。","mechanism":"治疗窗、肾排泄和电解质共同影响毒性风险。","avoid":"一种心电外观不能单独确诊全部中毒。","numbers":"","source":"D06:P0068–P0075、P0112、P0116、P0120–P0137；NICE CG187","id":"row-6"}],"question":"不同药类出现头晕、乏力或心律改变时先核对什么？"},{"id":"card-care","title":"护理P-E、饮食与活动条件","axis":"nursing","common":"同一个诊断名称要配不同相关因素和证据。","rows":[{"name":"气体交换与体液过多","cues":"肺水肿，或颈静脉水肿体重增加","content":"左心肺淤血可写气体交换受损，并用低氧与呼吸表现支持。右心或容量潴留证据支持体液过多，记录体重、出入量、水肿和腹围。","mechanism":"肺交换障碍与体循环容量负荷不能互相替代。","avoid":"不能只因呼吸困难就列全部水肿诊断。","numbers":"","source":"D06:P0049–P0067、P0082–P0116、P0135–P0145；PDF05视觉核查","id":"row-1"},{"name":"疼痛、便秘与皮肤风险","cues":"胸痛、头痛、卧床或水肿","content":"胸痛记录缺血线索，头痛联系血压及神经症状。卧床者预防用力排便和压力损伤，兼顾水肿皮肤、生活协助和排泄习惯。","mechanism":"疼痛增加负荷，用力和受压也会影响循环。","avoid":"急性胸痛不只写安慰和分散注意。","numbers":"","source":"D06:P0049–P0067、P0082–P0116、P0135–P0145；PDF05视觉核查","id":"row-2"},{"name":"受伤与电解质失衡危险","cues":"晕厥、降压后头晕或利尿治疗","content":"节律病关注晕厥与跌倒，降压后关注体位性不适。利尿、肾损害或相关药物者观察钾钠和心律，护理相关因素应写具体治疗或机制。","mechanism":"循环波动和电解质改变可同时造成头晕与心律异常。","avoid":"不能把风险名称当作已经发生问题的全部描述。","numbers":"","source":"D06:P0049–P0067、P0082–P0116、P0135–P0145；PDF05视觉核查","id":"row-3"},{"name":"饮食条件树","cues":"稳定高血压、心衰水肿或急性缺血","content":"一般管理减少过量盐脂并合理分餐；明显淤血者结合容量记录执行水盐计划。急性不稳定或需操作时依吞咽及诊疗要求安排摄入，缓解后恢复合适营养。","mechanism":"过量钠水增加负荷，摄入不足又影响恢复。","avoid":"不统一禁水、禁食，也不因低盐就自行补钾。","numbers":"","source":"D06:P0049–P0067、P0082–P0116、P0135–P0145；PDF05视觉核查","id":"row-4"},{"name":"康复与随访","cues":"稳定、出院或抗凝治疗中","content":"按心功能和症状组织活动，教会记录体重、血压及心率。新发胸痛、气促水肿加重、晕厥或出血应及时联系专业人员；抗凝者特别辨识黑便与黏膜出血。","mechanism":"连续记录有助于及早发现淤血与药物风险。","avoid":"病情好转不能自行停长期药物。","numbers":"","source":"D06:P0049–P0067、P0082–P0116、P0135–P0145；PDF05视觉核查","id":"row-5"}],"question":"体液过多、活动无耐力、受伤危险分别怎样落到病种？"},{"id":"card-drug-classes","title":"循环药物分层与不良反应对照","axis":"treatment","common":"每类药背作用、适用问题、观察和不适用条件。","rows":[{"name":"袢、噻嗪与保钾利尿剂","cues":"容量潴留或相关血压治疗","content":"呋塞米等袢利尿与噻嗪类关注低钾、低钠和容量不足，部分药还需关注耳部或代谢不适。螺内酯等MRA关注高钾、肾功能和乳房相关反应，复查随药类不同安排。","mechanism":"不同肾单位作用点与激素通路产生不同电解质影响。","avoid":"MRA与ACEI等可在合适心衰方案中合用并严密监测，不能把配伍一律写禁止。","numbers":"","source":"PDF06四段逐图核查；D06:P0068–P0075；NICE NG106；NHS SPS","id":"row-1"},{"name":"地高辛及毒性风险","cues":"相应心衰或房颤治疗","content":"结合心率心电、肾功能、钾镁钙与用药核查风险，老年和肾功能不全者尤其关注。新发食欲差恶心、视色或心律变化及时报告，按临床需要检查药物浓度。","mechanism":"药物浓度及电解质共同影响心肌电活动。","avoid":"鱼钩样ST本身不能单独证明中毒，也不按一个统一心率擅停或加药。","numbers":"","source":"PDF06四段逐图核查；D06:P0068–P0075；NICE NG106；NHS SPS","id":"row-2"},{"name":"硝酸酯与硝普钠","cues":"缺血胸痛或需静脉血管扩张","content":"硝酸酯观察头痛、面红及低压，静脉血管扩张药核对输注系统、保护要求和速度。硝普钠等还需按制剂和方案关注毒性及器官功能，出现异常及时报告。","mechanism":"血管扩张减轻负荷，但过量可降低灌注；不同药的代谢风险不同。","avoid":"不将其写作所有高血压急症唯一首选，不机械照固定时长决定毒性。","numbers":"","source":"PDF06四段逐图核查；D06:P0068–P0075；NICE NG106；NHS SPS","id":"row-3"},{"name":"抗血小板与抗凝","cues":"冠脉病、支架或栓塞风险方案","content":"阿司匹林、氯吡格雷等关注黏膜、皮肤及消化道出血；抗凝则按具体药核对凝血或肾功能等监测。双联或联合方案需注明目的和期限，宣教异常出血就医。","mechanism":"血小板与凝血级联是不同环节，联用改变出血风险。","avoid":"华法林监测目标随适应证和瓣膜类型，不统一一个INR范围。","numbers":"","source":"PDF06四段逐图核查；D06:P0068–P0075；NICE NG106；NHS SPS","id":"row-4"},{"name":"溶栓前、中、后","cues":"经专业评估拟溶栓","content":"治疗前配合禁忌证、出血史及相关检查，治疗中核对通路并观察出血、过敏和循环。治疗后比较症状、心电及标志物等再灌注信息，继续监护和准备急救。","mechanism":"恢复灌注可能伴出血和再灌注性心律变化。","avoid":"不是所有ST抬高、胸痛或卒中都能溶栓，不照图列禁忌自行决定。","numbers":"","source":"PDF06四段逐图核查；D06:P0068–P0075；NICE NG106；NHS SPS","id":"row-5"},{"name":"β阻滞与CCB亚类","cues":"血压、缺血、节律或心衰长期方案","content":"β阻滞剂观察过慢心率、传导、低压和气道耐受；避免自行骤停。二氢吡啶CCB侧重血管作用，非二氢吡啶还抑制心率传导和收缩，需联系心功能选择。","mechanism":"同为降压药，对血管与心脏作用权重不同。","avoid":"射血分数降低心衰避免维拉帕米/地尔硫䓬等，不把所有CCB都写成相同禁忌。","numbers":"","source":"PDF06四段逐图核查；D06:P0068–P0075；NICE NG106；NHS SPS","id":"row-6"},{"name":"ACEI与ARB的相同和不同","cues":"心衰、蛋白尿或高血压相关方案","content":"两类均观察血压、肌酐和血钾，ACEI特别留意干咳和血管性水肿。出现不能耐受反应时由治疗团队调整，解释妊娠及肾血管等特殊情况需预先核对。","mechanism":"两类均影响RAAS，但作用环节不同。","avoid":"不能把ACEI与ARB当作应常规联用，也不能用旧表固定eGFR变化自行停药。","numbers":"","source":"PDF06四段逐图核查；D06:P0068–P0075；NICE NG106；NHS SPS","id":"row-7"}],"question":"同为利尿或扩血管，为什么要分别看钾、听力和血压？"},{"id":"card-pe-activity","title":"同一问题：活动无耐力的病种差异","axis":"nursing","common":"共享护理：比较活动前后心率、血压、气促、胸痛和疲劳；稳定后递进，不耐受停止复评。","rows":[{"name":"心衰","cues":"活动气促乏力，休息后缓解程度不一","content":"活动无耐力：与心排量受限、氧供需失衡有关。按休息、一般或较小活动即出现症状分层，协助生活并观察呼吸、容量及恢复时间。","mechanism":"泵功能受限使活动时供氧不能满足需求。","avoid":"有静息心衰或灌注不稳时不能继续推进训练。","numbers":"","source":"D06:P0082–P0109；PDF05逐图核查","id":"row-1"},{"name":"心肌缺血","cues":"活动诱发胸痛胸闷","content":"活动无耐力：与心肌氧供需失衡有关。记录诱发负荷、胸痛起止及心电血压反应，在专业康复计划内递进。","mechanism":"冠脉供血不能随活动需求充分增加。","avoid":"不能把忍痛坚持当耐量训练。","numbers":"","source":"D06:P0082–P0109；PDF05逐图核查","id":"row-2"},{"name":"心律失常","cues":"活动时心悸头晕，或心率反应异常","content":"活动无耐力：与节律异常导致有效泵血受影响有关。观察心率心律和灌注，出现头晕或近晕厥停止并复评，必要时监护下活动。","mechanism":"频率与充盈变化可降低有效心排量。","avoid":"不能只凭症状暂缓就忽略危险心律。","numbers":"","source":"D06:P0082–P0109；PDF05逐图核查","id":"row-3"},{"name":"肥厚梗阻或其他结构病","cues":"劳力胸痛、晕厥或结构异常","content":"活动无耐力：与结构限制泵血或心肌氧供不足有关。根据病型和专科风险安排活动，尤其注意劳力晕厥和胸痛。","mechanism":"流出受限与负荷变化可影响灌注。","avoid":"不能照搬普通高血压的运动计划。","numbers":"","source":"D06:P0082–P0109；PDF05逐图核查","id":"row-4"}],"question":"心衰、心肌缺血和节律异常各怎样写P-E？"}],"drills":[{"id":"card-drill-after","title":"治疗后出现新问题","stem":"一位心衰患者用药后气促缓解，却出现恶心、头晕及新发不规则心搏。","prompt":"为什么不能只写心衰好转？","answer":["记录心率心律、血压及灌注，核对近期药物、肾功能和电解质。","若有洋地黄等用药，需报告并配合相应毒性与其他心律原因评估。","评价呼吸改善与药物安全两个维度，不自行追加药物。"],"source":"D06:P0137、P0152；原创变式"},{"id":"card-drill-load","title":"体位随着灌注改变","stem":"原来端坐气促的患者后来四肢湿冷、血压下降、尿量减少。","prompt":"原先的体位和去液思路为什么需要重新评价？","answer":["出现低灌注线索，应立即报告并复评循环。","体位与治疗配合需同时考虑呼吸和血压，不继续机械套垂腿。","记录意识、末梢、尿量及治疗反应，配合进一步急救。"],"source":"D06:P0120–P0123；原创变式"},{"id":"card-drill-valve","title":"瓣膜病里的整体护理","stem":"既往瓣膜病者出现不能平卧、颈静脉充盈、腿肿和食欲下降。","prompt":"把肺淤血、体循环淤血和营养问题分组，再写优先原则。","answer":["气促和不能平卧支持肺淤血方向，颈静脉和水肿支持体循环负荷。","观察血压、末梢和尿量判断灌注，体位不能脱离血压机械套用。","营养问题联系胃肠淤血与摄入，整体护理再加入活动及药物观察。"],"source":"D06:P0019–P0024、P0051–P0067；M032/M034题型目标；原创变式"},{"id":"card-drill-atypical","title":"上腹痛也要联系心肌缺血","stem":"一位有血管风险者持续上腹不适并出冷汗、近乎晕厥，初步心电出现缺血性变化。","prompt":"为什么不能继续只按胃痛护理？","answer":["疼痛部位不典型不能排除心肌缺血，结合心电与标志物动态评估。","先看灌注、节律和呼吸，持续恶化需立即升级。","记录疼痛时间及治疗反应，配合再灌注等专业评估，不把溶栓作为所有上腹痛必做。"],"source":"D06:P0017–P0018、P0035–P0038、P0121–P0123；M033题型目标；原创变式"}],"references":[{"title":"NICE 急性心衰","url":"https://www.nice.org.uk/guidance/cg187/chapter/Recommendations"},{"title":"NICE 慢性心衰","url":"https://www.nice.org.uk/guidance/ng106/chapter/Recommendations"},{"title":"NHS SPS 地高辛监测","url":"https://sps.nhs.uk/monitorings/digoxin-monitoring/"}]},"digestive":{"title":"消化系统：出血、炎症与肝脏代谢分线学习","intro":"先辨出血与腹膜危险，再按胃食管、肠道、肝脏和胰腺组织疾病；饮食、用药和意识观察随病程变化。","framework":[{"id":"dig-bleed","title":"出血观察不能只看血量","cue":"呕血、黑便或头晕冷汗","answer":"记录血液及粪便颜色、量、时间和频次，同时连续观察意识、血压、心率、皮温与尿量。配合血常规、凝血及备血，比较复苏后灌注与再出血表现。","why":"外观出血量和早期血红蛋白都可能低估真实失血。","source":"D09:P0055、P0083、P0127–P0132"},{"id":"dig-abdomen","title":"腹痛联动四组信息","cue":"上腹痛、呕吐或腹胀","answer":"先写部位、性质、持续与放射，再联系进食节律、呕吐物和排便。突发全腹痛与腹膜刺激考虑穿孔等危险，持续上腹向背放射结合胰酶和影像，呕宿食注意胃潴留及电解质。","why":"部位与节律帮助定位，新的腹膜或循环征象意味着病程改变。","source":"D09:P0041–P0054、P0086–P0087、P0119"},{"id":"dig-liver","title":"肝病同时看四条线","cue":"黄疸、腹水、出血倾向或认知改变","answer":"观察肝功能减退、门脉高压、容量营养和神经行为变化；每日比较体重腹围及出入量。发现意识变化时找感染、出血、便秘、药物和电解质诱因，并同时保护气道和安全。","why":"肝病并发症相互诱发，腹水处理和消化道出血也可改变有效循环及代谢。","source":"D09:P0049–P0051、P0084–P0085、P0122–P0124"},{"id":"dig-care","title":"护理框架按当前表现填充","cue":"题目要求整体护理","answer":"按体位休息、出血腹部监测、摄入途径营养、药物反应、皮肤口腔、安全排泄、并发症与随访组织。每一项注明适用疾病和当前证据，最后评价疼痛、灌注、摄入、意识或腹水的具体变化。","why":"共性框架避免遗漏，病种条件避免所有消化病写同一种禁食和高蛋白。","source":"D09:P0071–P0145"}],"contrasts":[{"id":"dig-upper","title":"胃食管与溃疡鉴别","axis":"diagnosis","common":"把症状节律、黏膜病理与并发症分层。","rows":[{"name":"胃食管反流与反流性食管炎","cues":"烧心反酸，平卧或餐后加重","content":"反流病可有症状而内镜未见明显炎症，食管炎需联系内镜表现。按需要配合pH或动力检查，并观察吞咽困难等异常。","mechanism":"胃内容物反流刺激食管，黏膜损伤程度不同。","avoid":"不能用一次pH低值或反酸症状替代完整评估。","numbers":"","source":"D09:P0006–P0045、P0060–P0067","id":"row-1"},{"name":"急性胃炎与应激损伤","cues":"NSAIDs、饮酒或严重应激后上腹不适出血","content":"追问药物及应激背景，结合胃镜了解充血糜烂等损伤。烧伤和中枢神经病变相关应激溃疡按诱因区分，重点观察出血。","mechanism":"黏膜屏障受损和应激影响黏膜防御。","avoid":"不能把所有胃痛都写成消化性溃疡。","numbers":"","source":"D09:P0006–P0045、P0060–P0067","id":"row-2"},{"name":"慢性胃炎分型","cues":"Hp背景，或胃体萎缩及贫血","content":"非萎缩与萎缩依内镜和病理区分；多灶性与自身免疫类型结合部位、Hp/自身抗体及贫血。胃酸和胃泌素变化需与类型对应，不只背一个胃炎名。","mechanism":"不同黏膜细胞和病因受损产生不同分泌及营养影响。","avoid":"不能只凭胃镜外观确定全部病理分型。","numbers":"","source":"D09:P0006–P0045、P0060–P0067","id":"row-3"},{"name":"胃与十二指肠溃疡","cues":"节律性上腹痛","content":"胃溃疡较常餐后痛，十二指肠溃疡较常空腹或夜间痛，但以检查证实。观察疼痛规律突然改变、呕血黑便和呕宿食，分别联系穿孔、出血或梗阻。","mechanism":"酸与黏膜防御失衡造成溃疡，部位影响典型症状。","avoid":"疼痛规律不是绝对鉴别标准。","numbers":"","source":"D09:P0006–P0045、P0060–P0067","id":"row-4"},{"name":"穿孔与幽门梗阻","cues":"全腹急剧疼痛，或反复宿食呕吐","content":"穿孔重点看腹膜刺激及循环，配合影像与急腹症评估。幽门梗阻重点看胃潴留、脱水和电解质酸碱，记录呕吐及减压液。","mechanism":"穿孔污染腹腔，梗阻妨碍排空并丢失胃液。","avoid":"没有游离气不能排除穿孔，术后呕吐也不都等于幽门梗阻。","numbers":"","source":"D09:P0006–P0045、P0060–P0067","id":"row-5"},{"name":"胃癌","cues":"消瘦、黑便、持续上腹症状或淋巴结异常","content":"结合胃镜取样及分期评估，而非只看食欲下降。护理关注摄入、贫血和出血，并与后续围术期学习衔接。","mechanism":"占位和黏膜损伤可影响摄入并导致慢性失血。","avoid":"症状轻或不典型不能排除恶性病变。","numbers":"","source":"D09:P0006–P0045、P0060–P0067","id":"row-6"}],"question":"烧心、餐后痛和突发全腹剧痛为什么不能用同一答案？"},{"id":"dig-bowel-liver","title":"肠道、肝脏与胰腺病种对照","axis":"diagnosis","common":"定位疾病后再找并发症与病程阶段。","rows":[{"name":"溃疡性结肠炎与克罗恩病","cues":"脓血便，或节段病变伴瘘管","content":"UC重点联系结肠黏膜炎症与脓血便，CD关注节段、透壁和瘘管等线索。以肠镜、病理及病变分布综合鉴别，并记录排便、营养和腹痛。","mechanism":"炎症部位与深度不同形成不同并发症。","avoid":"不能仅凭一次腹泻或肉芽肿词语定型。","numbers":"","source":"D09:P0046–P0055","id":"row-1"},{"name":"肠结核","cues":"慢性腹痛排便改变伴低热盗汗消瘦","content":"结合结核背景、腹部及全身表现，再看肠镜病理和病原学。评估营养和梗阻等变化，并与CD等病变鉴别。","mechanism":"肠道慢性感染可形成溃疡、增生及瘢痕。","avoid":"PPD阳性不能独立确诊肠结核。","numbers":"","source":"D09:P0046–P0055","id":"row-2"},{"name":"肝硬化","cues":"肝功能减退与门脉高压组合","content":"把黄疸、凝血及营养变化与脾大、腹水、静脉曲张分开归类。每次复评出血、感染、肾功能和意识改变，不能只量腹围。","mechanism":"肝实质功能下降和门脉血流阻力增大并存。","avoid":"蜘蛛痣或腹水单项不能确诊肝硬化。","numbers":"","source":"D09:P0046–P0055","id":"row-3"},{"name":"原发性肝癌","cues":"慢性肝病背景、肝区痛或占位","content":"结合超声及进一步影像、肿瘤标志物与必要病理评价。记录疼痛、营养及出血等变化，并依治疗方式连接围术期或介入护理。","mechanism":"肿瘤生长和基础肝病共同影响表现。","avoid":"AFP升高不是所有肝癌的必有条件，也不能单项确诊。","numbers":"","source":"D09:P0046–P0055","id":"row-4"},{"name":"肝性脑病","cues":"肝病背景的睡眠、性格、认知或意识改变","content":"从轻微行为变化到明显定向和意识障碍连续观察，记录扑翼样震颤等表现。查诱因并排除低糖、药物和其他神经原因，血氨只是辅助信息。","mechanism":"肝脏处理毒性物质能力下降与分流等共同影响脑功能。","avoid":"血氨不是单独诊断或分级工具。","numbers":"","source":"D09:P0046–P0055","id":"row-5"},{"name":"急性胰腺炎","cues":"持续上腹痛向背放射及酶学影像异常","content":"将疼痛、胰酶和影像组合，动态观察循环、呼吸、尿量和腹部。皮肤瘀斑、低钙或器官功能变化提示需要评估严重度，不能只盯淀粉酶。","mechanism":"胰腺炎症和渗漏可造成局部损伤及全身反应。","avoid":"酶升高幅度不能独立判定全部严重度。","numbers":"","source":"D09:P0046–P0055","id":"row-6"},{"name":"上消化道出血","cues":"呕血黑便伴灌注变化","content":"先维持气道及灌注评估，再查溃疡、静脉曲张等病因。复苏后新鲜出血、血流动力学再次恶化或血象持续变化需要重评再出血。","mechanism":"失血影响循环，呕血和意识障碍增加误吸危险。","avoid":"黑便持续或早期Hb正常都不能单独判定是否继续大量出血。","numbers":"","source":"D09:P0046–P0055","id":"row-7"}],"question":"哪些临床和病理线索帮助区分炎症性肠病及肝胰疾病？"},{"id":"dig-tests","title":"检查项目怎样与疾病配对","axis":"labs","common":"检查目的分为出血程度、炎症病因、结构和病理。","rows":[{"name":"出血与器官功能","cues":"呕血、肝病或循环异常","content":"血常规和凝血用于失血及止血风险评价，结合动态而非一次结果。肝肾功能、电解质和血气帮助看全身影响，需备血者配合血型与交叉配血。","mechanism":"血液稀释和时间变化影响早期血象。","avoid":"不以初次Hb未降排除严重失血。","numbers":"","source":"D09:P0056–P0070","id":"row-1"},{"name":"内镜、活检与Hp","cues":"胃炎、溃疡、胃癌或结肠炎","content":"胃镜定位上消化道黏膜病变并可配合止血，取样回答病理或Hp问题。肠镜结合分布及病理判断肠道炎症和肿瘤，核对准备、用药及风险。","mechanism":"镜下外观和病理是相互补充的证据。","avoid":"大出血先复苏和评估，急性重症肠病不能机械安排常规肠镜。","numbers":"","source":"D09:P0056–P0070","id":"row-2"},{"name":"影像、pH和测压","cues":"穿孔梗阻、肝胆胰或反流问题","content":"立位片可找游离气和液平，超声CT/MRI评价肝胆胰及并发症。pH监测关注反流负荷，测压关注动力，不能把两种检查互代。","mechanism":"气体、结构和功能需要不同检测方法。","avoid":"检查适应证与准备不能一律写禁食同样时长。","numbers":"","source":"D09:P0056–P0070","id":"row-3"},{"name":"腹水与肝病取样","cues":"腹水新变化或病因不明","content":"腹水检查帮助辨别感染和其他原因，配合无菌取样及术后观察。肝穿刺在适用情境提供病理，需先评估凝血和出血风险。","mechanism":"同是腹水，感染和门脉高压等原因处理重点不同。","avoid":"并非所有肝硬化或肝癌都必须穿刺。","numbers":"","source":"D09:P0056–P0070","id":"row-4"}],"question":"同是胃镜、肠镜或腹部影像，它们各补哪类证据？"},{"id":"dig-drugs","title":"药物类别、目的与护理","axis":"treatment","common":"先区分抑酸黏膜保护、止血路径和降氨治疗。","rows":[{"name":"抑酸、抗酸和黏膜保护","cues":"溃疡或上消化道病变","content":"PPI/H2类抑制酸分泌，抗酸药中和现有酸，黏膜保护药保护受损黏膜。核对具体药品与进餐关系，观察腹部症状及药物间隔，铋剂可使粪便颜色改变需与出血表现合看。","mechanism":"作用环节不同，服用安排不能互相套用。","avoid":"不把所有PPI、铋剂和H2制剂统一成同一服药时点。","numbers":"","source":"D09:P0094–P0117；NICE CG141、NG104","id":"row-1"},{"name":"Hp根除与促动力","cues":"Hp相关溃疡，或排空/反流问题","content":"根除需完整联合方案并按计划复查，不因症状减轻就停药。促动力药着眼排空和动力，观察腹部症状与耐受，不能代替评估机械梗阻。","mechanism":"去除病因与改善动力解决不同问题。","avoid":"药敏、既往用药和制剂影响方案，不自行拼药。","numbers":"","source":"D09:P0094–P0117；NICE CG141、NG104","id":"row-2"},{"name":"出血的病因路径","cues":"非静脉曲张或静脉曲张出血","content":"非静脉曲张重点配合内镜及相应抑酸等治疗，静脉曲张另有降低门脉相关血流和止血路径。持续给药要避免意外中断，并观察灌注、腹痛及循环不良反应。","mechanism":"溃疡黏膜血管和门脉高压不是同一出血机制。","avoid":"不能将一类止血药用于所有出血病因。","numbers":"","source":"D09:P0094–P0117；NICE CG141、NG104","id":"row-3"},{"name":"腹水利尿与降氨治疗","cues":"腹水或肝性脑病","content":"利尿观察体重、尿量、电解质与肾功能，过快去液需警惕循环不足。乳果糖等按处方调整并记录排便及意识，避免腹泻造成新的水电解质问题。","mechanism":"去液影响有效循环，肠道排便及酸化可影响氨负荷。","avoid":"不统一长期禁蛋白，也不常规用镇静掩盖意识变化。","numbers":"","source":"D09:P0094–P0117；NICE CG141、NG104","id":"row-4"},{"name":"胰腺炎支持与营养","cues":"腹痛、呕吐或摄入不足","content":"配合镇痛和循环支持，并记录器官功能和液体反应。能否经口或肠内营养看呕吐、耐受和病情，不能因为诊断胰腺炎就固定禁食。","mechanism":"长期摄入不足增加营养风险，支持需兼顾肠道与全身。","avoid":"有明确呕吐等原因时另行安排，不机械照固定禁食天数。","numbers":"","source":"D09:P0094–P0117；NICE CG141、NG104","id":"row-5"}],"question":"药物出现黑便或腹泻时如何联系机制与病情？"},{"id":"dig-nursing","title":"护理诊断横向对照与摄入条件","axis":"nursing","common":"先写机制与题干证据，再选择共性框架中的个性条目。","rows":[{"name":"营养失调的不同因素","cues":"出血禁食、肝病食欲差、胰腺炎呕吐或溃疡疼痛","content":"出血联系失血及阶段性摄入减少，肝病联系食欲与吸收，胰腺炎联系呕吐和摄入障碍。分别记录摄入、体重和营养反应，不只写营养不足名称。","mechanism":"同一营养问题在不同病种的丢失与摄入环节不同。","avoid":"腹水体重不能直接等同营养改善。","numbers":"","source":"D09:P0071–P0093、P0118–P0145；PDF11视觉核查","id":"row-1"},{"name":"体液不足与体液过多","cues":"失血冷汗，或腹水水肿","content":"出血支持体液不足及失血性休克合作问题，评价灌注和尿量。肝硬化腹水支持体液分布及容量问题，但仍需判断有效循环是否不足。","mechanism":"组织间隙积液可以与血管内灌注不足并存。","avoid":"不能见腹水就忽略休克，也不能只看黑便不看循环。","numbers":"","source":"D09:P0071–P0093、P0118–P0145；PDF11视觉核查","id":"row-2"},{"name":"饮食和体位条件树","cues":"反流、出血、腹水、脑病或胰腺炎","content":"反流避免餐后立即平卧，出血按活动性、吞咽和止血恢复安排途径与性状。腹水执行合适水盐计划；脑病避免长期一概禁蛋白；胰腺炎在可耐受时恢复合适摄入。","mechanism":"体位影响反流和呼吸，摄入需兼顾安全与营养。","avoid":"不把全部消化病都写禁食禁水或高蛋白。","numbers":"","source":"D09:P0071–P0093、P0118–P0145；PDF11视觉核查","id":"row-3"},{"name":"意识、皮肤与受伤风险","cues":"脑病、黄疸瘙痒或长期卧床","content":"行为意识异常者看护、安全防跌及气道保护，并记录诱因处理后变化。黄疸瘙痒温和清洁、润肤和修剪指甲，卧床同时预防压力损伤和感染。","mechanism":"认知受损与瘙痒受压共同增加伤害。","avoid":"不能只用约束替代寻找原因和持续评估。","numbers":"","source":"D09:P0071–P0093、P0118–P0145；PDF11视觉核查","id":"row-4"},{"name":"三腔二囊管与腹水穿刺配合","cues":"特殊止血装置或放腹水","content":"三腔管重点核对固定、气道、压力监测要求和止血效果，观察移位及黏膜损伤风险。腹水操作前后比较血压、症状和腹围，观察局部出血及循环变化。","mechanism":"装置移位可威胁气道，放液可改变循环。","avoid":"不背一个固定放气周期或放液上限用于全部装置和病情。","numbers":"","source":"D09:P0071–P0093、P0118–P0145；PDF11视觉核查","id":"row-5"},{"name":"随访与再发识别","cues":"出院或慢性病复发风险","content":"教会识别新鲜呕血、晕厥、黑便伴全身不适及行为改变。溃疡按计划完成Hp治疗复查，肝病继续监测肝功能、肿瘤及静脉曲张风险，避免自行用损肝或NSAIDs类药物。","mechanism":"再出血与肝病恶化早期可能先出现行为或循环变化。","avoid":"不能以症状暂缓替代复查。","numbers":"","source":"D09:P0071–P0093、P0118–P0145；PDF11视觉核查","id":"row-6"}],"question":"体液不足、体液过多与营养问题能否同时存在？"}],"drills":[{"id":"dig-drill-rebleed","title":"黑便仍在，怎样判断变化","stem":"止血治疗后的患者仍解黑便，随后又出现心率加快、站立头晕和尿量减少。","prompt":"哪些信息比单纯便色更重要？","answer":["比较血压、心率、意识、皮温和尿量的动态，报告新出现低灌注。","记录有无新鲜呕血及血象趋势，配合复评再出血和复苏需要。","黑便本身不能单独证明继续大量出血，但伴灌注恶化不能忽略。"],"source":"D09:P0083、P0150；原创变式"},{"id":"dig-drill-liver","title":"同是腹水，不能只写利尿","stem":"肝硬化患者腹水增加，近两日嗜睡，家属说排便少且刚服了助眠药。","prompt":"补充哪些评估与护理？","answer":["观察认知、定向、意识及气道，及时报告脑病或其他意识异常。","核对便秘、感染、出血、用药和电解质等诱因，配合检查。","容量、营养和安全同时管理，不能以镇静或长期禁蛋白替代病因处理。"],"source":"D09:P0084–P0085、P0122–P0124；原创变式"}],"references":[{"title":"NICE 上消化道出血","url":"https://www.nice.org.uk/guidance/CG141/Chapter/Recommendations"},{"title":"NICE 胰腺炎与营养","url":"https://www.nice.org.uk/guidance/ng104/chapter/recommendations"}]},"renal":{"title":"内科泌尿：把蛋白丢失、容量和排泄功能分开","intro":"先辨肾炎、肾病、感染和肾功能变化；护理以容量、电解质、营养及治疗风险为共同框架，再加入每病的机制和观察。","framework":[{"id":"renal-capacity","title":"容量观察四联","cue":"水肿、少尿、气促或体重变化","answer":"同条件测体重，记录同一时段摄入和排出，观察水肿、血压与呼吸，再联系尿量及肾功能趋势。评估有效循环，出现气促、湿啰音、低压或意识变化及时报告；不能只按腿肿决定补液或利尿。","why":"组织间水肿与血管内有效容量并不总一致。","source":"D07:P0090–P0103；TEXTBOOK renal basics/agn/nephrotic"},{"id":"renal-electrolyte","title":"少尿时先找危险","cue":"尿量下降、肌无力、心律或意识异常","answer":"复核尿量时间与导尿通畅，跟踪肌酐、钾和酸碱；疑高钾时同时看心电及循环。配合保护心肌、转移钾和清除钾等治疗时分别观察心律、血糖及电解质反向变化。","why":"排泄下降可使钾、酸和水分潴留，而降钾各路径作用不同。","source":"D07:P0095、P0104–P0118；TEXTBOOK renal aki/ckd；SUPPLEMENTS"},{"id":"renal-protein","title":"蛋白尿—水肿—营养连起来","cue":"大量蛋白尿、低白蛋白和水肿","answer":"记录蛋白丢失、白蛋白、摄入和水肿，解释低胶体渗透压与水钠潴留。饮食不能单为补回尿蛋白就无限增加蛋白，需按肾功能及透析状态安排，同时保证能量。","why":"过多蛋白负荷与摄入不足均有风险，水肿体重也会掩盖消瘦。","source":"D07:P0007–P0008、P0119–P0120、P0188；TEXTBOOK renal nephrotic/ckd"},{"id":"renal-followup","title":"标本、药物和随访形成闭环","cue":"尿检异常、激素治疗或长期肾病","answer":"说明清洁中段尿和定时尿的目的与完整性，记录用药、血压、体重及尿量。核对肾毒性药和免疫抑制风险，按计划复查尿蛋白、肾功能及电解质；出现发热、少尿、气促或通路异常及时联系。","why":"规范标本提高解释可靠性，连续记录帮助发现复发和治疗风险。","source":"D07:P0065–P0081、P0121–P0131、P0165–P0172"}],"contrasts":[{"id":"renal-disease","title":"肾炎、肾病和感染怎么分","axis":"diagnosis","common":"尿液异常先分肾小球、感染和排泄功能，再用病程及检查支持。","rows":[{"name":"急性肾小球肾炎","cues":"感染后血尿、水肿和血压升高","content":"结合感染间隔、尿沉渣、补体及肾功能支持肾炎综合征。急性期重点观察容量、高血压脑病和心衰，症状缓解后仍需随访尿液。","mechanism":"免疫性炎症影响滤过，水钠潴留参与肾炎性水肿。","avoid":"无明显水肿不排除，感染并不等于细菌直接在肾内繁殖。","numbers":"","source":"D07:P0004–P0013；D08:P0004–P0014；TEXTBOOK renal","id":"row-1"},{"name":"急进性与慢性肾炎","cues":"短期肾功能迅降，或长期蛋白血尿高血压","content":"急进性强调恶化速度、少尿及病理/免疫分型，及时专科评估。慢性强调长期病程和可逆加重因素，连续管理血压、蛋白尿和功能。","mechanism":"活动性急损伤与慢性进展需要不同病程证据。","avoid":"不能只凭一次肌酐高低区分两者。","numbers":"","source":"D07:P0004–P0013；D08:P0004–P0014；TEXTBOOK renal","id":"row-2"},{"name":"肾病综合征","cues":"大量蛋白尿、低白蛋白及明显水肿","content":"将蛋白丢失、白蛋白和水肿机制连答，再查病因及感染、血栓和AKI。记录治疗后尿蛋白、体重和营养变化，不能只看腿肿消退。","mechanism":"滤过屏障受损导致蛋白丢失，低胶体压与肾性水钠潴留共同参与。","avoid":"成人标准不能直接套儿童；不是所有病理类型都同一激素方案。","numbers":"成人大量蛋白尿＞3.5 g/24 h、白蛋白＜30 g/L是核心组合。","source":"D07:P0004–P0013；D08:P0004–P0014；TEXTBOOK renal","id":"row-3"},{"name":"膀胱炎与肾盂肾炎","cues":"尿频急痛，或伴高热腰痛和叩击痛","content":"下尿路以局部刺激为主，上尿路常伴全身及肾区表现。结合规范培养和病情评价，观察寒战、低压等全身危险，并完成疗程及复查。","mechanism":"感染部位不同造成局部与全身反应差异。","avoid":"老年或免疫受损者可不典型，尿白细胞本身不是全部确诊。","numbers":"","source":"D07:P0004–P0013；D08:P0004–P0014；TEXTBOOK renal","id":"row-4"},{"name":"AKI与CKD","cues":"新近尿量肌酐变化，或异常持续数月","content":"AKI需要基线和时间窗口，CKD需要长期功能或损伤证据。慢性患者也可能出现急性加重，应追查脱水、感染、梗阻和肾毒药。","mechanism":"急性变化的可逆因素与慢性损伤可叠加。","avoid":"一次eGFR低或双肾大小不能独立完成分型。","numbers":"AKI：48小时Scr增≥26.5 μmol/L，或7天达基线≥1.5倍，或尿量＜0.5 mL/(kg·h)持续≥6小时。","source":"D07:P0004–P0013；D08:P0004–P0014；TEXTBOOK renal","id":"row-5"}],"question":"同是水肿或尿蛋白，哪些线索改变诊断方向？"},{"id":"renal-tests","title":"尿液、滤过、病理与分期","axis":"labs","common":"检查分为损伤定位、功能趋势、病因和操作配合。","rows":[{"name":"尿沉渣与定量","cues":"红白细胞、蛋白或管型异常","content":"尿沉渣帮助区分出血、炎症和肾实质线索；定量蛋白或合适比值评价丢失。标本污染、漏收和时间不准确会影响结果，需要先核对采集。","mechanism":"定性、显微计数和蛋白总量不是同一测量。","avoid":"不能把培养CFU/mL与高倍视野计数混用。","numbers":"","source":"D07:P0014–P0081；D08:P0015–P0082；TEXTBOOK renal basics/ckd","id":"row-1"},{"name":"培养、中段尿和定时尿","cues":"疑感染或需定量","content":"培养尽量按要求在抗菌治疗前留取清洁中段尿，容器内面避免接触。定时尿明确起止并收全，漏收应告知，不用估计量补足。","mechanism":"污染影响病原解释，漏收影响总排泄量。","avoid":"导管培养不从尿袋取；不因采样自行停药。","numbers":"","source":"D07:P0014–P0081；D08:P0015–P0082；TEXTBOOK renal basics/ckd","id":"row-2"},{"name":"Scr、BUN、Ccr与eGFR","cues":"排泄功能或药物耐受评估","content":"看既往基线与变化，BUN同时受摄入、出血和分解影响。Ccr相关收集或试验饮食按检验项目准备，eGFR结合年龄体型和临床解释。","mechanism":"肌酐产生和排出均影响数值，BUN并非肾损伤专属。","avoid":"不能把单一数值当作全部肾功能或直接换算旧表。","numbers":"","source":"D07:P0014–P0081；D08:P0015–P0082；TEXTBOOK renal basics/ckd","id":"row-3"},{"name":"CKD分期与旧指标区别","cues":"长期肾损伤或eGFR下降","content":"现代评估同时看病因、GFR类别和白蛋白尿；G1/G2仍需损伤证据。Ccr或Scr旧阶段不能直接与所有现代GFR类逐格等同，治疗准备还看症状和风险。","mechanism":"相同GFR的风险可因病因及白蛋白尿不同。","avoid":"不能仅因进入G5就立即判定人人需透析。","numbers":"G1≥90；G2 60—89；G3a 45—59；G3b 30—44；G4 15—29；G5＜15，单位mL/(min·1.73 m²)。","source":"D07:P0014–P0081；D08:P0015–P0082；TEXTBOOK renal basics/ckd","id":"row-4"},{"name":"超声、尿路影像与肾活检","cues":"梗阻、结构或病理问题","content":"超声看大小及梗阻，KUB/CT等按结石与结构问题选择；造影及MR尿路检查各有条件。活检用于适用病理问题，术前核对血压凝血，术后观察尿色、腰痛和循环。","mechanism":"结构影像不能替代组织病理，病理也不适合所有病例。","avoid":"不能把肾活检写作全部肾病必做。","numbers":"","source":"D07:P0014–P0081；D08:P0015–P0082；TEXTBOOK renal basics/ckd","id":"row-5"},{"name":"全身并发症检查","cues":"贫血、骨痛、乏力或心律改变","content":"血红蛋白和铁状态帮助评价贫血，钙磷PTH连接骨代谢。电解质、血气和心电帮助识别急性危险，结合症状追踪趋势。","mechanism":"排泄、内分泌和矿物质代谢功能可同时受影响。","avoid":"没有典型心电改变不排除高钾。","numbers":"","source":"D07:P0014–P0081；D08:P0015–P0082；TEXTBOOK renal basics/ckd","id":"row-6"}],"question":"尿蛋白、eGFR与培养各回答什么？"},{"id":"renal-treatment","title":"治疗机制与药物观察","axis":"treatment","common":"按病因、容量、电解质和替代治疗分别说明目的。","rows":[{"name":"高钾与替代治疗","cues":"高钾、心电异常或难控容量酸碱","content":"钙剂用于相应情境保护心肌，胰岛素与葡萄糖等促进钾转移，药物排钾或透析减少体内负荷。同步观察心电、血钾及血糖，难控肺水肿、酸中毒和尿毒症并发症需评估替代治疗。","mechanism":"心肌稳定不等于钾已被清除，细胞内转移可反跳。","avoid":"不能只看单项肌酐或固定阈值决定全部透析时机。","numbers":"","source":"D07:P0106–P0136；TEXTBOOK renal；SUPPLEMENTS","id":"row-1"},{"name":"激素与环磷酰胺","cues":"相应肾小球病免疫治疗","content":"激素关注感染、血糖血压、消化道与骨骼风险，按方案减量不自行骤停。环磷酰胺关注血象、尿血和肝功能，记录用药及不适并配合预防措施。","mechanism":"抑制免疫可控制部分病变，也会削弱感染防御并影响代谢。","avoid":"不同病理不能共用一种方案；饮水措施须服从容量状态。","numbers":"","source":"D07:P0106–P0136；TEXTBOOK renal；SUPPLEMENTS","id":"row-2"},{"name":"利尿与RAAS相关药","cues":"水肿或血压蛋白尿管理","content":"利尿同时看尿量、体重、血压及电解质，低钾低钠或碱中毒表现需报告。ACEI/ARB等用后关注肌酐与血钾，解释按复查调整的重要性。","mechanism":"去液影响有效循环，RAAS调节又可影响钾和滤过。","avoid":"不能见水肿就无限利尿，也不自行联合多种相关药。","numbers":"","source":"D07:P0106–P0136；TEXTBOOK renal；SUPPLEMENTS","id":"row-3"},{"name":"抗感染与贫血骨代谢治疗","cues":"UTI、贫血或钙磷异常","content":"抗菌药核对病原、肾功能、疗程及药物反应；症状消失不自行结束疗程。造血相关治疗观察血红蛋白和血压，矿物质治疗核对进餐要求与钙磷变化。","mechanism":"药物清除和各代谢通路不同，监测指标需对应目标。","avoid":"不把碱化尿液或补钙列成全部患者必用。","numbers":"","source":"D07:P0106–P0136；TEXTBOOK renal；SUPPLEMENTS","id":"row-4"},{"name":"血透与腹透的不同护理","cues":"需要肾脏替代治疗","content":"血透围绕血管通路、前后体重血压及透析中不适；腹透围绕无菌换液、灌入引流、出口与混浊液。出现异常及时联系治疗团队并按要求留样，不能只写定期透析。","mechanism":"两者清除水和溶质的途径不同，感染及容量风险也不同。","avoid":"不自行更改超滤目标、腹透浓度或操作处方。","numbers":"","source":"D07:P0106–P0136；TEXTBOOK renal；SUPPLEMENTS","id":"row-5"}],"question":"保护心肌、转移钾和排出钾为什么不能互相替代？"},{"id":"renal-care","title":"饮食条件树、皮肤和通路护理","axis":"nursing","common":"先判容量、营养和治疗阶段，再填个性措施。","rows":[{"name":"无少尿或明显水肿、未透析","cues":"肾功能及容量相对稳定","content":"不自动严格限水，观察饮水、尿量和血压；盐摄入与血压容量相配。蛋白以合适量和优质来源为主，保证能量，避免把尿蛋白多等同无限高蛋白。","mechanism":"过度限制和过量补充都可能不利营养或肾负荷。","avoid":"不能把少尿期饮食照搬到稳定期。","numbers":"","source":"D07:P0083–P0096、P0119–P0120、P0137–P0186；PDF08/PDF10；TEXTBOOK renal","id":"row-1"},{"name":"少尿、水肿或高钾","cues":"排水排钾能力下降","content":"将饮水、食物含水和输液一并计入，结合出量、体重和呼吸执行限液。盐与含钾食物按容量和化验调整，不漏算代盐、药物和补充剂中的钾。","mechanism":"摄入与排出不匹配会加重容量及电解质危险。","avoid":"不以“前日尿量加固定量”覆盖全部病种和所有出量。","numbers":"","source":"D07:P0083–P0096、P0119–P0120、P0137–P0186；PDF08/PDF10；TEXTBOOK renal","id":"row-2"},{"name":"CKD非透析与透析营养","cues":"长期肾病，或已经血透/腹透","content":"非透析关注适量蛋白及足够能量，透析后考虑蛋白和营养丢失增加。钾磷限制根据化验与方案，不能继续沿用非透析阶段的同一严格蛋白计划。","mechanism":"透析、分解状态与残余肾功能改变营养需求。","avoid":"不把同一蛋白数值用于所有急性、高分解和透析患者。","numbers":"","source":"D07:P0083–P0096、P0119–P0120、P0137–P0186；PDF08/PDF10；TEXTBOOK renal","id":"row-3"},{"name":"感染、皮肤与血栓风险","cues":"免疫抑制、水肿或肾病综合征","content":"保持口腔皮肤和管路规范护理，发热及局部感染及时评估。水肿避免持续受压及不必要穿刺，观察下肢新肿痛和呼吸突变，按方案活动及抗凝观察。","mechanism":"免疫下降、皮肤屏障受损和高凝可并存。","avoid":"疑血栓不按摩，不凭单一腿围差直接诊断。","numbers":"","source":"D07:P0083–P0096、P0119–P0120、P0137–P0186；PDF08/PDF10；TEXTBOOK renal","id":"row-4"},{"name":"内瘘、UTI与结石居家管理","cues":"透析通路、反复尿感或结石","content":"内瘘避免受压和不必要瘘侧穿刺，学习触查震颤及异常联络。尿感重视清洁、及时排尿和复查，结石按成分调整饮水饮食并处理梗阻感染。","mechanism":"通路畅通、尿流通畅和病因处理分别减少不同风险。","avoid":"容量受限者不能统一大量饮水，结石也不能统一禁钙。","numbers":"","source":"D07:P0083–P0096、P0119–P0120、P0137–P0186；PDF08/PDF10；TEXTBOOK renal","id":"row-5"}],"question":"同样肾病水肿，为什么饮食和护理相关因素不同？"},{"id":"renal-pe-fluid","title":"同一问题：体液过多的三种相关因素","axis":"nursing","common":"共享容量观察：同条件体重、同一时段出入量、水肿、血压及呼吸；再填各病个性证据。","rows":[{"name":"肾小球肾炎","cues":"血尿蛋白尿、水肿和血压升高","content":"体液过多：与肾小球滤过下降导致水钠潴留有关。护理将尿量水肿与血压、肺部及头痛意识联看，及时发现心衰或高血压相关神经变化。","mechanism":"炎症使滤过和排钠排水受影响，容量上升可增加血压。","avoid":"不能只按低白蛋白机制解释；没有低血压证据不任意扩容。","numbers":"","source":"D07:P0004–P0013、P0090–P0096；PDF08；TEXTBOOK renal","id":"row-1"},{"name":"肾病综合征","cues":"大量蛋白尿、低白蛋白及凹陷水肿","content":"体液过多：与低白蛋白降低血浆胶体渗透压及水钠潴留有关。护理除容量记录，还比较尿蛋白、白蛋白、摄入和有效灌注，并观察血栓及感染。","mechanism":"蛋白丢失与肾性钠潴留共同影响水分分布。","avoid":"腿肿明显不等于血管内灌注充足，不能只追求快速减重。","numbers":"","source":"D07:P0004–P0013、P0090–P0096；PDF08；TEXTBOOK renal","id":"row-2"},{"name":"肾功能下降或肾衰","cues":"少尿、体重上升及排泄功能恶化","content":"体液过多：与排水排钠能力下降和摄入排出不匹配有关。护理核算全部入出量、呼吸心律和钾酸碱，评价利尿或替代治疗后的容量与灌注。","mechanism":"水、钠及代谢产物可共同潴留。","avoid":"透析、残余尿量和高分解状态不同，不能统一套限液公式。","numbers":"","source":"D07:P0004–P0013、P0090–P0096；PDF08；TEXTBOOK renal","id":"row-3"}],"question":"名称一样，肾炎、肾病与肾衰的因素和复评重点怎样不同？"},{"id":"renal-pe-nutrition","title":"同一问题：营养与感染的病种差异","axis":"nursing","common":"共同记录实际摄入、体重构成、皮肤口腔和感染线索，再写具体相关因素。","rows":[{"name":"肾病综合征的营养","cues":"尿蛋白持续多、白蛋白低及食欲差","content":"营养失调：与蛋白丢失及摄入不足等因素有关。护理记录摄入和尿蛋白白蛋白，安排合适蛋白能量并复评水肿掩盖的体重变化。","mechanism":"摄入和丢失两端失衡，过量补蛋白并非唯一解决办法。","avoid":"不能因低白蛋白就无限高蛋白或自行补充白蛋白。","numbers":"","source":"D07:P0119–P0125、P0143–P0147、P0163–P0172；PDF08；TEXTBOOK renal","id":"row-1"},{"name":"CKD非透析的营养","cues":"食欲下降、恶心或长期限食","content":"营养失调：与食欲和消化功能变化、限制饮食等因素有关。护理帮助口腔和进食环境，保证能量并执行适宜蛋白及水盐钾磷安排，防止多重限制导致摄入更差。","mechanism":"尿毒症相关症状与饮食限制共同减少摄入。","avoid":"不可把治疗性限制当成越少吃越好。","numbers":"","source":"D07:P0119–P0125、P0143–P0147、P0163–P0172；PDF08；TEXTBOOK renal","id":"row-2"},{"name":"透析或高分解状态的营养","cues":"透析后丢失，或感染应激消耗增加","content":"营养失调：与治疗丢失、分解增加及摄入不足有关。护理比较透析方式、营养指标和实际摄入，配合较非透析期不同的营养计划。","mechanism":"蛋白和能量需要随丢失及分解程度改变。","avoid":"不能继续机械执行稳定非透析期的同一低蛋白方案。","numbers":"","source":"D07:P0119–P0125、P0143–P0147、P0163–P0172；PDF08；TEXTBOOK renal","id":"row-3"},{"name":"免疫抑制中的肾病","cues":"激素或细胞毒治疗","content":"感染风险：与疾病防御下降及免疫抑制治疗有关。护理留意口腔皮肤、发热和局部症状，落实手卫生及相关血象监测，感染表现轻也复评。","mechanism":"疾病丢失与药物抑制免疫可叠加。","avoid":"不把缺少高热当作没有感染。","numbers":"","source":"D07:P0119–P0125、P0143–P0147、P0163–P0172；PDF08；TEXTBOOK renal","id":"row-4"},{"name":"透析相关感染","cues":"血管或腹透通路","content":"感染风险：与屏障被侵入及通路维护因素有关。护理检查内瘘穿刺点、导管出口或腹透液，落实相应无菌连接和异常采样报告。","mechanism":"通路类型不同，感染入口与表现不同。","avoid":"不能只讲避免感冒而漏掉出口和透出液。","numbers":"","source":"D07:P0119–P0125、P0143–P0147、P0163–P0172；PDF08；TEXTBOOK renal","id":"row-5"}],"question":"同是营养不足或感染风险，哪些因素必须换掉？"}],"drills":[{"id":"renal-drill-nephrotic","title":"把水肿机制接回激素护理","stem":"成人有大量蛋白尿、白蛋白下降和水肿，拟按病理方案接受糖皮质激素治疗。","prompt":"解释水肿机制，并列治疗期三类监测。","answer":["滤过屏障异常使蛋白丢失，低白蛋白降低胶体渗透压，水钠潴留也参与水肿。","观察感染及皮肤口腔，监测血糖血压和体重出入量，关注消化道与长期骨骼风险。","用尿蛋白、白蛋白、营养和水肿共同评价，不自行停减激素。"],"source":"D07:P0007–P0008、P0123–P0125、P0188；M038题型目标；原创变式"},{"id":"renal-drill-uti","title":"不要把尿痛写成单纯水肿护理","stem":"一位成人出现尿频尿痛，随后寒战、发热和单侧腰痛，肾区叩击不适。","prompt":"如何定位、补检查并组织护理？","answer":["警惕上尿路感染方向，补生命体征及灌注评估。","规范留尿培养并结合尿检、肾功能及病情，观察全身恶化。","配合抗感染并记录疗效，饮水服从容量状态，说明疗程、卫生及复查。"],"source":"D07:P0009–P0011、P0094、P0126–P0127、P0174–P0179；M037题型目标；原创变式"},{"id":"renal-drill-trend","title":"慢性病里也要寻找急性变化","stem":"长期蛋白尿患者在感染后出现少尿、血压上升和乏力。","prompt":"还缺哪些信息才能判断病程与优先问题？","answer":["补既往与当前肌酐、时间跨度、逐时尿量及容量证据。","查血钾、酸碱及心电，识别急性危险。","把感染、药物、低灌注与梗阻列为可逆因素，不仅写慢性肾病。"],"source":"D07:P0012–P0013、P0090–P0096；M035/M039题型目标；原创变式"}],"references":[{"title":"NIDDK 成人肾病综合征","url":"https://www.niddk.nih.gov/health-information/kidney-disease/nephrotic-syndrome-adults"},{"title":"KDIGO 慢性肾病评估与管理","url":"https://kdigo.org/guidelines/ckd-evaluation-and-management/"},{"title":"KDIGO AKI定义与分期","url":"https://kdigo.org/wp-content/uploads/2016/10/KDIGO-2012-AKI-Guideline-English.pdf"},{"title":"UKKA 高钾血症指南","url":"https://www.ukkidney.org/sites/default/files/FINAL%20VERSION%20-%20UKKA%20CLINICAL%20PRACTICE%20GUIDELINE%20-%20MANAGEMENT%20OF%20HYPERKALAEMIA%20IN%20ADULTS%20-%20191223.pdf"}]},"thyroid":{"title":"甲状腺：功能、结节与围术期三线","intro":"甲亢围绕高代谢与药物，结节围绕性质评估，围术期围绕气道、声音吞咽与钙；三条线共用观察框架，保留各自细节。","framework":[{"id":"thyroid-monitor","title":"功能状态用症状和检查共同看","cue":"怕热、多汗、消瘦、心悸或治疗复查","answer":"记录脉搏、体重、睡眠、食欲和情绪，再联系TSH及游离激素趋势。抗甲状腺药期间关注发热咽痛、黄疸或深色尿，异常及时联系并按要求核查血象和肝功能。","why":"激素过多增加代谢负荷，药物又可能影响血细胞与肝脏。","source":"D01:P0003、P0007–P0010、P0053–P0065；ATA"},{"id":"thyroid-neck","title":"颈部术后观察五项","cue":"术后颈部紧绷、气促或声音变化","answer":"看呼吸、声音、吞咽、颈部及敷料引流，连续比较肿胀与渗血。出现呼吸费力或迅速肿胀立即呼叫支援并准备气道和解除压迫相关配合，不等待血氧明显下降。","why":"颈部小范围出血也可能压迫气道，声音与吞咽又提示不同神经分支。","source":"D01:P0083–P0103"},{"id":"thyroid-crisis","title":"危象要先识别整体恶化","cue":"甲亢背景遇感染、手术、停药或强应激","answer":"观察高热、明显心动过速、出汗、胃肠和意识变化，及时升级急救。配合气道循环、降温和针对激素的治疗，同时记录出入量及反应，基础护理跟上。","why":"多系统失代偿比单项数值更能提示危险。","source":"D01:P0029–P0043"},{"id":"thyroid-prepost","title":"术前准备与术后评价闭环","cue":"甲亢拟手术或甲状腺癌围术期","answer":"术前完成甲亢控制、相关用药及体位呼吸训练，关注脉搏、睡眠和体重改善。术后安排适宜体位、引流、吞咽安全、疼痛和功能训练，再按病因解释用药及随访。","why":"准备降低代谢和出血风险，术后护理连接气道安全与功能恢复。","source":"D01:P0066–P0089、P0116–P0137"}],"contrasts":[{"id":"thyroid-diagnosis","title":"甲亢与癌的依据怎样不同","axis":"diagnosis","common":"功能异常、恶性风险与病理分型分别回答。","rows":[{"name":"Graves甲亢","cues":"怕热消瘦、弥漫肿大、震颤或眼部表现","content":"症状和甲状腺体征支持功能亢进，再用甲功与抗体判断功能及病因。记录体重脉搏和治疗前后变化，不把每个甲亢都当Graves。","mechanism":"自身免疫刺激可增加甲状腺激素产生。","avoid":"典型三组表现缺一不排除，病因仍需评估。","numbers":"","source":"D01:P0002–P0025；D02:P0002–P0025","id":"row-1"},{"name":"甲状腺恶性结节","cues":"质硬固定、压迫症状或可疑淋巴结","content":"结合超声风险和细针细胞学进一步分层，必要时组织病理补证。声音变化、吞咽或呼吸不适要同时评价局部影响。","mechanism":"结节性质与是否分泌过多激素是两条不同问题。","avoid":"触诊、超声可疑或单次甲功不能独立确诊全部癌型。","numbers":"","source":"D01:P0002–P0025；D02:P0002–P0025","id":"row-2"},{"name":"术后急变分支","cues":"气促、抽搐、高热或乳白引流","content":"气促先走气道分支，麻木抽搐走钙代谢分支，高热心动过速伴整体恶化走危象分支。引流性状与皮下捻发感另查乳糜漏或气肿，不用一种并发症解释全部。","mechanism":"不同损伤环节产生不同时间和表现。","avoid":"术后异常不能全部写成切口疼痛。","numbers":"","source":"D01:P0002–P0025；D02:P0002–P0025","id":"row-3"}],"question":"高代谢和颈部结节分别需要哪类证据？"},{"id":"thyroid-tests","title":"检查和计算要点","axis":"labs","common":"甲功答功能，抗体答病因，超声/取样答结构性质。","rows":[{"name":"TSH、FT3/FT4与抗体","cues":"高代谢或复查","content":"典型原发甲亢多为TSH受抑制、游离激素升高；TRAb等支持Graves病因。总激素受结合蛋白等影响，需与临床及具体情境联合。","mechanism":"反馈调节与游离激素水平联系功能变化。","avoid":"药物、妊娠和其他病型可改变解释，不能只看一个箭头。","numbers":"","source":"D01:P0005–P0025、P0080–P0082、P0104–P0109、P0142–P0145","id":"row-1"},{"name":"超声、细针与影像","cues":"结节或侵犯范围问题","content":"超声看回声、边界、钙化及淋巴结，取样看细胞性质。CT/MRI用于相应局部范围问题，术后核医学检查按癌型和治疗目的选择。","mechanism":"风险分层、细胞学和分期回答不同问题。","avoid":"不是所有癌型都适用同一种核医学或随访标志物。","numbers":"","source":"D01:P0005–P0025、P0080–P0082、P0104–P0109、P0142–P0145","id":"row-2"},{"name":"降钙素与血钙","cues":"髓样癌相关评估，或术后抽搐麻木","content":"降钙素用于髓样癌相关线索和随访，血钙用于神经肌肉兴奋异常评估。二者名称相似但临床问题不同，抽搐时还要评价气道和其他原因。","mechanism":"髓样癌标志与钙稳态不是同一检查。","avoid":"不能用降钙素替代血钙，也不能凭抽搐一项自行补钙。","numbers":"","source":"D01:P0005–P0025、P0080–P0082、P0104–P0109、P0142–P0145","id":"row-3"},{"name":"基础代谢率与术前达标","cues":"计算问或判断准备充分","content":"计算题先列题目指定公式、静息测量的脉搏与脉压，再逐步代入并写单位与判断依据。术前准备还需结合情绪睡眠、体重、心率和综合评估，不能只凭计算值放行。","mechanism":"静息循环指标可反映代谢负荷，但不是完整手术风险。","avoid":"公式及分度未给时先核对课程采用方法，不把简式用于真实能量处方。","numbers":"","source":"D01:P0005–P0025、P0080–P0082、P0104–P0109、P0142–P0145","id":"row-4"}],"question":"术后抽搐和术前基础代谢率题各应补什么？"},{"id":"thyroid-drugs","title":"药物和术前准备的作用","axis":"treatment","common":"分清抑制合成、抑制释放、控制症状与替代治疗。","rows":[{"name":"抗甲状腺药与警讯","cues":"甲亢保守治疗","content":"治疗用于控制激素相关状态，按计划复查并解释依从性。出现发热或明显咽痛时立即就医查血象，在医生确认可恢复前不继续服用相关抗甲状腺药；黄疸等也应及时评估。","mechanism":"粒细胞减少和肝损伤可能是药物严重不良反应。","avoid":"不能仅把发热按普通感冒处理，也不自行换药长期观察。","numbers":"","source":"D01:P0029–P0043、P0060–P0081、P0088、P0118；ATA","id":"row-1"},{"name":"碘剂与术前路径","cues":"拟甲亢手术","content":"短期碘剂可减少激素释放及腺体血流，准备路径需与抗甲状腺药控制及手术计划配合。核对处方、时点、服用方法与症状，解释不能自行突然停改。","mechanism":"抑制合成与抑制释放是不同环节，血流改变影响出血风险。","avoid":"不将一种滴数递增表用于所有制剂，也不用作任意长期自疗。","numbers":"","source":"D01:P0029–P0043、P0060–P0081、P0088、P0118；ATA","id":"row-2"},{"name":"β阻滞与症状控制","cues":"心悸、心动过速等","content":"观察心率、血压及呼吸耐受，并结合基础心肺情况核对禁忌。控制交感相关症状不能代替病因和激素控制。","mechanism":"减轻外周反应与降低激素来源不同。","avoid":"哮喘、明显心动过缓或不稳定循环时需另评。","numbers":"","source":"D01:P0029–P0043、P0060–P0081、P0088、P0118；ATA","id":"row-3"},{"name":"危象与低钙处理配合","cues":"整体恶化，或术后神经肌肉症状","content":"危象配合病因及多系统支持，记录温度、心律、意识和出入量。低钙按症状、检查和医嘱处理，静脉治疗时观察通路及心律。","mechanism":"危象涉及过量激素作用，低钙涉及神经肌肉及心电活动。","avoid":"不照搬固定补液量、镇静方案或静脉钙剂量。","numbers":"","source":"D01:P0029–P0043、P0060–P0081、P0088、P0118；ATA","id":"row-4"},{"name":"术后激素及癌相关后续治疗","cues":"切除术后或肿瘤随访","content":"核对是否需甲状腺激素替代或抑制治疗，按计划复查功能与相关肿瘤指标。饮食是否低碘须联系放射性碘治疗准备，不能把所有癌术后长期禁碘。","mechanism":"残余功能和治疗目的决定激素与碘安排。","avoid":"甲亢与癌术后不能用同一饮食和用药宣教。","numbers":"","source":"D01:P0029–P0043、P0060–P0081、P0088、P0118；ATA","id":"row-5"}],"question":"同是碘剂和抗甲状腺药，为什么作用与时点不同？"},{"id":"thyroid-care","title":"围术期与护理P-E差异","axis":"nursing","common":"护理问题按高代谢、眼部、气道和神经肌肉损伤分支。","rows":[{"name":"营养、睡眠与活动","cues":"高代谢消瘦、失眠或易疲劳","content":"营养问题联系代谢消耗与摄入，安排足够能量和合适蛋白并记录体重。睡眠与活动减少刺激、合理休息，脉搏和症状改善后再调整活动。","mechanism":"代谢负荷增加能量消耗与交感兴奋。","avoid":"不能把肾功能受限或其他并病者统一高蛋白，碘安排须联系病因及治疗。","numbers":"","source":"D01:P0044–P0052、P0053–P0065、P0083–P0137；D02相应段","id":"row-1"},{"name":"突眼与角膜保护","cues":"眼睑闭合不全、畏光或干涩","content":"保护眼睛免受风沙强光刺激，按眼部方案保湿覆盖并观察角膜。抬高头部帮助减轻眼部胀肿，提醒不揉眼及定期眼科评价。","mechanism":"暴露增加角膜干燥与损伤风险。","avoid":"不自行使用激素滴眼液或把严重眼病仅当美容问题。","numbers":"","source":"D01:P0044–P0052、P0053–P0065、P0083–P0137；D02相应段","id":"row-2"},{"name":"术后气道风险","cues":"颈部肿胀、渗血、喘鸣或气促","content":"观察血肿压迫、喉头水肿、气管问题及双侧神经损伤方向，立即呼叫并配合气道处理。记录引流与敷料并连续看呼吸，不等到明显发绀才报告。","mechanism":"不同原因均可能迅速缩小有效气道。","avoid":"不能仅按疼痛解释，也不让未受训人员自行侵入处理。","numbers":"","source":"D01:P0044–P0052、P0053–P0065、P0083–P0137；D02相应段","id":"row-3"},{"name":"喉返与喉上神经差异","cues":"声嘶、声调无力或饮水呛咳","content":"喉返损伤重点看发声及双侧受损时呼吸；喉上外支关注音调力量，内支关注感觉与误咽。安排声音和吞咽评价，进食性状途径按安全结果调整。","mechanism":"运动、张力和喉部感觉分支作用不同。","avoid":"清醒不代表吞咽安全，不能强迫试水证明恢复。","numbers":"","source":"D01:P0044–P0052、P0053–P0065、P0083–P0137；D02相应段","id":"row-4"},{"name":"低钙、乳糜漏与皮下气肿","cues":"口周麻木抽搐、乳白液或皮下捻发感","content":"低钙看神经肌肉、心律与血钙；乳糜漏记录液体与进食关系并配合引流营养。皮下气肿看范围与呼吸变化，扩展或气道异常及时升级。","mechanism":"钙稳态、淋巴损伤与气体进入组织分别产生不同表现。","avoid":"不能只按引流颜色确诊，也不将轻微气肿的观察用于呼吸危险者。","numbers":"","source":"D01:P0044–P0052、P0053–P0065、P0083–P0137；D02相应段","id":"row-5"},{"name":"疼痛、体位与功能恢复","cues":"切口痛、吞咽不适或出院阶段","content":"固定支托颈部减少咳嗽牵拉，评估镇痛效果并兼顾深呼吸排痰。进食先看清醒和吞咽，后续在伤口及方案允许下逐步颈肩活动，并指导复查与危险信号。","mechanism":"舒适与活动改善恢复，但气道和误吸优先。","avoid":"不把固定进食天数或同一活动幅度用于全部手术。","numbers":"","source":"D01:P0044–P0052、P0053–P0065、P0083–P0137；D02相应段","id":"row-6"}],"question":"声嘶、呛咳和抽搐为什么要分别观察？"},{"id":"thyroid-pe-matrix","title":"内外科护理诊断相关因素对照","axis":"nursing","common":"名称相同要换因素，内科代谢问题与术后创伤问题分开。","rows":[{"name":"营养与活动问题","cues":"高代谢消瘦、肌无力或心脏负担","content":"营养失调联系代谢需求增加与摄入失配，活动无耐力联系肌肉分解、乏力和心脏影响。分别记录摄入体重和活动症状，护理措施不可只背同一休息句。","mechanism":"激素过多同时改变消耗、肌肉与循环负荷。","avoid":"没有活动证据时不只凭病名认定严重活动限制。","numbers":"","source":"M002逐图核查；D01:P0026–P0065、P0083–P0137","id":"row-1"},{"name":"体液不足、应对与体像","cues":"多汗腹泻，情绪改变或突眼肿大","content":"体液不足需有丢失及容量证据；应对问题联系情绪调节与病情影响。突眼或颈部改变造成体像困扰时关注患者实际感受，知识问题用回演自我管理评价。","mechanism":"生理失水与心理社会影响是不同护理维度。","avoid":"焦虑和体像问题不能无患者线索就一概套上。","numbers":"","source":"M002逐图核查；D01:P0026–P0065、P0083–P0137","id":"row-2"},{"name":"术后疼痛、清理气道与恐惧","cues":"切口咽痛、分泌物难排或担忧手术","content":"急性疼痛联系手术与局部刺激，清理气道无效联系分泌物、刺激及疼痛导致咳嗽受限。恐惧联系对肿块、手术或预后的具体担忧，解释并评价理解和情绪变化。","mechanism":"创伤和插管等影响舒适与咳嗽，心理因素影响配合。","avoid":"不能只写疼痛而漏掉血肿等气道危险。","numbers":"","source":"M002逐图核查；D01:P0026–P0065、P0083–P0137","id":"row-3"}],"question":"营养、活动、体液和心理问题分别由什么证据支持？"},{"id":"thyroid-bmr","title":"基础代谢估算与手术评估","axis":"labs","common":"计算用清晨空腹静卧测量的脉率和血压，先算脉压。","rows":[{"name":"基础代谢率简式","cues":"需要列式的计算题","content":"先用收缩压减舒张压求脉压，再把脉率和脉压代入估算式并写百分比。结果用于估算题，甲亢的诊断与治疗评价仍需甲功、症状和病因。","mechanism":"脉率及脉压可反映高代谢循环反应，但估计并不等于直接测代谢。","avoid":"非清晨空腹静卧数据、心律不齐或其他影响循环因素时不能机械外推。","numbers":"估算BMR(%)＝脉率(次/min)＋脉压(mmHg)－111。正常约±10%；轻度约+20%—+30%，中度约+30%—+60%，重度＞+60%；分界值结合题设。","source":"外科扫描PDF287–289＝印刷279–281，已视觉核查；ATA手术资料","id":"row-1"},{"name":"术前控制与耐受","cues":"拟手术的甲亢","content":"情绪、睡眠、体重及静息脉搏改善是控制表现，还需甲功和完整围术期评估。明确手术方式、麻醉与心肺并病风险，不能只看一个BMR计算数。","mechanism":"降低代谢与循环负荷有助于减少手术应激风险。","avoid":"该组参考指标不能替代外科麻醉评估，也不能用于患者自行决定停药。","numbers":"常用准备观察参考：静息脉率＜90次/min、脉压趋正常、BMR＜+20%，同时症状和甲功达到手术团队要求。","source":"外科扫描PDF287–289＝印刷279–281，已视觉核查；ATA手术资料","id":"row-2"}],"question":"算得代谢升高能否替代甲功或单独决定手术？"},{"id":"thyroid-surgical-choice","title":"手术适用情境与限制","axis":"treatment","common":"考虑压迫、结节性质、控制难度和患者耐受，再比较治疗选择。","rows":[{"name":"倾向外科评估的情境","cues":"明显压迫、较大肿大、毒性结节或控制困难","content":"颈部压迫、胸骨后延伸、可疑恶性结节及药物难以控制或复发时，可讨论手术路径。病因、其他治疗选择和患者意愿共同决定，并由经验团队评估。","mechanism":"手术可同时解决局部占位及激素来源问题。","avoid":"不是仅按轻中重分度就自动手术，也不把治疗复发等同必须同一种切除方式。","numbers":"","source":"外科扫描PDF288印刷280；ATA Surgical Management/儿童/妊娠资料","id":"row-1"},{"name":"耐受、儿童与妊娠","cues":"合并严重器官病、儿童或妊娠","content":"严重心肺等问题先评估能否耐受并完成控制；儿童和孕期的替代治疗限制与风险需专科讨论。需要手术时选择时机和经验团队，不能用年龄或妊娠一项简单归为绝对禁忌。","mechanism":"治疗风险取决于病情、手术条件与其他方案可用性。","avoid":"妊娠禁用放射性碘；不能把青少年或高龄一律排除手术。","numbers":"","source":"外科扫描PDF288印刷280；ATA Surgical Management/儿童/妊娠资料","id":"row-2"}],"question":"年龄、妊娠或药物治疗失败时，为什么要分别评估？"}],"drills":[{"id":"thyroid-drill-branch","title":"先区分三个术后信号","stem":"甲术后甲出现声嘶，乙饮水呛咳，丙口周麻木并手指痉挛。","prompt":"分别指出评估分支和护理重点。","answer":["甲看发声与呼吸，评估喉返相关问题及其他原因。","乙先看吞咽和误吸安全，联系喉部感觉或其他吞咽问题。","丙联系血钙等检查及神经肌肉危险；三者均需记录并报告，不套同一处理。"],"source":"D01:P0098–P0109；M005题型目标；原创变式"},{"id":"thyroid-drill-prep","title":"从准备目的回忆观察","stem":"甲亢拟手术者问：症状已减轻，为什么还需规定的药物准备和评估？","prompt":"用机制解释，并列两个观察方向。","answer":["合成、释放及外周反应是不同环节，术前准备还需降低代谢与腺体血流相关风险。","观察脉搏、体重睡眠等控制表现，也观察药物血象肝脏警讯。","核对具体手术及用药安排，不能只凭感觉舒服自行停药。"],"source":"D01:P0066–P0082、P0143–P0145；M004题型目标；原创变式"},{"id":"thyroid-drill-crisis","title":"高热不只是体温问题","stem":"甲亢患者应激后出现高热、大汗、明显心悸和行为异常。","prompt":"为何需整体评价？","answer":["从甲亢背景与多系统恶化识别危象可能，立即升级。","监测呼吸循环、温度和意识，配合降温及针对病因治疗。","寻找感染、停药等诱因，并记录反应及出入量。"],"source":"D01:P0029–P0043；M003题型目标；原创变式"},{"id":"thyroid-drill-bmr","title":"列式后还要判断条件","stem":"一次静息测量脉率88次/min、血压125/75 mmHg，题目要求用脉率脉压简式估算基础代谢率。","prompt":"列式并说明它不能替代什么。","answer":["脉压＝125－75＝50 mmHg；估算BMR＝88＋50－111＝+27%。","处于轻度升高参考范围，但需确认清晨、空腹、静卧及测量可靠。","不能据此单独确诊甲亢或决定已达到手术条件，需甲功和综合评估。"],"source":"外科扫描PDF287印刷279；M004题型目标；原创数据变式"}],"references":[{"title":"美国甲状腺协会：甲亢与抗甲状腺药警讯","url":"https://www.thyroid.org/hyperthyroidism/"},{"title":"ATA Graves病外科治疗","url":"https://www.thyroid.org/surgical-management-graves-disease/"},{"title":"ATA 儿童青少年甲亢治疗","url":"https://www.thyroid.org/hyperthyroidism-children-adolescents/"},{"title":"ATA 妊娠与甲亢","url":"https://www.thyroid.org/hyperthyroidism-in-pregnancy/"}]},"diabetes":{"title":"糖代谢：日常管理与三类急变分开","intro":"先看血糖、酮体酸碱、渗透及意识，区分低血糖、DKA和高渗；长期管理再把饮食运动、药物、监测和足眼肾保护连起来。","framework":[{"id":"dm-acute","title":"血糖异常先看意识与吞咽","cue":"出汗手抖、深快呼吸、脱水或意识改变","answer":"先测血糖并评价意识、吞咽及循环；疑低血糖按流程及时纠正并复测。高糖或疑DKA/HHS时补酮体、酸碱、电解质、渗透与脱水评估，不能只凭血糖高低作全部判断。","why":"低糖损害供能，高糖危象涉及不同程度酮症、酸中毒及渗透性失水。","source":"D03:P0007–P0012、P0020–P0033、P0041–P0045"},{"id":"dm-record","title":"把四件事记在同一张记录","cue":"血糖波动、运动或药物调整","answer":"记录血糖时点、实际进食、活动和药物剂型剂量时间，并同时记录症状。复盘时找漏餐、额外运动、感染或用药偏差，纠正后继续观察复发而非只看一次数字。","why":"药物、摄入和能量消耗共同决定血糖变化。","source":"D03:P0042–P0044、P0096–P0100"},{"id":"dm-insulin","title":"胰岛素核对与回演","cue":"需要注射治疗","answer":"核对制剂、装置、剂量、时间及进餐，检查注射部位并按计划轮换。请患者演示保存、准备和注射步骤，记录低血糖、过敏或脂肪改变；生病时不自行中断关键治疗。","why":"作用时程和皮下吸收受制剂与部位影响，演示比口头答应更能发现错误。","source":"D03:P0072–P0080、P0099–P0100"},{"id":"dm-longterm","title":"长期管理要落到眼肾足","cue":"慢性糖尿病随访","answer":"饮食、运动、药物、监测和教育共同实施，同时复查尿白蛋白/肾功能、眼底及足部感觉血供。教会每日足部自查、低血糖识别和病日联络，把记录带入复诊。","why":"微血管、神经和大血管损伤可在症状不明显时发展。","source":"D03:P0009–P0011、P0019、P0096–P0111"}],"contrasts":[{"id":"dm-disease","title":"糖尿病与急性危象对照","axis":"diagnosis","common":"分型、当次急症和慢性并发症分别列证据。","rows":[{"name":"糖尿病与1/2型","cues":"典型症状或筛查异常","content":"糖尿病判断结合规范实验室血糖、症状及必要复核；分型结合起病、体型、抗体和胰岛素分泌。年轻消瘦或肥胖家族史只是线索，不能单独定型。","mechanism":"胰岛素缺乏与抵抗可有不同组合。","avoid":"无典型症状时不能把一次随机值随意当确诊。","numbers":"","source":"D03:P0004–P0012；D04:P0003–P0011；2024高血糖危象共识","id":"row-1"},{"name":"DKA","cues":"酮体升高、酸中毒及糖尿病相关背景","content":"深快呼吸、恶心腹痛和脱水提示补查血酮与酸碱。血糖不高也可能存在DKA，尤其相关药物背景；观察循环及钾变化。","mechanism":"胰岛素不足促进脂肪分解和酮酸形成，同时产生失水。","avoid":"不能仅靠高血糖阈值排除或确诊DKA。","numbers":"","source":"D03:P0004–P0012；D04:P0003–P0011；2024高血糖危象共识","id":"row-2"},{"name":"高渗高血糖状态","cues":"明显失水、高渗及神经症状","content":"把血糖、有效渗透和脱水程度合看，并与DKA及其他意识异常区分。可出现混合状态，记录进食饮水、诱因和肾功能。","mechanism":"高糖造成渗透性利尿，失水进一步加重高渗。","avoid":"年龄与尿酮阴性不能单独完成分类。","numbers":"","source":"D03:P0004–P0012；D04:P0003–P0011；2024高血糖危象共识","id":"row-3"},{"name":"低血糖","cues":"出汗、心慌、手抖或意识异常","content":"联系当时血糖、进餐、药物和运动，先按安全吞咽分支处理。恢复后寻找诱因及再发风险，严重程度还取决是否需要他人帮助。","mechanism":"葡萄糖不足影响交感反应及脑功能。","avoid":"没有典型心慌不能排除，意识障碍者禁止强行喂食。","numbers":"","source":"D03:P0004–P0012；D04:P0003–P0011；2024高血糖危象共识","id":"row-4"},{"name":"肾、眼与足慢性并发症","cues":"蛋白尿、视物变化或足部异常","content":"肾病看白蛋白尿及功能趋势并排除其他肾病；视网膜病变依眼底筛查及专科评估。足部把感觉、供血、伤口和感染分别记录，不能只写皮肤破损。","mechanism":"微血管、神经和血供损伤导致不同靶器官表现。","avoid":"肾病不能只凭糖尿病史归因，视力尚可也不免筛查。","numbers":"","source":"D03:P0004–P0012；D04:P0003–P0011；2024高血糖危象共识","id":"row-5"}],"question":"血糖没有特别高，为什么仍可能是DKA？"},{"id":"dm-tests","title":"当前血糖与长期损伤检查","axis":"labs","common":"当前急症看实时变化，长期管理看累积控制与靶器官。","rows":[{"name":"FPG、OGTT与HbA1c","cues":"诊断、分型或控制评估","content":"FPG看空腹，OGTT按规范负荷及时点，HbA1c主要反映近数月平均。记录样本方法与状态，贫血等影响HbA1c解释时另评。","mechanism":"瞬时测量与长期糖化具有不同时间维度。","avoid":"HbA1c不能代替此刻低血糖或急症判断。","numbers":"","source":"D03:P0013–P0033；D04:P0012–P0032","id":"row-1"},{"name":"血酮、血气与电解质","cues":"疑DKA或治疗中","content":"血酮联系酮症，pH和碳酸氢根联系酸中毒，钾需动态追踪。初始血钾不低也可能总体缺钾，治疗后变化更需观察。","mechanism":"失水、细胞转移和胰岛素作用共同影响血钾。","avoid":"尿酮和血酮不能简单互代，不能以初始高钾排除缺钾。","numbers":"","source":"D03:P0013–P0033；D04:P0012–P0032","id":"row-2"},{"name":"渗透与肾功能","cues":"严重脱水或意识异常","content":"渗透相关指标与钠、血糖及肾功能共同评价，计算时核对单位。记录出入量和循环反应，反映排泄及治疗耐受。","mechanism":"溶质和水分比例决定渗透压力，肾排泄影响恢复。","avoid":"不只凭一个计算值忽略临床脱水。","numbers":"","source":"D03:P0013–P0033；D04:P0012–P0032","id":"row-3"},{"name":"足、眼与肾筛查","cues":"长期风险或出现症状","content":"足部检查保护性感觉、动脉搏动和创面，必要时补血管检查及培养。眼底和尿白蛋白/肾功能按计划随访，记录变化而非仅列检查名。","mechanism":"感觉丧失、缺血、感染和微血管损伤分属不同环节。","avoid":"踝肱指数受钙化影响，不能把一个正常数字当全部血供正常。","numbers":"","source":"D03:P0013–P0033；D04:P0012–P0032","id":"row-4"}],"question":"HbA1c与即时血糖为什么不能替代？"},{"id":"dm-treatment","title":"降糖药、急症治疗与时点","axis":"treatment","common":"把日常药物与急救分开，具体制剂和方案决定用法。","rows":[{"name":"清醒低血糖与严重低血糖","cues":"血糖低且能吞咽，或意识吞咽异常","content":"能安全吞咽时以快速糖类纠正并复测，仍低则按流程继续处理；恢复后结合下餐安排防复发。意识异常时保护气道并配合非经口急救，不能强喂。","mechanism":"快速糖恢复供能，但长效药物作用可能持续。","avoid":"脂肪多食物吸收较慢，不是首选快速纠正手段。","numbers":"成人能吞咽的低血糖常用约15 g快速糖，15分钟后复测；按个人流程调整。","source":"D03:P0064–P0090；D04:P0064–P0085；ADA低血糖与危象共识","id":"row-1"},{"name":"DKA/HHS协同处理","cues":"脱水、酮症酸中毒或高渗","content":"补液、胰岛素、电解质和诱因治疗协同，连续复评血糖、酮体、酸碱及循环。补液和降糖过快均可能带来风险，心肾受限者尤其要观察耐受。","mechanism":"只降血糖不能同时完成纠正酮症和有效循环。","avoid":"不能以血糖降到一个值就自行停胰岛素，也不照固定速度补液。","numbers":"","source":"D03:P0064–P0090；D04:P0064–P0085；ADA低血糖与危象共识","id":"row-2"},{"name":"口服降糖药进餐关系","cues":"长期处方与进食安排","content":"促分泌类需关注进餐和低血糖，双胍常随餐以改善耐受，α糖苷酶抑制剂与含碳水第一口食物相配。具体普通、缓释或控释剂型另核对，结合肾功能及不良反应教育。","mechanism":"作用机制和释放方式决定与食物的关系。","avoid":"同一大类不同制剂也不能直接共用一个时间表。","numbers":"","source":"D03:P0064–P0090；D04:P0064–P0085；ADA低血糖与危象共识","id":"row-3"},{"name":"胰岛素适应情境与注射","cues":"1型、相关急症或其他需胰岛素情况","content":"解释胰岛素治疗目的，核对短效/速效及基础制剂的时程和装置。保存条件与开封期限依制剂，避免极端温度及重复在同点注射，观察低糖及局部改变。","mechanism":"不同制剂持续时间不同，局部脂肪改变影响吸收。","avoid":"不把一种储存上限或碘消毒说法泛化全部制剂操作。","numbers":"","source":"D03:P0064–P0090；D04:P0064–P0085；ADA低血糖与危象共识","id":"row-4"},{"name":"黎明现象与夜间低糖反跳","cues":"晨起血糖高","content":"补充夜间血糖或连续监测，区别夜间逐渐升高与低糖后升高的轨迹。治疗调整依证据和团队方案，不能只看晨糖高就加睡前药。","mechanism":"相同晨高可对应不同夜间过程。","avoid":"不能未经监测就认定反跳机制并自行减量或加量。","numbers":"","source":"D03:P0064–P0090；D04:P0064–P0085；ADA低血糖与危象共识","id":"row-5"},{"name":"糖尿病足治疗","cues":"溃疡、感染或供血异常","content":"按感染、缺血和压力分别配合评估，培养、敷料及抗感染按需要选择。减压与血供问题不能被清洁换药代替，观察坏疽和全身感染。","mechanism":"愈合依赖足够血供、控感染及减少重复受压。","avoid":"缺血足不能统一抬高、热敷或自行修剪深部伤口。","numbers":"","source":"D03:P0064–P0090；D04:P0064–P0085；ADA低血糖与危象共识","id":"row-6"}],"question":"低血糖纠正后为什么还要复测和评估下一餐？"},{"id":"dm-care","title":"饮食运动与护理P-E对照","axis":"nursing","common":"先指出危险或已发生问题，再用进食、活动和治疗线索填因素。","rows":[{"name":"营养与能量计算","cues":"消瘦、超重或需调整膳食","content":"先根据身高体重、活动量、年龄及特殊状态确定目标，再分配能量与餐次并复评血糖体重。肾病和透析者另核对蛋白需求，足创面也需考虑组织修复。","mechanism":"能量供需与药物配合影响血糖及体重，蛋白需求受肾功能影响。","avoid":"不把一套劳动强度或营养比例当全部人固定处方。","numbers":"","source":"D03:P0034–P0067、P0073–P0080、P0091–P0112；D04对应段","id":"row-1"},{"name":"运动前后管理","cues":"血糖相对稳定准备锻炼","content":"选择可持续的有氧及力量活动，计划与进餐和药物时间配合。运动前后看血糖和症状，出现不适停止并处理，急性代谢失控或足损伤先解决危险。","mechanism":"活动增加葡萄糖利用，药物作用可叠加低糖。","avoid":"不能用运动替代危象治疗，也不让足溃疡者继续负重训练。","numbers":"","source":"D03:P0034–P0067、P0073–P0080、P0091–P0112；D04对应段","id":"row-2"},{"name":"低血糖、体液不足与活动问题","cues":"已低糖、DKA失水或乏力","content":"已发生低糖写当前问题及意识风险，不能只写有低糖危险。危象的体液不足联系渗透性利尿和呕吐，以血压、皮温、尿量等支持；活动耐量随稳定程度安排。","mechanism":"实际问题与风险问题的证据不同。","avoid":"不能仅用血糖不稳定风险替代已发生急症。","numbers":"","source":"D03:P0034–P0067、P0073–P0080、P0091–P0112；D04对应段","id":"row-3"},{"name":"足部清单与皮肤完整性","cues":"感觉下降、缺血或既往溃疡","content":"每日看足底趾间、肤色皮温和伤口，检查鞋内异物并选合适鞋袜。温和洗护后擦干，修甲避免过深，不赤足、不用热源直接取暖，异常及时就诊。","mechanism":"感觉下降使小损伤被忽视，缺血和感染使伤口难愈。","avoid":"不可按感觉试高温水，也不自行切除胼胝或挤破水疱。","numbers":"","source":"D03:P0034–P0067、P0073–P0080、P0091–P0112；D04对应段","id":"row-4"},{"name":"感染与病日管理","cues":"发热、腹泻、摄入减少","content":"加强血糖及相应酮体观察，记录饮水进食和用药并及时联系调整。即使吃得少也不能自行停掉必要基础胰岛素，持续呕吐、意识或循环变化及时就医。","mechanism":"应激可增加胰岛素需求，同时摄入下降也带来低糖风险。","avoid":"生病不等于只休息或把全部降糖药照旧不评估。","numbers":"","source":"D03:P0034–P0067、P0073–P0080、P0091–P0112；D04对应段","id":"row-5"},{"name":"五方面教育与靶器官随访","cues":"准备出院或长期控制不佳","content":"让患者说出饮食、活动、药物、监测及教育如何落到一天，并回演测糖注射和应急处理。定期核查眼、肾、足和心血管风险，记录复查计划与警讯。","mechanism":"掌握动作和情境判断比背出五个名称更能预防问题。","avoid":"症状缓解或短期血糖好看不代表并发症风险消失。","numbers":"","source":"D03:P0034–P0067、P0073–P0080、P0091–P0112；D04对应段","id":"row-6"}],"question":"普通管理、危象和足溃疡的饮食活动有何差别？"},{"id":"dm-numeric-criteria","title":"诊断和危象数值对照","axis":"labs","common":"先分成人非孕诊断、低血糖级别和急性危象，再核对样本与复核条件。","rows":[{"name":"成人非孕糖尿病诊断","cues":"实验室血糖或HbA1c异常","content":"空腹需无热量摄入至少8小时，OGTT采用75 g无水葡萄糖负荷及2小时静脉血浆结果。HbA1c采用标准化实验室方法；无明确典型高糖症状或危象时，需要异常结果确认。","mechanism":"不同检测分别反映空腹、负荷与长期糖化。","avoid":"不能把家用指尖一次异常或妊娠筛查直接套本表；影响红细胞更新时HbA1c另评。","numbers":"FPG≥7.0 mmol/L；75 g OGTT 2h≥11.1 mmol/L；HbA1c≥6.5%；典型症状/高糖危象且随机血浆糖≥11.1 mmol/L也支持诊断。","source":"ADA2026诊断/低血糖；2024成人危象共识；D03:P0004–P0033","id":"row-1"},{"name":"低血糖三级","cues":"糖尿病治疗中血糖下降","content":"一级为警示范围，二级为明显低糖；三级按严重认知或躯体功能受损而需他人协助定义。症状不典型仍要重视测值，意识吞咽异常优先安全路径。","mechanism":"反复低糖可降低对预警症状的感知。","avoid":"三级不是再找一个更低数字；不能把非糖尿病低糖病因评估完全等同治疗中分级。","numbers":"一级：3.0≤血糖＜3.9 mmol/L；二级：＜3.0 mmol/L；三级：需他人帮助恢复，不设固定血糖下限。","source":"ADA2026诊断/低血糖；2024成人危象共识；D03:P0004–P0033","id":"row-2"},{"name":"成人DKA三项需同时具备","cues":"糖尿病或高糖背景伴酮症酸中毒","content":"糖尿病/高糖、酮症和代谢性酸中毒三部分合看。优先定量β羟丁酸，特别注意SGLT2相关或进食少时血糖可能不高。","mechanism":"酮酸生成与渗透性失水共同形成危象，尿酮检测的代谢物不同。","avoid":"不能只看血糖，也不能用酮尿单项诊断酸中毒。","numbers":"糖尿病既往史或血糖≥11.1 mmol/L；β羟丁酸≥3.0 mmol/L或尿酮≥2+；pH＜7.3和/或HCO₃⁻＜18 mmol/L。","source":"ADA2026诊断/低血糖；2024成人危象共识；D03:P0004–P0033","id":"row-3"},{"name":"成人HHS四项与混合状态","cues":"显著高糖高渗与脱水","content":"高糖、高渗、无显著酮症和无明显酸中毒四部分共同评价。若同时有DKA的酮症酸中毒标准，要考虑混合状态而非强行二选一。","mechanism":"剩余胰岛素可抑制明显酮酸生成，但不能阻止严重高糖失水。","avoid":"血浆渗透压单位及有效/总值不同，不能混用阈值。","numbers":"血浆糖≥33.3 mmol/L；有效渗透压＞300或总渗透压＞320 mOsm/kg；β羟丁酸＜3.0 mmol/L或尿酮＜2+；pH≥7.3且HCO₃⁻≥15 mmol/L。","source":"ADA2026诊断/低血糖；2024成人危象共识；D03:P0004–P0033","id":"row-4"}],"question":"哪些阈值必须联用，哪些需要重复确认？"},{"id":"dm-organ-stages","title":"肾与视网膜：分层后对应监测","axis":"diagnosis","common":"肾看白蛋白尿与eGFR双维，眼看血管增殖和黄斑是否受累。","rows":[{"name":"糖尿病相关肾损伤","cues":"白蛋白尿或eGFR异常持续","content":"结合尿白蛋白肌酐比和eGFR分层，不要求先大量蛋白尿才出现功能下降。追踪持续性并排除感染、运动、血糖剧变等暂时影响，快速下降或非典型尿沉渣要查其他病因。","mechanism":"白蛋白漏出与滤过功能反映不同损伤维度。","avoid":"传统高滤过到尿毒症的阶段不等于每位患者都会按固定顺序进展。","numbers":"UACR＜30 mg/g、30—299 mg/g、≥300 mg/g分别为正常/轻增、中增、重增；3—6个月内3份中至少2份异常有助确认持续升高，结合eGFR与病因。","source":"D03:P0009–P0010；ADA2026 CKD；NIDDK眼病资料","id":"row-1"},{"name":"非增殖与增殖性视网膜病变","cues":"眼底微血管变化，或新生血管","content":"非增殖期关注微动脉瘤、出血、渗出及缺血相关变化；增殖期出现新生血管，可出血和瘢痕牵拉。黄斑水肿单独评价，可在不同阶段损害中央视力，因此视力尚可也要筛查。","mechanism":"缺血刺激异常新生血管，渗漏影响黄斑。","avoid":"不能凭视物模糊直接分期，需散瞳眼底或相应影像专科判定。","numbers":"","source":"D03:P0009–P0010；ADA2026 CKD；NIDDK眼病资料","id":"row-2"}],"question":"为什么不能把白蛋白尿阶段或眼底阶段当作固定线性过程？"},{"id":"dm-pe-matrix","title":"糖尿病、DKA与足病护理因素","axis":"nursing","common":"区分已发生低糖、体液丢失、感染皮肤与知识问题。","rows":[{"name":"日常糖尿病的营养、活动及自理","cues":"体重异常、乏力或视力影响操作","content":"营养联系能量供需与代谢，活动联系虚弱及并发症而非病名本身。视力问题影响测糖、注射和修甲时，安排可回演的辅助和家属支持。","mechanism":"代谢与视力等功能限制改变自我管理能力。","avoid":"不能因为患者会复述五驾马车就认定能独立完成操作。","numbers":"","source":"M007逐图核查；D03:P0034–P0045、P0091–P0111","id":"row-1"},{"name":"DKA体液、电解质和气道","cues":"多尿呕吐、深快呼吸或意识改变","content":"体液不足联系渗透性利尿及胃肠丢失，电解质问题联系丢失和治疗后细胞转移。深快呼吸反映代偿，意识异常另评误吸与气道清除，连续看神经状态及治疗中变化。","mechanism":"Kussmaul呼吸本身不等于痰堵，气道问题需要相应证据。","avoid":"不能把图中所有诊断不加证据照列，避免用镇静掩盖新神经变化。","numbers":"","source":"M007逐图核查；D03:P0034–P0045、P0091–P0111","id":"row-2"},{"name":"足病的皮肤、疼痛与感染","cues":"感觉下降、缺血、溃疡或感染","content":"皮肤损伤联系供血、神经及受压，疼痛联系缺血或炎症，但无痛也可能严重。感染风险随屏障和代谢状态评估，实际感染还要记录局部和全身证据。","mechanism":"感觉丧失可掩盖组织损伤，血供不足延缓修复。","avoid":"不能用不疼来排除深部病变或继续负重。","numbers":"","source":"M007逐图核查；D03:P0034–P0045、P0091–P0111","id":"row-3"}],"question":"同为活动困难，如何写不同相关因素？"},{"id":"dm-insulin-details","title":"胰岛素制剂、保存与操作对照","axis":"treatment","common":"核对药名浓度装置及处方，操作训练由回演确认。","rows":[{"name":"制剂与进餐","cues":"基础、餐时或预混方案","content":"速效/短效用于相应餐时控制，基础制剂着眼餐间及夜间，预混同时包含不同作用部分。核对具体药品起效与处方餐时，不能仅按外观或同一支笔推断药效。","mechanism":"作用曲线不同决定覆盖的生理需求。","avoid":"不是所有胰岛素能静脉给药或互相混合，不能擅改剂型。","numbers":"","source":"D03:P0072–P0080；内科扫描PDF583–585、590–591＝印刷577–579、584–585；ADA/NHS","id":"row-1"},{"name":"保存与外观","cues":"未开封、已使用或携带外出","content":"未开封按标签冷藏，使用中核对具体制剂允许温度与期限并标记启用日期。避免冻结、日晒和过热，异常外观与规定不符时先核实再用。","mechanism":"蛋白制剂稳定性受温度与保存时间影响。","avoid":"不同制剂开封期限不能统一成28天，冻过的不能以解冻后外观正常判断可用。","numbers":"多数未开封制剂按标签在2—8℃冷藏；使用中温度上限和天数依该制剂。","source":"D03:P0072–P0080；内科扫描PDF583–585、590–591＝印刷577–579、584–585；ADA/NHS","id":"row-2"},{"name":"区域及点位轮换","cues":"长期皮下注射","content":"在腹部、上臂、大腿或臀部等适宜皮下区域按计划轮换，同一区域内有顺序换点。每次看触局部，避开硬结、感染和脂肪异常，并关注运动与部位吸收变化。","mechanism":"重复同点可产生脂肪改变，使吸收不稳定。","avoid":"换到正常组织后吸收可改变，需加强血糖观察，不在肿块上继续注射。","numbers":"同一区域相邻注射点通常至少间隔1 cm。","source":"D03:P0072–P0080；内科扫描PDF583–585、590–591＝印刷577–579、584–585；ADA/NHS","id":"row-3"},{"name":"笔式装置回演","cues":"使用胰岛素笔","content":"按具体装置检查药液、安装新针、排气并核对实际剂量，再选择合适部位完成注射及规定停留。取下针头后安全弃置并记录，护士观看每一步而不是只问会不会。","mechanism":"剂量输送、皮下注射和停留共同影响实际给药。","avoid":"不共用注射笔，不把所有针长角度或停留秒数定成统一操作。","numbers":"","source":"D03:P0072–P0080；内科扫描PDF583–585、590–591＝印刷577–579、584–585；ADA/NHS","id":"row-4"},{"name":"不良反应与夜间轨迹","cues":"低糖、局部反应或晨起高糖","content":"观察低血糖、过敏、脂肪增生/萎缩和治疗后新不适，记录与制剂时间关系。晨高先补夜间数据，区别持续升高与曾低糖，按证据联系团队调整。","mechanism":"胰岛素作用、吸收和反调节可造成不同轨迹。","avoid":"不只看晨起一个值加药，不把视物改变都归短期药物效应而漏眼病。","numbers":"","source":"D03:P0072–P0080；内科扫描PDF583–585、590–591＝印刷577–579、584–585；ADA/NHS","id":"row-5"}],"question":"大区域轮换与同一区域内换点分别防什么？"}],"drills":[{"id":"dm-drill-keto","title":"血钾不低也不能放心","stem":"糖尿病患者呕吐、深快呼吸、脱水，检查见酮症和酸中毒，初次血钾在正常偏高范围。","prompt":"解释为什么仍需连续观察钾及循环。","answer":["DKA可总体缺钾，细胞转移和脱水让初次血值不低。","治疗后血钾可下降，需联动心电、肾功能、尿量及治疗反应。","血糖、酮体酸碱和灌注都要复评，不能只看血糖下降。"],"source":"D03:P0007、P0020–P0025、P0081–P0086；M006/M009题型目标；原创变式"},{"id":"dm-drill-kidney","title":"长期糖尿病出现水肿","stem":"长期糖尿病者水肿、血压上升并出现肾功能异常，还说最近视物模糊。","prompt":"怎样避免只写一个糖尿病护理模板？","answer":["分别补肾病与其他水肿原因、容量、尿蛋白及肾功能趋势。","视物改变需眼科评估，不把所有症状自动归一种并发症。","护理把容量、营养、血糖用药及靶器官随访并列，并据证据排序。"],"source":"D03:P0009–P0010、P0019；M008题型目标；原创变式"},{"id":"dm-drill-meal","title":"把低糖预防落实到一天","stem":"一位使用降糖药的学生晨练后才吃早饭，近日反复出汗心慌，却只记录睡前血糖。","prompt":"该补什么记录和教育？","answer":["发作时尽快测糖并按流程处理，意识和吞咽决定补糖路径。","记录药物、实际餐时、晨练及发作时间，补与症状相对应的测糖。","教会携带应急糖和联系信息，调整由方案与团队决定，不自行改药。"],"source":"D03:P0044、P0064–P0065、P0100；原创变式"}],"references":[{"title":"ADA 低血糖与15分钟复测","url":"https://diabetes.org/living-with-diabetes/hypoglycemia-low-blood-glucose"},{"title":"2024成人高血糖危象多学会共识","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC11272983/"},{"title":"ADA2026 糖尿病诊断","url":"https://diabetesjournals.org/care/article/49/Supplement_1/S27/163926/2-Diagnosis-and-Classification-of-Diabetes"},{"title":"ADA2026 低血糖级别","url":"https://diabetesjournals.org/compendia/article/2026/1/7/172319"},{"title":"ADA2026 慢性肾病评估","url":"https://doi.org/10.2337/dc26-s011"},{"title":"NIDDK 糖尿病眼病","url":"https://www.niddk.nih.gov/health-information/diabetes/overview/preventing-problems/diabetic-eye-disease"},{"title":"ADA 胰岛素储存与安全","url":"https://diabetes.org/health-wellness/medication/insulin-storage-and-syringe-safety"},{"title":"NHS 胰岛素注射部位与反应","url":"https://www.nhs.uk/medicines/insulin/intermediate-acting-insulin/side-effects-of-intermediate-acting-insulin/"},{"title":"ADA 胰岛素笔使用","url":"https://diabetes.org/about-diabetes/devices-technology/insulin-pens"}]},"neuro":{"title":"神经系统：按变化分流，按风险护理","intro":"先背气道、神经观察、继发损伤、功能维护；再用出血、缺血和外伤线索选择个性条目。","framework":[{"id":"neuro-airway","title":"共性一：气道与吞咽","cue":"意识下降、流涎、湿嗓或呛咳","answer":"观察呼吸节律、血氧、分泌物及有效咳嗽；不能保护气道时立即升级。吞咽筛查前不经口给水、食物或药物，评估后明确食物性状、体位和替代途径。","why":"意识、感觉和吞咽协调下降会造成误吸；血氧正常不代表吞咽安全。","source":"D10:P0126,P0133–P0142,P0151–P0154"},{"id":"neuro-observe","title":"共性二：记录变化而非只记总分","cue":"意识、瞳孔、语言或肢体变化","answer":"并列记录GCS分项、双侧瞳孔大小及反应、语言、肢体活动和生命体征；与最近一次正常状态比较。新发瞳孔不等大、运动反应下降或呼吸异常即时报告，并标记镇静、失语或插管的影响。","why":"同一总分可由不同功能缺损构成；趋势有助于发现血肿、水肿与脑灌注变化。","source":"D10:P0127–P0131,P0233–P0239"},{"id":"neuro-secondary","title":"共性三：减少继发损伤","cue":"颅压增高、脑水肿或外伤","answer":"保持头颈中立和气道通畅，体位结合颈椎、血压及术式；减少屏气、颈部压迫与用力排便。高渗治疗后追踪血压、尿量、电解质和肾功能；镇静后检查呼吸与神经反应。","why":"缺氧、低灌注和静脉回流受阻可叠加损伤；降颅压同时需维持灌注。","source":"D10:P0122–P0125,P0143–P0150,P0188–P0193"},{"id":"neuro-function","title":"共性四：把康复写成可评价目标","cue":"病情稳定、偏瘫、语言或活动障碍","answer":"评估患侧运动、皮肤、关节和日常生活能力，实施减压、良肢位与循序活动。出院核对用药、危险因素、复查及再发信号，请患者或家属复述安全转移、进食与求助步骤。","why":"卧床和感觉运动缺损共同增加压力损伤、失用和坠伤风险。","source":"D10:P0155–P0159,P0210–P0225,P0269–P0271"}],"contrasts":[{"id":"neuro-patterns","title":"诊断差异：出血、缺血与外伤","axis":"diagnosis","common":"共记起病时间、局灶体征、意识与危险背景，再由影像确认病变。","rows":[{"id":"neuro-patterns-ich","name":"脑出血","cues":"突发偏瘫伴头痛呕吐、血压升高","content":"优先关注脑实质出血、血肿扩大与颅高压，记录意识瞳孔肢体基线。急诊影像分型后分别落实血压、凝血和手术评价，观察相应治疗反应。","mechanism":"血肿占位与水肿既影响局部功能，也可能威胁脑灌注。","numbers":"","avoid":"不凭活动时发病或高血压就确诊；不套用缺血性卒中的抗栓措施。","source":"D10:P0008–P0012,P0121–P0164"},{"id":"neuro-patterns-ischemic","name":"脑血栓形成与脑栓塞","cues":"安静时起病或骤达高峰；动脉粥样硬化、房颤背景","content":"两者均可造成局灶缺血，栓塞更应追查心源性等来源；起病速度只能提示方向。记录最后正常时间、抗凝药和近期出血手术史，影像后评估再灌注，并按病因选择二级预防。","mechanism":"原位血栓和远处栓子来源不同，恢复灌注与预防复发的路径也有差异。","numbers":"","avoid":"不凭时间一项决定溶栓，不自行给予抗栓药。","source":"D10:P0013–P0017,P0148,P0210–P0219"},{"id":"neuro-patterns-tia","name":"TIA","cues":"短暂单眼视力缺失、言语或单侧无力后恢复","content":"完整记录症状及持续过程；症状恢复后仍须紧急评价卒中风险。结合影像、血管和心律检查寻找病因，并把危险因素控制与复发预防连接。","mechanism":"短暂症状可提示持续存在的栓塞或灌注危险。","numbers":"","avoid":"不以恢复时间代替现代TIA评估，也不因症状消失而取消检查。","source":"D10:P0018–P0022,P0217"},{"id":"neuro-patterns-sah","name":"蛛网膜下腔出血","cues":"雷击样头痛、呕吐、颈强，可无偏瘫","content":"先行急诊CT，确诊后以血管检查寻找出血原因；阴性CT后的进一步检查取决于时间与专业判断。突然再发剧痛、神经恶化或进行性意识下降，分别警惕再出血、迟发缺血和脑积水。","mechanism":"血液刺激脑膜；再出血、血流障碍和脑脊液循环受阻是不同恶化机制。","numbers":"","avoid":"不把所有头痛都列为必须腰穿，也不靠固定卧床天数替代病情判断。","source":"D10:P0023–P0028,P0049–P0053"},{"id":"neuro-patterns-epidural","name":"硬膜外血肿","cues":"外伤后曾好转，随后又嗜睡、头痛或呕吐","content":"中间清醒期提示血肿可能扩大，但并非每位患者都有完整过程。结合双凸形CT、瞳孔与对侧运动变化，立即启动神经外科评价。","mechanism":"扩大血肿可在最初好转后产生占位压迫。","numbers":"","avoid":"不能等待完整三阶段，也不能用曾经清醒排除颅内损伤。","source":"D10:P0083–P0086,P0301"},{"id":"neuro-patterns-subdural","name":"硬膜下血肿：急性与慢性","cues":"重伤后持续意识障碍，或老年轻伤后缓慢改变","content":"急性者常与脑挫裂伤并存，意识持续异常或进行性恶化；慢性者可表现为认知、步态及局灶改变。CT常呈新月形，护理同时核对外伤时间、抗栓药与症状趋势。","mechanism":"出血速度、间隙及伴随损伤决定急慢性表现差异。","numbers":"","avoid":"不把无中间清醒期作为单项确诊，也不因伤轻而忽略慢性血肿。","source":"D10:P0087–P0094"},{"id":"neuro-patterns-contusion","name":"脑挫裂伤","cues":"头伤后意识障碍、局灶症状或之后继续恶化","content":"组织挫伤、出血和水肿可同时存在，影像显示损伤区域的混合改变。重复评估意识、肢体和体温，警惕迟发血肿、水肿、癫痫及低氧。","mechanism":"继发水肿与出血可在原发损伤后继续扩大功能缺损。","numbers":"","avoid":"不把嗜睡全归因于疲劳或镇痛；不常规套用激素治疗创伤性脑损伤。","source":"D10:P0095–P0098,P0280–P0283"},{"id":"neuro-patterns-open","name":"开放性颅脑损伤","cues":"伤口异物或脑组织暴露","content":"先评估气道循环及颈椎风险，再覆盖保护伤口并准备紧急专科处理。记录伤口、出血、异物及意识变化，配合清创、感染和破伤风风险评价。","mechanism":"盲目移动异物或压迫组织会扩大损伤与出血。","numbers":"","avoid":"不压回暴露组织、不拔嵌入物，不套用普通浅表伤口的加压清洗。","source":"D10:P0227–P0232,P0288–P0291"}],"question":"哪些题干线索改变了后续路径？"},{"id":"neuro-assessment","title":"检查与意识分层","axis":"labs","common":"先问检查回答什么问题，再比较结果；床旁反应与评分同时记录。","rows":[{"id":"neuro-assessment-imaging","name":"CT、DWI与血管检查","cues":"疑似卒中或头伤","content":"CT快速识别急性出血、明显血肿和占位，早期缺血可尚不明显。DWI侧重早期缺血，CTA/MRA/DSA侧重血管狭窄、闭塞或出血原因，按急诊任务选择。","mechanism":"各检查反映血液密度、弥散或血管腔等不同信息。","numbers":"","avoid":"CT暂正常不能单独排除缺血，不要求人人同时完成全部检查。","source":"D10:P0029–P0078"},{"id":"neuro-assessment-conscious","name":"意识程度与GCS","cues":"难唤醒、反应异常或睁眼无交流","content":"嗜睡可唤醒简单应答，昏睡需较强刺激才短暂反应；昏迷不能被唤醒，再比较疼痛反应、保护反射和生命体征。意识模糊、谵妄重在注意力与内容；GCS分别记睁眼、语言、运动并注明插管失语镇静，睁眼并不保证正常意识。 浅昏迷仍可有疼痛回避与保护反射，中昏迷反射和防御减弱，深昏迷反应与反射明显丧失；特殊的睁眼无交流状态需区别植物状态、无动性缄默等。","mechanism":"觉醒水平与意识内容是不同轴；相同总分可包含不同损害。","numbers":"GCS：睁眼为自主4、对声音3、对压力2、无1；语言为定向正常5、混乱4、可辨词语3、仅声音2、无1；运动为遵指令6、定位5、正常屈曲/回避4、异常屈曲3、伸展2、无1。可测分项总分3–15；不可测分项注明原因，不编造总分。","avoid":"评分不替代全神经评估，特殊意识状态需专科鉴别，不能仅用深浅昏迷命名。","source":"D10:P0194–P0209;M045,M046图片核对;GCS结构化评分项目"},{"id":"neuro-assessment-base","name":"颅底骨折：前中后窝","cues":"眶周或乳突瘀斑、鼻耳漏、后组脑神经异常","content":"前窝联系眶周瘀斑、鼻漏和嗅视功能；中窝联系耳漏、乳突瘀斑及面听神经；后窝注意枕部瘀斑、吞咽与后组神经。疑似脑脊液漏记录量性质并评估感染，避免堵塞冲洗及鼻腔置管。","mechanism":"颅窝邻近结构决定体征，破口可形成颅内感染通道。","numbers":"","avoid":"月晕不是独立确诊试验，不凭一项瘀斑定位全部骨折，也不自行改头低位。","source":"D10:P0099–P0110,P0274–P0279,P0299"}],"question":"为什么总分、影像和完整神经查体不能相互代替？"},{"id":"neuro-rescue","title":"急变与治疗监测","axis":"treatment","common":"先维持气道灌注，再针对病因处理；观察与记录贯穿急救。","rows":[{"id":"neuro-rescue-herniation","name":"两类脑疝","cues":"意识恶化伴瞳孔、偏瘫或呼吸改变","content":"小脑幕切迹疝常伴同侧瞳孔异常和对侧运动障碍；枕骨大孔疝可较早出现呼吸循环失常。立即启动急救，支持气道通气、建立监测通路并准备专科降颅压及手术，持续评价反应。","mechanism":"前者涉及钩回及脑干压迫，后者向下移位可直接威胁延髓。","numbers":"","avoid":"不等待完整体征次序，也不把固定药物三联推广到全部病因。","source":"D10:P0111–P0118,P0161–P0164"},{"id":"neuro-rescue-temperature","name":"体温管理与亚低温","cues":"已有目标温度治疗方案或高热","content":"核对温度目标与降温复温计划，连续看核心温度、寒战、循环、意识、电解质、血糖和凝血。观察冷伤、压力损伤与感染，复温时特别记录血压和神经变化。","mechanism":"寒战增加代谢耗氧；温度变化影响循环和电解质分布。","numbers":"","avoid":"预防性低温不是所有创伤性脑损伤的常规方案，不套固定温度、天数或复温速度。","source":"D10:P0171–P0175"},{"id":"neuro-rescue-drugs","name":"癫痫与高渗/镇静观察","cues":"抽搐或使用降颅压镇静药","content":"记录发作时间、动作、意识及恢复，保护气道和头部，不强压肢体或向口内塞物。高渗与镇静分别追踪血压、尿量、电解质、肾功能及呼吸，标记药后神经反应变化。","mechanism":"发作增加耗氧，药物可能改变容量或掩盖神经表现。","numbers":"","avoid":"既不把药后反应全当病情恶化，也不把新恶化全归因于药物。","source":"D10:P0143–P0150,P0193,P0250–P0255"}],"question":"意识下降后哪些线索提示脑疝或治疗并发症？"},{"id":"neuro-care","title":"装置、进食与长期并发症","axis":"nursing","common":"共性问题与个性装置分别列；措施应能回答做什么、观察什么、如何评价。","rows":[{"id":"neuro-care-evd","name":"脑室外引流","cues":"引流量突然改变、液色异常或无液流","content":"核对处方高度和解剖零点，变换体位后由受训人员校准；记录液量颜色、颅压/波形、切口和神经变化。无液流先排查夹闭、扭折、体位和高度改变，再报告可能阻塞或压力变化；突然增多也须评价过度引流。","mechanism":"高度差决定压力阈值，过高可不足、过低可过度引流。","numbers":"","avoid":"不自行调低、抽拔旋转导管或冲洗；移动夹管遵具体装置监护方案。","source":"D10:P0176–P0187"},{"id":"neuro-care-feeding","name":"吞咽与经口进食","cues":"湿嗓、口腔残留、咳嗽或疲劳","content":"专业评估后确定食团性状、液体稠度和坐起支持；少量慢速、专注进食，观察残留和疲劳。代偿动作须个体选择，出现呛咳、呼吸改变时停止并重新评价营养途径。","mechanism":"食团控制与气道关闭不协调造成误吸，疲劳可使原本安全方式失效。","numbers":"急性卒中吞咽筛查：入院后尽早，质量指标要求4小时内；住院中发病者按发病后4小时内。由受训人员完成，且必须在首次经口食物、液体或药物之前。","avoid":"不统一规定转头方向或禁用吸管，不用一口水试验代替规范筛查。 4小时是完成时效目标，不能理解为等待4小时后才能评估，也不能未通过就到时喂食。","source":"D10:P0138–P0142;NICE IND36"},{"id":"neuro-care-complication","name":"预防、术后及出院","cues":"卧床、颅内术后、去骨瓣或卒中恢复","content":"共性核对减压、关节活动、排便、口腔气道和营养；增加消化道出血、癫痫、血栓、眼睑闭合不全的观察。辨认不同引流和术式体位；出院按病因管理血压血糖血脂、房颤与吸烟，训练家属识别再发。","mechanism":"卧床带来多条风险链，而装置和颅骨缺损增加特定防护要求。","numbers":"","avoid":"不按摩持续发红皮肤，不把某类血肿引流体位用于全部手术，不自行加抗栓。","source":"D10:P0188–P0193,P0210–P0225,P0256–P0271"}],"question":"这道题比共性骨架多出哪条护理？"}],"drills":[{"id":"neuro-drill-stroke","title":"晨起无力，先补哪条信息","stem":"患者晨起右手持杯困难、言语含糊，昨晚睡前正常；家属准备喂水。","prompt":"分别列共性、个性和错用措施。","answer":["共性：评估气道、血糖、意识瞳孔肢体及生命体征，记录趋势。","个性：最后正常时间是昨晚睡前，另记发现时间；尽快影像分型，配合再灌注资格评价。","个性：吞咽筛查前不喂水食物或口服药，安排替代途径。","错用：不以晨起发病确定脑血栓，不在未排出血时自行抗栓。"],"source":"D10:P0008–P0028,P0138–P0142,P0303–P0307"},{"id":"neuro-drill-trauma","title":"曾清醒，后来又难唤醒","stem":"头伤者曾能交谈，后来反复呕吐、嗜睡，一侧瞳孔反应变慢，耳道有血性液体。","prompt":"提出优先危险、检查与耳部护理，说明不能做什么。","answer":["共性：立即升级气道和神经观察，记GCS分项、瞳孔与生命体征。","个性：血肿扩大及脑疝需警惕，急诊影像与神经外科评价；耳漏提示颅底损伤可能。","个性：保护并观察漏液及感染征象，不堵塞冲洗、不鼻腔置管。","错用：不因曾清醒而等待，不为验证漏液让患者反复擤鼻。"],"source":"D10:P0083–P0118,P0308–P0312"},{"id":"neuro-drill-conscious","title":"证明意识程度，不能只写名称","stem":"患者不能唤醒，疼痛刺激时有回避，角膜与吞咽反射尚存在；CT已证实脑内出血，恢复后仍有偏瘫。","prompt":"怎样用表现说明意识状态？急性护理与出院指导分别是什么？","answer":["意识：根据不能唤醒、疼痛回避和部分反射保留描述浅昏迷特征，另记GCS分项，不能从文字猜缺失分数。","共性：保护气道、观察意识瞳孔生命体征和肢体，关注吞咽与继发损伤。","个性：脑出血时关注血压、凝血及颅压分支，不套缺血抗栓。","出院：病因和危险因素管理、偏瘫功能训练、防坠伤及再发预警，请家属复述。"],"source":"D10:P0194–P0209,P0210–P0225;M043,M047图片病例目标"}],"references":[{"title":"NICE：卒中与TIA","url":"https://www.nice.org.uk/guidance/ng128/chapter/recommendations"},{"title":"NICE：头部损伤与GCS","url":"https://www.nice.org.uk/guidance/ng232/chapter/recommendations"},{"title":"NICE：蛛网膜下腔出血","url":"https://www.nice.org.uk/guidance/ng228/chapter/Recommendations"},{"title":"BTF：重型颅脑损伤","url":"https://braintrauma.org/s/Management_of_Severe_TBI_ExecSmry_4th_Edition.pdf"},{"title":"RCH：脑室引流装置护理原则","url":"https://www.rch.org.au/rchcpg/hospital_clinical_guideline_index/External_Ventricular_Drains_and_Intracranial_Pressure_Monitoring/"},{"title":"GCS原始项目：结构化评分","url":"https://www.glasgowcomascale.org/gcs-aid/"},{"title":"NICE IND36：卒中吞咽筛查时效","url":"https://www.nice.org.uk/indicators/ind36-stroke-and-ischaemic-attack-4-hour-swallowing-assessment/IND36-20260220.pdf"}]},"hematology":{"title":"血液系统：贫血、出血、感染三条主线","intro":"先用三条主线列共性观察与护理，再按红细胞生成、破坏、止血机制和具体药物增加差异。","framework":[{"id":"hematology-anemia","title":"共性一：贫血看供氧与原因","cue":"乏力、苍白、心悸、气促","answer":"记录Hb及变化、脉搏、血压、活动后症状；胸痛、晕厥或静息气促时优先升级评估。根据耐受安排休息和协助活动，再用细胞大小、网织反应及铁/B12等证据寻找病因。","why":"Hb下降降低携氧能力，但耐受还受下降速度与心肺状态影响。","source":"D12:P0001–P0015,P0063–P0075,P0128"},{"id":"hematology-bleeding","title":"共性二：出血分部位、程度与原因","cue":"瘀点、牙龈渗血、黑便、血尿或深部疼痛","answer":"记录部位、量、持续时间与灌注；核对血小板、凝血和相关药物。避免碰撞和粗糙食物，减少不必要穿刺并观察止血效果；头痛呕吐、神志变化或咽喉肿胀立即升级。","why":"血小板、凝血因子和血管壁异常的出血模式不同；少量皮黏出血不能代表全身风险低。","source":"D13:P0137–P0171"},{"id":"hematology-infection","title":"共性三：感染找入口与全身反应","cue":"发热、寒战、咽痛、口腔破损或粒细胞减少","answer":"观察体温、循环、意识和呼吸，核对中性粒细胞绝对值并查口腔、肺、皮肤、肛周和导管。及时留合适标本并配合抗感染处理；保持手卫生、黏膜皮肤完整和导管无菌维护。","why":"中性粒细胞减少时感染可快速进展，局部炎症表现反而不明显。","source":"D13:P0172–P0195"},{"id":"hematology-therapy","title":"共性四：药物安全与生活支持","cue":"化疗、免疫抑制或长期补充治疗","answer":"先认药名、通路和毒性靶器官，再追踪血象、肝肾与症状；核对治疗周期及复查。提供适合口腔和胃肠耐受的食物，评估骨痛、脱发、形象改变和家庭支持，以能否进食、活动和按时返院评价效果。","why":"治疗既控制原病，也可能引起骨髓抑制、器官损害或心理负担。","source":"D13:P0088–P0133,P0196–P0205"}],"contrasts":[{"id":"hematology-red-cells","title":"贫血差异：生成少、原料少还是破坏多","axis":"diagnosis","common":"先证实贫血，再用细胞形态、网织反应与病因证据分流。","rows":[{"id":"hematology-red-cells-ida","name":"缺铁性贫血","cues":"慢性失血、摄入不足，可能伴反甲或口角炎","content":"常见小细胞低色素，结合铁蛋白、血清铁和总铁结合力判断铁缺乏；同时追查月经过多、消化道失血或吸收问题。护理联系乏力、黏膜改变与补铁疗效，不仅盯Hb恢复。","mechanism":"铁不足影响血红蛋白合成，贮存铁不足可早于明显贫血。","numbers":"","avoid":"炎症可升高铁蛋白；不凭小细胞或Hb低就直接补铁。","source":"D12:P0012,P0074,P0080,P0086–P0097"},{"id":"hematology-red-cells-megaloblastic","name":"巨幼细胞性贫血","cues":"大细胞、舌炎、营养或吸收问题，可能伴麻木步态改变","content":"结合B12和叶酸状态寻找DNA合成原料问题，骨髓可见核成熟落后于胞浆的改变。询问胃肠疾病、饮食和药物，观察感觉步态及认知；补充治疗要与缺乏原因对应。","mechanism":"核酸合成受阻使核成熟落后；B12缺乏还可损伤神经。","numbers":"","avoid":"不能只见大细胞就定病因；未查B12时不以单补叶酸掩盖神经风险。","source":"D12:P0013;D13:P0016"},{"id":"hematology-red-cells-hemolysis","name":"溶血性贫血","cues":"贫血伴黄疸、脾大或尿色变深","content":"网织红细胞、间接胆红素等帮助寻找红细胞破坏证据，直接抗球蛋白试验支持部分免疫性原因。观察尿量尿色、腰腹痛、循环与肾功能，追问感染、药物及既往诱发史。","mechanism":"红细胞破坏超过代偿，胆红素增加；部分急性血管内溶血可损害肾脏。","numbers":"","avoid":"Coombs阳性不能概括所有溶血，饮水安排须结合心肾状态。","source":"D12:P0014,P0075,P0083;D13:P0017,P0079"},{"id":"hematology-red-cells-aplastic","name":"再生障碍性贫血","cues":"多系血细胞减少伴贫血、感染或出血","content":"结合骨髓低增生与外周多系减少，排除其他骨髓病因；不能把全血细胞减少自动当白血病。重症评价联系骨髓及中性粒、血小板、网织绝对值，护理同时展开感染和出血防护。","mechanism":"造血储备下降同时影响三系；ANC尤其联系严重感染风险，血小板联系止血，网织绝对值反映红细胞生成。骨髓与至少两项外周指标相结合，避免用一个低值过度分型。","numbers":"SAA组合标准：骨髓细胞量<25%，或25%–50%且残余造血细胞<30%；再满足外周三项中至少两项：ANC<0.5×10⁹/L、血小板<20×10⁹/L、网织红细胞绝对值<60×10⁹/L（自动计数标准）。VSAA在SAA基础上ANC<0.2×10⁹/L。","avoid":"不只凭一个计数判重型，也不把层流病房或绝对卧床作为所有患者默认措施。 自动与手工网织计数的标准不混用；须排除其他低增生骨髓疾病，不能由一次ANC直接命名SAA或NSAA。","source":"D12:P0015–P0036,P0098–P0101;D13:P0018–P0039;BSH2024;BloodAdvances2024重型再障共识"}],"question":"同样Hb下降，为什么不能都补铁？"},{"id":"hematology-hemostasis","title":"出血差异：血小板、血管与凝血","axis":"labs","common":"把出血模式与血小板、PT/APTT、纤维蛋白原等组合解释。","rows":[{"id":"hematology-hemostasis-itp","name":"ITP","cues":"皮肤黏膜出血，以血小板减少突出","content":"结合孤立性血小板减少、出血表现和排除诊断评价ITP；复核药物、感染及其他血液疾病。追踪黏膜及内脏出血，治疗强度结合出血程度、计数趋势和患者风险。","mechanism":"免疫相关血小板破坏及生成受影响使初级止血受损。","numbers":"","avoid":"不凭瘀点确诊，不将所有血小板低归为ITP，也不按单一阈值自动输血。","source":"D12:P0038;D13:P0041"},{"id":"hematology-hemostasis-iga","name":"IgA血管炎/过敏性紫癜","cues":"可触性紫癜伴腹痛、关节痛或尿异常","content":"血小板常不减少，结合皮肤、关节、腹部与肾脏表现判断系统受累。观察腹痛部位性质、便血、关节肿痛与活动、尿量尿色及尿检，腹部恶化及时复评。","mechanism":"小血管炎症可同时影响皮肤、肠道、关节及肾脏。","numbers":"","avoid":"不将紫癜全部当血小板减少；血小板正常不排除严重肾或胃肠受累。","source":"D12:P0039,P0076;D13:P0042,P0080"},{"id":"hematology-hemostasis-dic","name":"DIC","cues":"严重感染、创伤或肿瘤背景，渗血并灌注异常","content":"结合原发病与动态血小板下降、PT等凝血改变、纤维蛋白原和纤维降解指标判断。记录穿刺口渗血、皮肤、尿量、意识与循环；治疗重点包括原发病控制及按出血/血栓状态选择支持。","mechanism":"广泛凝血激活消耗止血成分，并可导致微循环障碍，所以血栓与出血可并存。","numbers":"","avoid":"单项D二聚体升高不能确诊；不能将肝素视为所有DIC必用。","source":"D12:P0040,P0103;D13:P0043,P0106"},{"id":"hematology-hemostasis-hemophilia","name":"血友病A/B","cues":"自幼或家族出血、深部肌肉/关节血肿","content":"A型联系凝血因子VIII，B型联系IX；常见凝血途径异常，确诊需因子活性等检查。观察关节疼痛肿胀、活动和远端神经血管，避免损伤及不必要肌注，配合专科止血治疗与关节保护。","mechanism":"凝血因子缺陷影响继发止血，深部出血比单纯皮黏瘀点更典型。","numbers":"","avoid":"不以APTT一项确定类型；关节血肿不能热敷按摩或强行活动。","source":"D12:P0041–P0043,P0146–P0148;D13:P0044–P0046"},{"id":"hematology-hemostasis-severity","name":"成人贫血：Hb判定与严重程度","cues":"Hb降低或多系计数显著下降","content":"先确认年龄、性别、妊娠和居住海拔，再将Hb与相应界值比较；以WHO 2024的分组判断贫血及严重程度。随后联系下降速度、活动症状和心肺状态，不把严重度分级当成输血指令。","mechanism":"Hb反映血液携氧能力；性别和生理状态影响界值，下降速度及代偿决定同一浓度的症状。高海拔可使Hb适应性升高，必须先调整再比较。","numbers":"WHO 2024，15–65岁：非妊娠女性Hb<120 g/L、男性<130 g/L判贫血；女性轻度110–119、男性轻度110–129，中度均80–109，重度均<80 g/L。1 g/dL=10 g/L。","avoid":"不把此年龄段直接用于65岁以上、儿童或孕妇；慢性分级不代替急性失血的循环评估，也不与其他分级表拼接。海拔调整可从实测Hb减去调整量，或给判定界值加同一量，二选一，不能重复校正。","source":"D12:P0001–P0036;D13:P0004–P0039;PDF16:PDF页1;WHO2024表2–4"},{"id":"hematology-hemostasis-pregnancy-altitude","name":"妊娠与海拔：同一Hb为何结论不同","cues":"孕期或居住高海拔地区，需解释Hb数值","content":"妊娠按孕早、中、晚期分别选择阈值，不能把非妊娠女性界值直接套用。居住海拔造成的适应性升高另作调整，再与所选人群比较；吸烟也需核对相应调整规则。","mechanism":"孕期血浆容量扩张产生稀释效应，高海拔低氧则促进红细胞生成，两种影响方向不同。","numbers":"WHO 2024：孕早/晚期Hb<110 g/L，轻度100–109、中度70–99、重度<70；孕中期<105 g/L，轻度95–104、中度70–94、重度<70。海拔500–999 m时实测Hb减4 g/L，1000–1499 m减8 g/L；如Hb 124 g/L、海拔1200 m，调整为116 g/L。","avoid":"海拔例子是换算演示，不是完整高海拔调整表；更高海拔按对应分段/公式，不能线性外推。孕期界值用于识别贫血，不独立决定补铁、输血或住院。","source":"D12:P0001–P0015;WHO2024表2–4"}],"question":"皮肤瘀点与关节血肿为何需要不同检查？"},{"id":"hematology-malignancy","title":"恶性血液病：浸润与生成受抑分开记","axis":"diagnosis","common":"共性是贫血、感染与出血；个性在细胞来源、浸润部位及分子证据。","rows":[{"id":"hematology-malignancy-acute","name":"AML/ALL与APL等亚型","cues":"发热贫血出血伴骨痛、肝脾或淋巴结改变","content":"AML/ALL需形态、免疫分型及遗传学联合确认；外周白细胞不一定升高。APL尤其警惕凝血异常和早期出血，ALL等需关注中枢受累线索；新发头痛呕吐不能只归于化疗。","mechanism":"异常克隆扩增既挤占正常造血，也可浸润骨、组织和中枢。","numbers":"","avoid":"不把FAB口诀代替现代分型，也不将固定原始细胞阈值套用于所有遗传学定义亚型。","source":"D12:P0044–P0051;D13:P0047–P0054"},{"id":"hematology-malignancy-chronic","name":"CML与CLL","cues":"持续白细胞增多伴巨脾，或老年淋巴细胞增多","content":"CML联系髓系增殖和BCR::ABL1证据；CLL需确认克隆性B淋巴细胞并评价淋巴结、脾及血象。观察腹胀早饱、感染与细胞减少趋势，治疗选择按病期及症状。","mechanism":"不同克隆来源和驱动改变决定病程及靶向选择。","numbers":"","avoid":"不把所有白细胞增高当感染，也不把所有慢性白血病当同一病。","source":"D12:P0052–P0054;D13:P0055–P0057"},{"id":"hematology-malignancy-lymphoma","name":"淋巴瘤","cues":"持续无痛淋巴结肿大伴发热盗汗或消瘦","content":"记录淋巴结部位、进展和全身症状，结合组织病理及免疫等确定类型。评估压迫、呼吸吞咽和营养影响，检查用于分期及后续疗效比较。","mechanism":"淋巴细胞肿瘤可在结内外生长，组织类型决定治疗。","numbers":"","avoid":"不凭一个肿大淋巴结或发热确诊，不以血常规正常排除。","source":"D12:P0055;D13:P0058"},{"id":"hematology-malignancy-myeloma","name":"多发性骨髓瘤","cues":"骨痛、贫血、肾损害或高钙线索","content":"按CRAB联系高钙、肾损害、贫血和骨病变，结合单克隆蛋白与骨髓等确认。观察疼痛、尿量、意识与骨折风险，协助轴线转移和安全活动，不能只处理疼痛。","mechanism":"异常浆细胞及其产物可损伤骨和肾脏，贫血来自造血受影响。","numbers":"","avoid":"无完整CRAB不能自行排除；不在不明骨痛部位强行按摩或负重。","source":"D12:P0056,P0066,P0167;D13:P0059,P0071"}],"question":"哪些体征决定追加骨髓、组织或分子检查？"},{"id":"hematology-medicines","title":"治疗差异：药物—毒性—观察","axis":"treatment","common":"共性核对药名、途径、周期和反应；个性是每个药物的靶器官与专门措施。","rows":[{"id":"hematology-medicines-iron","name":"口服与静脉铁剂","cues":"已证实缺铁并接受补铁","content":"口服铁剂关注胃肠不适、依从性及食物药物相互作用，解释可能黑便并区分伴灌注异常的出血。静脉铁剂核对具体制剂与输注方案，观察过敏、低血压及局部渗漏；追踪Hb与贮存铁而不在症状好转时自行停药。","mechanism":"口服吸收受相互作用影响，静脉给药增加输注反应与局部染色风险。","numbers":"","avoid":"不把液体铁吸管要求套到片剂，不把肌注试验剂量用于所有现代制剂。","source":"D12:P0086–P0097;D13:P0088–P0101"},{"id":"hematology-medicines-aplastic","name":"再障免疫治疗","cues":"使用ATG、环孢素或其他专科方案","content":"ATG输注关注过敏、输注反应及感染；环孢素追踪血压、肾功能、电解质及规定的血药浓度。使用雄激素等方案时另看肝功能和制剂给药要求，按药名逐项对应监测。","mechanism":"免疫调节可改善造血，但会增加感染及特定器官毒性。","numbers":"","avoid":"不把过敏试验、注射路径和药物组合视为所有方案通则。","source":"D12:P0098–P0101;D13:P0102–P0104"},{"id":"hematology-medicines-chemo","name":"化疗药物毒性对照","cues":"化疗后口腔痛、血尿、麻木、心悸或气促","content":"甲氨蝶呤关注口腔黏膜、血象和肾功能，特定方案核对亚叶酸钙解救时序；CTX关注尿痛血尿和水化排尿计划；蒽环类关注心功能，长春新碱关注周围神经及便秘。分化治疗后新发发热、体重增加、水肿、低血压或气促应警惕分化综合征；鞘内治疗另看头痛、神经反应和感染。","mechanism":"各药损伤靶器官不同，不能用骨髓抑制一项概括全部毒性。","numbers":"","avoid":"不把所有口腔溃疡视为真菌感染；不自行碱化尿液，也不把一个解救方案用于所有化疗。","source":"D12:P0104–P0110;D13:P0107–P0116"},{"id":"hematology-medicines-extravasation","name":"外渗与化学性静脉炎","cues":"输注处疼痛、烧灼、肿胀或血管走向红痛","content":"疑外渗立即停止输注并呼叫受训团队，保留通路供回抽/处理，不冲管；标记范围、评估远端血运和组织变化，记录药名浓度量及时间。冷热敷和解毒剂按具体药物：蒽环与长春碱类不能套同一种方法；沿静脉红痛的静脉炎也需停用评估该通路。","mechanism":"外渗使药物进入组织，静脉炎主要累及血管；药物性质决定组织处置。","numbers":"","avoid":"不按摩挤压、不立即盲目拔掉全部通路，不把冷敷热敷通用化。","source":"D12:P0111–P0126;D13:P0117–P0133"}],"question":"患者多出一条什么用药，你的观察清单就要多什么？"},{"id":"hematology-care","title":"护理差异：问题、相关因素与部位","axis":"nursing","common":"现存问题写表现，危险问题写风险因素；不要让风险名称掩盖已发生的出血或感染。","rows":[{"id":"hematology-care-bleeding-sites","name":"按部位预防与识别出血","cues":"瘀点、鼻牙龈血、关节肿、黑便或头痛","content":"皮肤减少碰撞、抓挠和创伤；鼻牙龈避免抠鼻、硬食及黏膜损伤，观察局部压迫效果。关节深部血肿保护制动并评价远端功能；咽喉肿胀警惕气道，黑便血尿观察灌注，突发头痛呕吐视力或意识改变立即升级。","mechanism":"同是出血，气道、颅内和深部血肿的隐蔽性及后果不同。","numbers":"","avoid":"不因皮肤血少就忽略内脏；不热敷按摩关节血肿，输注血制品须结合适应证与反应。","source":"D13:P0137–P0171"},{"id":"hematology-care-infection-sites","name":"按入口预防感染与发热观察","cues":"化疗后、黏膜破损、导管或粒细胞减少","content":"呼吸道注意接触史与症状；口腔保持清洁并观察溃疡疼痛和摄食；皮肤会阴肛周温和清洁、观察红痛裂损，导管查敷料及局部异常。发热同时记录循环意识、采集合适标本并及时进入抗感染路径；缺乏局部红肿不能排除感染。","mechanism":"屏障破损与粒细胞减少可使微生物进入血流，炎症反应不足会掩盖局部体征。 ANC越低，抵御细菌真菌能力越弱；激素等可掩盖发热，因此休克、低体温或意识变化即使未达发热界值也要急评。","numbers":"抗癌治疗期间，NICE CG151：ANC≤0.5×10⁹/L，并有体温>38℃或其他临床显著脓毒症表现，应诊断评价中性粒细胞减少性脓毒症。ASCO/IDSA成人指南发热定义为单次口温≥38.3℃，或≥38.0℃持续1小时；严重中性粒细胞减少ANC<0.5×10⁹/L。CDC患者求助阈值为化疗期间体温≥38℃立即联系医疗团队，不必等待1小时。","avoid":"不把保护措施等同于一律层流或固定消毒坐浴；严重黏膜损伤时避免直肠测温及创伤性操作。 诊断定义与居家求助阈值用途不同；不可为凑持续时间而等待，不混用口温、腋温、耳温数值，不能只凭白细胞总数代替ANC。","source":"D13:P0172–P0195;NICECG151;ASCO-IDSA2018;CDC化疗发热"},{"id":"hematology-care-pe","name":"P—E、饮食与长期支持","cues":"贫血活动症状、疼痛进食受限、脱发或返院治疗","content":"活动无耐力可联系供氧不足，并用活动后气促心悸支持；营养摄入不足需有摄入或体重等证据，区分口腔痛、恶心和食欲差。缺铁补充铁源并查失血，骨髓瘤保护骨骼，化疗软洁食物兼顾耐受；评估形象与焦虑，明确复查和周期返院。","mechanism":"问题、相关因素和表现连成链，才能选择对因措施并验证成效。","numbers":"","avoid":"不把所有患者写成营养不足或一律高蛋白；心肾异常时液体和蛋白另作评估。","source":"D12:P0063–P0083,P0128,P0167–P0175;D13:P0196–P0205"},{"id":"hematology-care-platelet-context","name":"血小板数字：先分有没有出血和操作","cues":"化疗后血小板下降，准备侵入操作，或已经有出血","content":"先问当前是否出血、出血部位严重度及是否要做操作，再解释计数；黏膜、眼底/颅内和手术风险不能共用一个界值。治疗后复查临床止血和计数反应，同时记录发热、凝血异常及下降趋势。","mechanism":"血小板参与初级止血，但风险同时受血管损伤、凝血状态、感染和操作创伤影响，因此数字须与场景合用。","numbers":"NICE NG24：无出血且不做操作/手术的适用患者，预防性输注参考<10×10⁹/L；有临床显著出血参考<30×10⁹/L；侵入操作或手术一般考虑提高至>50×10⁹/L，关键部位手术如中枢神经考虑>100×10⁹/L。","avoid":"这些是不同情境的输注评估阈值，不是自发出血的绝对分界。无出血预防阈值不常规套用于慢性骨髓衰竭、ITP、HIT或TTP；低出血风险操作亦有例外。严重/关键部位出血按专科更高目标处理，不自行用数值开立输血。","source":"D13:P0068–P0076,P0137–P0171;NICE NG24血小板输注"}],"question":"这道题已有症状还是只有风险？哪一部位决定个性护理？"}],"drills":[{"id":"hematology-drill-iron","title":"补铁后好转，为什么仍需复评","stem":"患者长期月经过多，乏力，小细胞低色素、铁蛋白降低；服铁后胃部不适且便色变黑，想自行停药。","prompt":"列诊断依据、共性护理、用药差异和不能套用项。","answer":["共性：比较Hb趋势、心悸气促与活动耐受，核对持续失血和营养。","个性：检查支持缺铁，不能只给饮食建议而不处理月经过多原因；调整耐受策略需联系具体剂量制剂。","个性：解释铁相关便色变化，但黑便伴头晕低血压或其他出血证据仍要评估；疗效追踪Hb及贮存铁。","错用：不凭不适自行停药，不把所有贫血都补铁，也不把针剂试验套到口服。"],"source":"D13:P0015,P0088–P0101,P0207–P0213"},{"id":"hematology-drill-chemo","title":"化疗后发热加局部疼痛","stem":"化疗后患者发热寒战、牙龈渗血，输液处肿痛；另诉足尖麻木、排便变慢。","prompt":"先列当前优先级，再用药名补充个性观察。","answer":["共性：评估循环呼吸意识，查中性粒绝对值、血小板和感染入口，发热及时进入感染处理。","个性：牙龈渗血属于现存出血，记录并保护黏膜；另观察内脏出血信号。","个性：疑外渗停止输注、不冲管并保留通路待专业处置，核对药名决定处理；足麻便秘需追查长春新碱等神经毒性。","错用：不把发热只写成风险，不以一律冷敷或换个位置继续输注代替外渗处理。"],"source":"D13:P0107–P0133,P0137–P0195,P0214–P0215"},{"id":"hematology-drill-aplastic","title":"三系减少，为什么护理要三线展开","stem":"患者乏力、反复口腔感染和鼻出血，外周多系血细胞减少，骨髓低增生，未见支持白血病的克隆证据。","prompt":"提出诊断方向、补充评价与治疗护理，说明病因询问重点。","answer":["方向：再障需重点评价，同时排除其他骨髓疾病；多系减少不是自动等于白血病。","检查：复核中性粒、血小板及网织绝对值和骨髓资料，再判断严重性，不靠单个Hb。","共性：贫血看活动耐受，出血看部位与灌注，感染看入口及全身反应。","个性：询问药物、职业/化学及放射暴露等，治疗可涉及移植或免疫方案，按具体ATG/环孢素等记录不同反应。","错用：不把所有发热只写预防感染，不将所有方案统一层流或注射过敏试验。"],"source":"D13:P0018–P0039,P0102–P0104,P0207–P0211;M050图片病例目标"},{"id":"hematology-drill-leukemia","title":"化疗前的头晕与反应迟钝","stem":"患者新诊断急性白血病，乏力、头晕、反应变慢，白细胞显著增多且血小板减少，尚未开始化疗。","prompt":"列出需要立即排查的危险及之后化疗护理重点。","answer":["共性：先评估气道、血氧、循环、意识和血糖，核对Hb、血小板及计数趋势。","个性：同时警惕严重贫血、感染、出血或白细胞淤滞等原因，不能仅凭头晕锁定一种机制，及时专科处理。","现存出血或发热按实际问题记录；神经恶化立即升级，不等待化疗后再复评。","化疗后按药物增加外渗、骨髓抑制、黏膜与器官毒性观察，支持进食和形象适应。","错用：不把化疗前症状归于化疗不良反应，不用一律输血/补液或等待计数自然下降替代评估。"],"source":"D13:P0047–P0059,P0107–P0199,P0213–P0215;M051,M053图片病例目标"}],"references":[{"title":"NHLBI：贫血","url":"https://www.nhlbi.nih.gov/health/anemia"},{"title":"NHLBI：缺铁性贫血","url":"https://www.nhlbi.nih.gov/health/anemia/iron-deficiency-anemia"},{"title":"NHLBI：B12缺乏","url":"https://www.nhlbi.nih.gov/health/anemia/vitamin-b12-deficiency-anemia"},{"title":"NHLBI：溶血","url":"https://www.nhlbi.nih.gov/health/anemia/hemolytic-anemia"},{"title":"NHLBI：再障","url":"https://www.nhlbi.nih.gov/health/anemia/aplastic-anemia"},{"title":"NHLBI：ITP","url":"https://www.nhlbi.nih.gov/health/immune-thrombocytopenia"},{"title":"NHLBI：DIC","url":"https://www.nhlbi.nih.gov/health/disseminated-intravascular-coagulation"},{"title":"CDC：血友病","url":"https://www.cdc.gov/hemophilia/about/"},{"title":"NCI：AML","url":"https://www.cancer.gov/types/leukemia/hp/adult-aml-treatment-pdq"},{"title":"NCI：骨髓瘤","url":"https://www.cancer.gov/types/myeloma/patient/myeloma-treatment-pdq"},{"title":"NCI：分化综合征","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/differentiation-syndrome"},{"title":"eviQ：抗癌药外渗","url":"https://www.eviq.org.au/clinical-resources/extravasation"},{"title":"NHS：白血病支持治疗与高白细胞危险","url":"https://www.bsuh.nhs.uk/library/wp-content/uploads/sites/8/2021/01/Supporitve-Care-Protocol-4th-Edition-v3.1-Dec-2020-FINAL.pdf"},{"title":"WHO 2024：Hb判定、严重度与海拔调整表","url":"https://www.ncbi.nlm.nih.gov/books/NBK602183/?report=reader"},{"title":"BSH 2024：成人再障指南","url":"https://onlinelibrary.wiley.com/doi/10.1111/bjh.19236"},{"title":"Blood Advances 2024：SAA管理共识与定义","url":"https://ashpublications.org/bloodadvances/article/8/15/3946/515904/Modified-Delphi-panel-consensus-recommendations"},{"title":"NICE CG151：抗癌治疗中性粒细胞减少性脓毒症","url":"https://www.nice.org.uk/guidance/cg151/chapter/recommendations"},{"title":"ASCO/IDSA：成人癌症发热与中性粒细胞减少","url":"https://www.idsociety.org/globalassets/idsa/practice-guidelines/outpatient-management-of-fever-and-neutropenia.pdf"},{"title":"CDC：化疗期间发热求助","url":"https://www.cdc.gov/cancer-preventing-infections/patients/fever.html"},{"title":"NICE NG24：血小板输注场景与阈值","url":"https://www.nice.org.uk/guidance/ng24/chapter/Platelet-transfusion"}]},"rheumatology":{"title":"风湿系统：同一共性骨架，两种重点","intro":"SLE多系统受累，RA以关节炎与功能维护为重。先背评估、用药安全、活动营养和长期自护，再对照皮肤肾脑与关节差异。","framework":[{"id":"rheumatology-assessment","title":"共性一：症状、活动性与损害分开","cue":"关节痛、发热、皮疹、疲乏","answer":"记录症状起止、关节部位肿胀、晨僵和功能，观察皮肤口腔、呼吸循环及尿的变化。抗体辅助病种判断，炎症指标辅助活动趋势，尿及肾功能反映器官损害；发热同时寻找感染而不自动判疾病活动。","why":"疾病活动、感染与药物反应可相似，但处理方向不同。","source":"D14:P0097–P0100,P0127–P0133"},{"id":"rheumatology-medicines","title":"共性二：疗效与毒性双线监测","cue":"使用激素、免疫抑制或生物制剂","answer":"用症状、活动能力和相应指标评价疗效；按药物另记血象、肝肾、血压血糖、感染和眼部变化。核对剂量频次和复查，不因疼痛减轻擅停药，发热或新症状联系治疗团队。","why":"控制症状不等于阻止器官损害，免疫治疗又可增加感染等风险。","source":"D14:P0105–P0114"},{"id":"rheumatology-activity","title":"共性三：休息与功能维护同时安排","cue":"关节肿痛、晨僵、活动受限","answer":"急性炎症时减少诱发疼痛的负荷，提供关节支持、辅助器具和日常生活协助。缓解后循序进行活动范围与力量训练，比较疼痛、肿胀和功能；避免长期不动，也不强行活动炎症关节。","why":"疼痛抑制活动，长期不动又加重肌力下降和挛缩，需在保护和运动间平衡。","source":"D14:P0093–P0096,P0124–P0133"},{"id":"rheumatology-selfcare","title":"共性四：营养、感染与长期自护","cue":"慢性反复、长期用药或出院","answer":"均衡饮食并按肾功能、血压和营养状态调整盐、水与蛋白；口腔痛时选择柔软食物。落实皮肤口腔清洁、感染预警、复查与用药核对，讨论情绪、工作和生育计划，让患者能说出何时求助。","why":"慢性疾病、器官受累及药物共同影响营养、生活与依从性。","source":"D14:P0101–P0104,P0134–P0141"}],"contrasts":[{"id":"rheumatology-patterns","title":"诊断对照：SLE与RA","axis":"diagnosis","common":"不能用关节痛一个症状命名疾病，要看系统组合与损害类型。","rows":[{"id":"rheumatology-patterns-sle","name":"SLE","cues":"光照后皮疹、口腔溃疡、关节痛伴尿或血象异常","content":"重点寻找皮肤黏膜、血液、肾及神经等多系统受累；关节炎常非典型侵蚀性。结合病史、体征、抗体、补体和尿检综合评价，不能用ANA阳性替代诊断。","mechanism":"免疫异常可影响多种组织，症状组合比单器官表现更有意义。","numbers":"","avoid":"不是所有皮疹关节痛都是SLE；与RA或感染仍可重叠。","source":"D14:P0003–P0028,P0099"},{"id":"rheumatology-patterns-ra","name":"RA","cues":"持续对称小关节肿痛、晨僵和功能受限","content":"重点问受累关节分布、持续炎症和活动限制；滑膜炎可逐渐侵蚀骨与软骨，造成不可逆损害。RA也可有结节、肺等关节外表现，因此记录全身症状并综合检查。","mechanism":"滑膜慢性炎症解释肿痛，结构破坏解释后期畸形和功能损失。 滑膜炎使静止后的关节活动启动困难，持续僵硬需与肿胀、功能及炎症活动一起解释。","numbers":"RA的晨僵常持续>30分钟，也可超过1小时；记录实际持续时间、严重度及对握持穿衣的影响，用于炎症线索与随访比较。","avoid":"晨僵时长或RF单项都不能确诊；不能只看疼痛而忽略肿胀和结构损害。 晨僵时间不是单一诊断线；不能用≤30分钟排除，或用>1小时直接确诊RA。","source":"D14:P0003–P0028,P0100;NIH健康主题RA"},{"id":"rheumatology-patterns-pe","name":"P—E相关因素对照","cues":"皮肤破损、口腔溃疡、疼痛或生活困难","content":"SLE皮肤/口腔完整性问题要以实际破损支持，再联系炎症、药物或感染等因素；有感染危险联系免疫治疗和屏障破损。RA疼痛联系炎症，活动障碍联系疼痛僵硬及结构变化，自理缺陷需举穿衣、进食等实际困难。","mechanism":"问题名称、原因与表现连接后，才可选择针对措施和复评目标。","numbers":"","avoid":"没有破损不写已受损；焦虑悲伤需有主观或行为证据，不能人人套用。","source":"D14:P0091–P0141;M054护理诊断图"}],"question":"哪些线索让你从关节转向皮肤、肾脏或系统受累？"},{"id":"rheumatology-tests","title":"检查对照：诊断、活动性与损害","axis":"labs","common":"一项检查先标明用途：支持病种、观察活动还是评价器官。","rows":[{"id":"rheumatology-tests-sle","name":"SLE抗体与器官检查","cues":"疑SLE或已诊断后出现尿异常","content":"ANA用于敏感筛查，dsDNA和Sm等提供进一步支持；dsDNA及补体变化需与临床和尿检合看，Sm不作为单独活动指标。RNP、SSA/SSB、抗磷脂等提示特定重叠或妊娠/血栓风险背景；肾活检用于需要明确肾炎分型等情况。","mechanism":"抗体谱、补体消耗和器官检查处于不同证据层，不能用一个结果回答全部问题。","numbers":"","avoid":"不以阴阳性替代完整诊断，不把单次抗体升高当作加药指令，也不将SSA阳性等同已发生并发症。","source":"D14:P0029–P0047,P0065–P0090"},{"id":"rheumatology-tests-ra","name":"RA血液、影像与滑液","cues":"对称关节炎，RF异常或血检阴性仍可疑","content":"RF与抗CCP结合关节表现和影像解释；ESR/CRP反映炎症趋势但不能单独区分感染。X线比较软组织/骨质改变、间隙变窄、侵蚀与强直，MRI/超声帮助看早期滑膜；滑液评估可帮助排除感染或晶体，结节活检仅在有适应证时补充。","mechanism":"抗体支持免疫背景，影像展示结构，滑液回答局部炎症鉴别问题。","numbers":"","avoid":"不把正常血检排除RA，不将X线、CCP、RF简单排成通用诊断名次，也不人人做活检。","source":"D14:P0048–P0064"}],"question":"同为阳性抗体，哪些不能用来追踪活动？"},{"id":"rheumatology-therapy","title":"药物对照：控制炎症与保护器官","axis":"treatment","common":"先背大类风险，再加具体药物的特殊观察。","rows":[{"id":"rheumatology-therapy-anti-inflammatory","name":"NSAIDs与糖皮质激素","cues":"关节疼痛或系统炎症，正在使用抗炎药","content":"NSAIDs缓解症状，关注上腹痛、黑便、血压和肾功能；用药前核查肾损伤、消化道出血及合并药物。激素可控制活动，但长期用药需观察感染、血糖血压、骨与精神状态，停减药按计划逐步评价。","mechanism":"两者风险与作用不同，止痛改善不等于疾病过程被控制。","numbers":"","avoid":"不将NSAIDs当作阻止关节破坏的替代品，也不突然停长期激素。","source":"D14:P0105–P0110"},{"id":"rheumatology-therapy-specific","name":"DMARDs、CTX/MMF与羟氯喹","cues":"长期控制治疗、肾受累或关节持续炎症","content":"DMARDs重在控制病程，按具体药物监测血象和肝肾；CTX另看血尿、感染与生殖风险，MMF另看腹泻、血象、感染及妊娠风险。羟氯喹需核对眼科筛查及新视力问题；生育计划须在调药前讨论，而非自行停换。 若药单有甲氨蝶呤，逐字核对每周频次与叶酸安排；新口腔溃疡、发热或血象下降需排查药物毒性。","mechanism":"免疫调节获益伴骨髓、泌尿、生殖或眼等不同靶器官风险。","numbers":"RA低剂量甲氨蝶呤常规按每周给药计划（固定同一星期几）使用，不能误作每日；分次、叶酸与监测安排以具体处方核对。此频次不用于肿瘤大剂量/鞘内方案。","avoid":"不把全部免疫药当作相同毒性，也不统一鼓励大量饮水；肾心功能限制者另评估。 绝不把风湿病每周方案直接用于肿瘤化疗，也不让学生据此自行调整剂量或漏服补服。","source":"D14:P0109–P0113;AustralianRheumatologyAssociation甲氨蝶呤"},{"id":"rheumatology-therapy-biologic","name":"生物制剂","cues":"准备使用或已接受靶向免疫治疗","content":"治疗前核查结核、肝炎等感染评价以及免疫接种计划，治疗中观察发热、咳嗽、皮肤或导管感染和过敏反应。新的严重感染需要联系团队重新评价治疗时机，并保留药名与最近给药日期。","mechanism":"特定免疫通路被抑制后可增加潜伏感染再激活等风险。","numbers":"","avoid":"筛查阴性不能保证以后无感染，不凭一次发热自行永久停药或继续输注。","source":"D14:P0114"}],"question":"药名变了，观察重点哪些仍相同，哪些需要替换？"},{"id":"rheumatology-care","title":"护理对照：皮肤肾脑与关节功能","axis":"nursing","common":"共性是舒适、感染预防与自护；个性由器官受累和功能问题决定。","rows":[{"id":"rheumatology-care-skin","name":"SLE皮肤与口腔","cues":"光敏皮疹、抓痕或口腔溃疡","content":"温和清洁、减少摩擦，记录皮损范围、渗液和感染；采取遮阳、防晒及减少紫外线暴露。口腔观察破损疼痛和进食，选温和清洁、柔软适温食物，按是否感染决定局部处理。","mechanism":"光照可诱发或加重病变，屏障破损叠加免疫治疗又提高感染风险。","numbers":"","avoid":"不把所有护肤品一概禁止，也不在所有溃疡统一用抗真菌或刺激性漱口液。","source":"D14:P0115–P0123,P0140"},{"id":"rheumatology-care-joint","name":"RA晨僵、关节保护与锻炼","cues":"晨起僵硬、握持和穿衣困难","content":"晨起适度温热舒适护理后轻柔活动，注意感觉、皮肤及耐热；急性肿痛时减少负荷。摆放舒适功能位并使用适合夹板/辅助器具，定期查看皮肤；恢复时由被动到主动、由轻到重，比较疼痛肿胀和实际功能。","mechanism":"支持减轻机械应力，适度活动维持关节活动和肌力。","numbers":"","avoid":"不长期固定不动，不强行扳动红肿关节，也不套固定俯卧次数或统一夹板方案。","source":"D14:P0096,P0124–P0126,P0132–P0133"},{"id":"rheumatology-care-organ","name":"SLE器官风险与生育/长期管理","cues":"蛋白尿水肿、精神改变或计划妊娠","content":"肾受累追踪尿量尿色、体重水肿、血压、尿蛋白和肾功能，按容量与营养调整饮食；精神意识改变须同时排查感染、代谢、药物与神经受累。疾病相对稳定时仍需复查、防晒与感染预警，妊娠前评估疾病活动、肾脏、抗体及药物。","mechanism":"系统病变与治疗均可损伤器官，妊娠又改变母体和胎儿风险。","numbers":"","avoid":"不把所有精神异常都叫狼疮脑病，不给全部SLE统一低蛋白限水，也不一律禁止生育。","source":"D14:P0099,P0103,P0127–P0141"}],"question":"用题干证据为每条护理措施找到理由。"}],"drills":[{"id":"rheumatology-drill-sle","title":"皮疹与尿异常要连在一起","stem":"年轻患者光照后面部皮疹加重，反复口腔溃疡，近期发热；尿蛋白增多、补体降低。","prompt":"提出诊断方向与需要补充的依据；说明治疗评估及皮肤护理重点。","answer":["共性：评估生命体征、感染线索、血象和器官功能，不只背皮疹特点。","个性：SLE为重要方向，抗体、补体与尿检联合解释；进一步量化肾受累并由专科决定是否活检。","个性：系统活动和器官受累决定激素及免疫治疗强度，不能只凭ANA或皮疹选择固定药物；关注感染和药物安全。","皮肤：温和清洁、防晒遮阳、减少摩擦，观察范围、破损渗液及感染；口腔痛时维护清洁与进食。","错用：不把发热全部当狼疮活动，不一律低蛋白限水，不自行突然停激素。"],"source":"D14:P0003–P0047,P0105–P0123;M055图片原题目标"},{"id":"rheumatology-drill-ra","title":"从关节痛走向功能目标","stem":"患者双腕与手指对称肿痛数月，晨起握杯困难，RF阳性；影像尚无明显侵蚀，刷牙穿衣需要帮助。","prompt":"列补充检查、主要护理问题与对应措施，区分共性和个性。","answer":["检查：结合抗CCP、ESR/CRP、血常规及适当影像评价；血检或X线暂正常不排除早期RA。","问题：疼痛与局部炎症相关；活动障碍与疼痛僵硬相关；自理缺陷由刷牙穿衣困难支持，失用风险另列。","共性：用药毒性、感染观察及情绪支持，记录实际功能与疗效。","个性：关节保护与辅助器具，晨起温和舒适后轻活动；缓解后逐步训练，比较握持穿衣能力。","错用：不长期固定全部关节，不强行活动红肿关节，不以止痛药替代病程控制。"],"source":"D14:P0048–P0064,P0093–P0141;M054,M056图片原题目标"}],"references":[{"title":"NIAMS：SLE诊断治疗与自护","url":"https://www.niams.nih.gov/health-topics/lupus/diagnosis-treatment-and-steps-to-take"},{"title":"NIAMS：RA诊断治疗与自护","url":"https://www.niams.nih.gov/health-topics/rheumatoid-arthritis/diagnosis-treatment-and-steps-to-take"},{"title":"ACR：甲氨蝶呤","url":"https://rheumatology.org/patients/methotrexate-rheumatrex-trexall-otrexup-rasuvo"},{"title":"Australian Rheumatology Association：羟氯喹","url":"https://rheumatology.org.au/For-Patients/Adult-Medication-Information/H-M/Hydroxychloroquine"},{"title":"BSR：生物制剂安全指南","url":"https://academic.oup.com/rheumatology/article/58/2/220/5076445"},{"title":"ACR：环磷酰胺","url":"https://rheumatology.org/I-Am-A/Patient-Caregiver/Treatments/Cyclophosphamide-Cytoxan"},{"title":"FDA药品标签：霉酚酸酯妊娠及感染风险","url":"https://www.dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=a15c26d8-5a27-48ba-a669-8546803d901f&type=display"},{"title":"NIH：RA症状与晨僵","url":"https://health.nih.gov/health-topics-a-z/rheumatoid-arthritis"},{"title":"Australian Rheumatology Association：甲氨蝶呤每周用药","url":"https://rheumatology.org.au/For-Patients/Adult-Medication-Information/H-M/Methotrexate"}]},"shock-burn":{"title":"水电解质、休克与烧伤","intro":"先把气道和灌注危险找出来，再沿丢失什么、转移到哪里、化验怎样变、处理怎样复评四条线回忆。","framework":[{"id":"shock-burn-f-loss","title":"液体问题先分四笔账","cue":"呕吐、腹泻、减压、烧伤或禁食","answer":"分别列摄入不足、既往丢失、继续丢失和体内异常分布。记录损失的量与成分，结合血钠、血钾、肾功能及心肺耐受解释补什么、补多少、怎样复评。","why":"烧伤及第三间隙可把水留在组织而使有效循环量下降，水肿不等于血管内充足。","source":"D17:P0008–P0038"},{"id":"shock-burn-f-perfusion","title":"休克答案按病因—灌注—反应","cue":"脉快、肢凉、尿少、意识改变或低血压","answer":"先找失血、感染、创伤等病因，再串意识、皮温、脉搏血压、尿量和乳酸/血气。写清循环支持与止血或感染源控制同时进行，并用连续变化评价效果。","why":"代偿期血压可维持，单次正常血压不能证明组织灌注正常。","source":"D17:P0117–P0174"},{"id":"shock-burn-f-electric","title":"钾紊乱先连肌力与心电","cue":"肌无力、腹胀或心律变化","answer":"把摄入、消化道/肾丢失、细胞内外转移和排泄能力分开。比较血钾与心电后，再说明补钾或降钾措施的目的及复查血钾、心律、血糖的需要。","why":"血清钾只反映细胞外小部分钾，移入细胞不等于从身体清除。","source":"D17:P0039–P0080"},{"id":"shock-burn-f-burn","title":"烧伤固定背五项，护理加三层","cue":"热烧伤伴创面或烟雾吸入","answer":"先补年龄、体重、受伤时刻、部位面积和深度。护理按气道/循环救命、创面与感染防护、营养功能及身体意象三层写，并在每层加病例证据。","why":"深度、面积及关键部位共同决定风险；疼痛较轻也可能是更深的损伤。","source":"D17:P0175–P0242；PDF22:PDF页1"},{"id":"shock-burn-f-pe","title":"问题—相关因素—并发症分开","cue":"需要列护理诊断","answer":"有丢失和脱水证据时写体液不足并写明来源；有深快呼吸证据时分析低效性呼吸型态与酸负荷。烧伤另列皮肤完整性、疼痛和身体意象问题；休克、心搏骤停、感染或器官功能障碍作为协同监测分支。","why":"问题名称相同，水钠失衡、休克与烧伤的相关因素及优先级不同。","source":"PDF22:PDF页1；D17:P0237–P0242"}],"contrasts":[{"id":"shock-burn-water","title":"水钠失衡：先比较水与钠的相对损失","axis":"diagnosis","common":"都可有体液不足；按血钠、损失史与循环状态共同判别。","rows":[{"id":"shock-burn-water-iso","name":"等渗性失水","cues":"急性消化液丢失、第三间隙或创面丢失","content":"水与钠大致成比例丢失，血钠可正常。主要警惕血容量不足，不能因不口渴就排除。","mechanism":"细胞外液减少为主，血钠浓度不代表总钠或循环量。","numbers":"","avoid":"","source":"D17:P0008–P0014"},{"id":"shock-burn-water-low","name":"低渗性失水","cues":"持续丢盐、只补水、排钠利尿剂后","content":"失钠相对多于失水，乏力、头晕、低灌注可突出。需区分低钠是否伴容量不足，并观察意识改变。","mechanism":"渗透压下降使水进入细胞，同时细胞外液量减少。","numbers":"","avoid":"不能把所有低钠都称为脱水，心衰等可为另一容量状态。","source":"D17:P0015–P0018"},{"id":"shock-burn-water-high","name":"高渗性失水","cues":"饮水不足、发热出汗、尿崩或渗透性利尿","content":"水丢失相对更多，口渴与黏膜干燥常明显。重者可躁动、嗜睡或昏迷，需追踪神经和循环两方面。","mechanism":"高渗使细胞失水，脑细胞容积变化产生神经症状。","numbers":"","avoid":"不能只快速灌入大量低渗液体，纠正速度须结合病程。","source":"D17:P0019–P0038"}],"question":"为什么血钠正常的患者仍可出现休克？"},{"id":"shock-burn-potassium","title":"钾紊乱：同有无力，心电和原因不同","axis":"labs","common":"把原因、血钾、心电、胃肠肌力和酸碱变化排成同一行。","rows":[{"id":"shock-burn-k-low","name":"低钾方向","cues":"长期呕吐、减压、排钾利尿剂或大量胰岛素后","content":"回忆肌无力、肠蠕动下降和心律失常，心电可有T波低平及U波。把摄入少、丢失多和转入细胞三类原因分开。","mechanism":"细胞内外梯度改变影响神经肌肉及心肌兴奋性。","numbers":"","avoid":"心电不典型仍不能排除；补钾前需看肾排泄。","source":"D17:P0042–P0059"},{"id":"shock-burn-k-high","name":"高钾方向","cues":"肾排泄下降、组织损伤或保钾药物后","content":"高尖T波、QRS变宽及缓慢/异常心律提示危险，严重者可心搏骤停。核对溶血假性升高并结合临床处理，不能等典型心电齐全。","mechanism":"组织释放和排出减少增加细胞外钾，影响心肌传导。","numbers":"","avoid":"正常心电不保证安全；不能把肌无力自动当低钾。","source":"D17:P0043–P0059；RCUK2025:高钾"}],"question":"同是肌无力，哪些证据会改变处理方向？"},{"id":"shock-burn-acid","title":"酸碱四步：性质、原发、代偿、混合","axis":"labs","common":"先看pH，再比较PaCO₂和HCO₃⁻，最后检查代偿是否合理并联系病因。","rows":[{"id":"shock-burn-acid-met","name":"代谢性改变","cues":"大量腹泻、低灌注或反复胃液丢失","content":"pH降低且HCO₃⁻降低支持代谢性酸负荷方向，低灌注时联系乳酸。pH升高且HCO₃⁻升高时，联系胃酸丢失或其他碱负荷。","mechanism":"前者酸增加或碱丢失，后者酸丢失或碱增加；呼吸会参与代偿。","numbers":"成人动脉血气常用参考：pH 7.35–7.45，PaCO₂ 35–45mmHg，HCO₃⁻22–26mmol/L；与本次实验室区间和样本类型核对。","avoid":"不能用同向变化一句话取代代偿核算；正常pH也可能是混合失衡。","source":"D17:P0081–P0116；MedlinePlus:动脉血气"},{"id":"shock-burn-acid-resp","name":"呼吸性改变","cues":"通气不足、过度通气或呼吸支持改变","content":"PaCO₂升高且pH偏酸时先想通气不足，下降且pH偏碱时先想过度通气。再看HCO₃⁻及急慢性病程，区分代偿和合并代谢问题。","mechanism":"肺排出CO₂，肾对碳酸氢根的调节较慢。","numbers":"","avoid":"不要只凭呼吸快慢命名酸碱类型。","source":"D17:P0081–P0116"}],"question":"pH接近正常时，为什么仍要同时看另两项？"},{"id":"shock-burn-resuscitate","title":"复苏与用药：同是支持，目的各异","axis":"treatment","common":"每项写目的、给药/液体途径、监测反应和停止或升级依据。","rows":[{"id":"shock-burn-fluid","name":"补液五要素","cues":"液体不足、持续丢失或休克","content":"分清复苏、日常维持、补丢失及异常分布，液体种类和速度依病情开立。记录所有输入及异常丢失，并反复看呼吸、灌注、肾功能和电解质。","mechanism":"补进血管内的液体可能重新分布，也可能增加心肺负荷。","numbers":"","avoid":"所有休克先大量快速补液不适用于心源性或明显过负荷。","source":"D17:P0024–P0034,P0121–P0135；NICE CG174"},{"id":"shock-burn-k-replace","name":"补钾","cues":"确认低钾并评估排泄能力","content":"可经口者优先评估口服途径；静脉制剂按规定浓度和泵速执行并观察静脉。复查血钾、肾功能和心律，不能只凭一次尿量决定安全。","mechanism":"纠正体内缺钾需要时间，输入过快会迅速升高细胞外钾。","numbers":"","avoid":"氯化钾不得静脉推注；不能按滴数而忽略输液器与实际单位。","source":"D17:P0060–P0070；NICE CG174"},{"id":"shock-burn-k-remove","name":"降钾","cues":"确认高钾并出现相关风险","content":"把保护心肌、使钾进入细胞、把钾排出体外及停止来源四个目的分开。胰岛素相关治疗后监测血糖，排钾效果不足时配合肾脏专科评估。","mechanism":"钙剂保护心肌而不降低钾，细胞转移措施也不能替代清除钾。","numbers":"","avoid":"不把碳酸氢钠、利尿剂或固定一套剂量用于全部高钾。","source":"D17:P0071–P0080；RCUK2025:高钾"},{"id":"shock-burn-shock-source","name":"休克病因治疗","cues":"外伤失血与感染表现不同","content":"失血分支重点为控制出血并配合复苏，感染分支重点为抗感染与感染源控制。血管活性药使用时核对浓度、泵速、通路和外渗，并持续比较灌注。","mechanism":"升高血压不一定已经控制病因或恢复微循环。","numbers":"","avoid":"不能以血压数字改善代替止血或感染引流。","source":"D17:P0117–P0149"}],"question":"钙剂、胰岛素葡萄糖和透析分别解决什么问题？"},{"id":"shock-burn-burn","title":"烧伤：面积、深度和气道分别回答","axis":"diagnosis","common":"面积估计与深度判断分开，关键部位和吸入风险另列。","rows":[{"id":"shock-burn-burn-area","name":"中国九分法：成人分区","cues":"成人大块连续热烧伤","content":"先按中国九分法确定解剖边界，再把Ⅱ度和Ⅲ度创面面积相加。躯干含前13%、后13%与会阴1%，臀部计入双下肢；仅Ⅰ度红斑不计入复苏面积。","mechanism":"体表比例是估计工具，成人与儿童头腿比例不同。","numbers":"头面颈9%（3+3+3）；双上肢18%（双手5、双前臂6、双上臂7）；躯干27%（13+13+1）；双下肢含臀46%（双臀5、双足7、双小腿13、双大腿21）。","avoid":"儿童需按年龄调整；不能把Wallace九分法的前躯干18%与中国九分法其他分区混算。","source":"D17:P0175–P0201；国家卫生健康委《突发事件烧伤伤员医疗救治规范（2025年版）》表1；ABA:Rule of Nines"},{"id":"shock-burn-burn-depth","name":"深度辨认","cues":"起疱、湿润潮红、苍白干燥或皮革样创面","content":"Ⅰ度为干燥红斑且无疱；浅Ⅱ度常水疱大、创底潮红湿润、痛觉明显。深Ⅱ度较苍白或红白相间、感觉迟钝，Ⅲ度可干燥皮革样和痛觉消失；需随创面演变复评。","mechanism":"深层神经末梢受损使疼痛反而减弱。","numbers":"","avoid":"不靠是否疼痛单项定深度，也不靠照片一次定全部损伤。","source":"D17:P0177–P0201；ABA:烧伤深度"},{"id":"shock-burn-burn-severe","name":"严重度与吸入损伤","cues":"面颈/关节等关键部位、声嘶、烟雾暴露或循环异常","content":"严重度同时看深度、面积、部位、合并伤和器官状态。面颈烧伤、声嘶及烟灰需立即升级气道评估，不等创面分级完成。","mechanism":"气道水肿可进展，深环形焦痂也可能限制胸廓或末梢循环。","numbers":"","avoid":"小面积关键部位烧伤也可高风险；普通脉氧正常不能排除CO问题。","source":"D17:P0191–P0208,P0238；ABA:转诊"}],"question":"最痛的一块是否一定最深？小面积是否一定轻？"},{"id":"shock-burn-burn-care","title":"烧伤护理：覆盖、暴露与全身支持","axis":"nursing","common":"共性是防污染、防失温、保功能和观察灌注；按部位与治疗方式增加差异。","rows":[{"id":"shock-burn-burn-resus","name":"液量估算与复评","cues":"已知年龄体重、TBSA、伤后时间并有复苏处方","content":"成人晶胶混合方案先估算渗出补充部分，再另计基础水分，并扣已输入量、关注受伤时刻。次日晶体和胶体部分可按前日实际量与病情调整，基础水分不随两者机械减半；随尿量、灌注、呼吸和化验复评。","mechanism":"毛细血管渗漏随阶段变化，公式是初始估计而不是固定终点。","numbers":"成人晶胶混合估算：伤后首24h，1.5–2mL×Ⅱ/Ⅲ度面积百分数×体重kg，另加基础水分2000mL；估计总量约半数在伤后首8h，其余分后续16h。系数及实际速率由复苏方案确定。","avoid":"题目未指定系数时不能自选一种公式当唯一答案。","source":"D17:P0209–P0214,P0220–P0221；国家卫生健康委2025烧伤规范:抗休克治疗"},{"id":"shock-burn-burn-cover","name":"包扎与暴露","cues":"已确定创面治疗方式","content":"包扎时保护敷料、末梢循环和功能体位；暴露时重点为环境、接触隔离及避免创面受压。两者都要记录感染征象并在清洁处理时镇痛。","mechanism":"覆盖减少污染和水热丢失，暴露处理则更依赖环境与体位管理。","numbers":"","avoid":"不自行涂有色偏方；大面积长时间冷却会增加失温。","source":"D17:P0203–P0208,P0222–P0227"},{"id":"shock-burn-burn-special","name":"特殊部位与恢复","cues":"眼耳、面颈、会阴、手足关节或大面积烧伤","content":"按部位增加视力/气道/循环、排泄污染及关节功能评估，任何管路需有明确适应证。营养、心理和身体意象贯穿恢复，逐步练习生活活动并监测肺、肾和应激性消化道出血风险。","mechanism":"深创面与高分解代谢使修复耗能增多，瘢痕与制动影响功能和外观。","numbers":"","avoid":"会阴烧伤不等于所有人必须留尿管或常规膀胱冲洗。","source":"D17:P0225–P0236；PDF22:PDF页1"}],"question":"包扎疗法与暴露疗法的护理能否用同一张清单？"},{"id":"shock-burn-perfusion-tests","title":"灌注检查：血压与CVP要连患者反应","axis":"labs","common":"CVP是压力信息，不等同容量；与灌注、心肺及趋势共同解释。","rows":[{"id":"shock-burn-low-pressure","name":"低CVP伴低血压","cues":"低灌注并有失血或失液背景","content":"可支持血管内容量不足方向，但还要比较失血来源、心率尿量及治疗反应。根据病因和复评安排循环支持，不能仅依据一对数字完成诊断。","mechanism":"压力低可与回心血量不足相连，但血管张力和胸内压也影响读数。","numbers":"","avoid":"不能把CVP低自动变成所有患者快速大量输液。","source":"D17:P0123–P0149；M065:CVP/血压表；NICE CG174"},{"id":"shock-burn-high-pressure","name":"CVP较高但血压低","cues":"灌注仍差，可能伴呼吸或心脏异常","content":"要评估心功能、回流阻碍、胸内压和容量负荷，结合氧合及必要床旁心脏检查。不能因低血压继续不加区分补液，也不凭高CVP自行使用强心药。","mechanism":"泵功能、阻塞和压力传递可能使静脉压升高而有效前向血流不足。","numbers":"","avoid":"高CVP不一定单纯心衰，也不单独决定药物。","source":"D17:P0123–P0149；M065:CVP/血压表；NICE CG174"},{"id":"shock-burn-normal-pressure","name":"CVP或血压正常而灌注异常","cues":"意识、末梢、尿量或乳酸趋势恶化","content":"正常读数不代表有效血流正常，需继续联系病因和器官反应。把输液前后呼吸、血压、尿量等变化记录完整，避免以一次测量宣布复苏结束。","mechanism":"循环代偿和测量条件可掩盖容量或微循环问题。","numbers":"","avoid":"尿少也不一定全部由缺液造成。","source":"D17:P0123–P0149；M065:CVP/血压表；NICE CG174"}],"question":"哪些证据会让低血压患者暂停机械补液，转向心肺或阻塞评估？"},{"id":"shock-burn-severity","title":"成人热烧伤严重程度：面积、深度与合并情况","axis":"diagnosis","common":"按2025烧伤救治规范分级；分别统计Ⅱ/Ⅲ度总面积和Ⅲ度面积，再检查特殊部位、休克、吸入损伤及复合伤，符合更高等级条件时不能停在低级。","rows":[{"id":"shock-burn-severity-mild","name":"轻度","cues":"成人热烧伤，面积小且无更高级别特征","content":"总面积较小且无Ⅲ度时可归轻度。仍需核对是否涉及特殊部位或合并危险，疼痛小与面积小都不是唯一依据。","mechanism":"总体组织损伤较少，但关键部位功能风险可能不由总面积反映。","numbers":"总面积＜10%，无Ⅲ度烧伤。","avoid":"儿童、电或化学损伤不直接套成同一种普通热烧伤评价；面颈手会阴等需看特殊部位条件。","source":"D17:P0175–P0201及烧伤严重程度表；国家卫生健康委《突发事件烧伤伤员医疗救治规范（2025年版）》2.3"},{"id":"shock-burn-severity-moderate","name":"中度","cues":"无更高级别合并条件，需要按面积/Ⅲ度面积分类","content":"比较Ⅱ/Ⅲ度合计面积与Ⅲ度部分，两者满足相应条件即可进入中度评估。即使总面积不足10%，若已有Ⅲ度也不能按无Ⅲ度的轻度条目。","mechanism":"少量全层损伤也增加修复与功能负担。","numbers":"总面积10%–29%，或Ⅲ度面积＜10%。","avoid":"Ⅲ度面积为0不能单独用小于10%一项把所有人归中度；同时满足高级别条件时从高判断。","source":"D17:P0175–P0201及烧伤严重程度表；国家卫生健康委《突发事件烧伤伤员医疗救治规范（2025年版）》2.3"},{"id":"shock-burn-severity-severe","name":"重度","cues":"面积增加、全层损伤增加或特殊部位受累","content":"除总面积和Ⅲ度面积，还要看面、颈、手、会阴等特殊部位。面积不足相应阈值而存在这些部位烧伤时，也需按重度条件评价。","mechanism":"重要部位气道、精细活动与排泄等功能易受影响。","numbers":"总面积30%–49%，或Ⅲ度10%–19%；总面积不足30%但有特殊部位烧伤也可归此级。","avoid":"不能只按面积小就降级；合并休克等特重条件时仍需上调。","source":"D17:P0175–P0201及烧伤严重程度表；国家卫生健康委《突发事件烧伤伤员医疗救治规范（2025年版）》2.3"},{"id":"shock-burn-severity-critical","name":"特重度","cues":"大面积/全层面积较大，或伴休克、中重度吸入损伤、严重复合伤","content":"面积达到阈值可列特重；面积不足时，严重复合伤、休克或中重度吸入损伤等仍使其进入特重评估。救命处置先于完成分级，气道、灌注和合并伤持续复评。","mechanism":"广泛组织损伤和全身器官风险叠加，不由皮肤面积单独决定。","numbers":"总面积≥50%，或Ⅲ度≥20%；总面积不足50%但伴严重复合伤、休克、中重度吸入损伤等。","avoid":"不能沿用把50%或Ⅲ度20%排除在特重之外的严格大于号。","source":"D17:P0175–P0201及烧伤严重程度表；国家卫生健康委《突发事件烧伤伤员医疗救治规范（2025年版）》2.3"}],"question":"成人总面积50%、Ⅲ度20%，以及面积较小却已休克，按此分级各落在哪一级？"}],"drills":[{"id":"shock-burn-drill-burn","title":"先判断，再计算","stem":"成人在密闭厨房火灾中受伤，整条右上肢和前躯干为起疱湿润创面，额头仅红斑。现声嘶、肢凉、尿量减少。","prompt":"按中国九分法估算计入复苏的面积，分别写气道、灌注及皮肤问题；列出液量估算还缺什么。","answer":["按中国九分法：整条右上肢9%加前躯干13%，计入22%；额头仅Ⅰ度红斑不加。","共性：先把气道、呼吸、循环危险和创面分开评估，立即报告恶化。个性：密闭烟雾与声嘶提示吸入风险，不能先等面积计算完。","液量计算还需体重、受伤时刻、已输入量和指定复苏方案；实际补液随灌注、尿量和呼吸变化复评。","皮肤完整性受损有创面证据；体液不足需联系渗漏及低灌注。错用项：不能把额头红斑计入，也不能把Wallace法前躯干18%与中国分区混算。"],"source":"D17:P0175–P0242；国家卫生健康委2025烧伤规范表1"},{"id":"shock-burn-drill-electrolyte","title":"同样无力，怎样分支","stem":"甲因长期胃肠减压出现腹胀和肌无力，心电见U波；乙肾功能明显下降后也无力，心电QRS较前增宽。","prompt":"比较最先核对的检查与用药目的，再说明为何不能互换护理。","answer":["共性：立即核对血钾、心电、肾功能、药物和出入量，持续观察心律。","甲联系消化道丢失与低钾方向，评估补钾途径及排泄；乙联系排出减少与高钾风险，及时配合保护心肌、转移/清除钾等治疗。","个性：乙如接受胰岛素相关降钾还需血糖监测，甲静脉补钾重点为核对浓度泵速与静脉。","错用项：不得看到无力就补钾；钙剂也不是把钾排出体外的药。"],"source":"D17:P0039–P0080；RCUK2025:高钾"},{"id":"shock-burn-drill-acid","title":"血气有数字，答案要有过程","stem":"腹部感染患者低灌注、呼吸深快。成人动脉血气为pH7.29、PaCO₂29mmHg、HCO₃⁻14mmol/L。","prompt":"按顺序解释酸碱方向，写共性护理与尚不能确定的部分。","answer":["pH低于常用参考，属于酸血症；HCO₃⁻下降指向代谢性酸中毒，PaCO₂下降可能为呼吸代偿。","下一步需评估代偿是否适当、乳酸/AG、肾功能及病因；不能仅凭三项方向宣布只有一种失衡。","共性：维护呼吸循环、记录灌注尿量及出入量；个性：联系感染及低灌注，配合病因和感染源处理。","错用项：呼吸深快不自动等于呼吸性碱中毒，也不自动静推碱性药。"],"source":"D17:P0081–P0145；M061:目标；MedlinePlus:动脉血气"},{"id":"shock-burn-drill-crush","title":"挤压伤后少尿与心律变化","stem":"肢体严重挤压后患者持续少尿、肌无力，心电出现进行性传导异常；化验报告血钾明显升高。","prompt":"解释机制，比较补液与降钾目的，列监测和错用项。","answer":["个性：组织损伤释放钾且肾排出减少可叠加，少尿不能只理解为喝水不够。","共性：优先气道循环与心律评估，核对采样及血钾，配合高钾紧急治疗并查肾功能酸碱。","保护心肌、转移钾与清除钾目的不同；胰岛素相关治疗后需监测血糖，持续高钾需专科排钾评估。","错用项：不能因肌无力或少尿盲目补钾，也不能大量补液而忽略过负荷。"],"source":"D17:P0039–P0080；M062:目标；RCUK2025"},{"id":"shock-burn-drill-calculation","title":"先写方案，再算时段","stem":"成人60kg，Ⅱ/Ⅲ度创面20%。题设采用1.5mL/(kg·百分数)估算首日晶胶部分，并另计基础水分2000mL。","prompt":"计算首24h估计总量，并说明时间和动态调整原则。","answer":["晶胶估算为60×20×1.5＝1800mL，加基础水分2000mL，总估计3800mL；20%在该式写20。","题设若按半数于伤后首8h，则该时段估计1900mL；起点是受伤时刻，已输入量需纳入，不能从入院重新算8h。","共性：持续评估灌注、尿量、呼吸、电解质和心肾耐受；个性：烧伤面积深度及指定方案决定估算。","错用项：该题系数并非所有年龄/伤情的统一处方；次日不能把3800全量机械减半。"],"source":"D17:P0209–P0214；M067/M068:面积深度液量目标；国家卫生健康委2025烧伤规范"},{"id":"shock-burn-drill-integrated","title":"烧伤综合：面积、深度、血气与优先级","stem":"成人在烟雾环境火灾中受伤，前躯干及整条左上肢起疱，右手局部皮革样、感觉减弱；现声音嘶哑、肢凉、尿量下降。动脉血气pH7.29、PaCO₂29mmHg、HCO₃⁻14mmol/L，电解质报告提示高钠、高钾。","prompt":"分四栏作答：面积深度需补什么、血气方向、最优先问题、休克期护理；不要把问题互相替代。","answer":["面积深度：按中国九分法已明确前躯干13%加左上肢9%；右手需补创面范围，不能整只手或深度单征直接代入。皮革样感觉减弱提示深部损伤方向，需要专业复评。","血气为酸血症、HCO₃⁻低，联系代谢性酸中毒及可能呼吸代偿；还需代偿核算、乳酸/AG及肾功能。高钠和高钾分别追损失、组织释放与排泄因素，不能只答休克。","优先：声嘶烟雾背景需立即升级气道评估；肢凉少尿需联系灌注，护理问题用各自证据，而非先完成算液量再处理。","休克期共性为通路、出入量、灌注氧合及化验复评，个性为烧伤面积深度/体重/受伤时刻和指定复苏方案。错用项：浅表红斑不计复苏面积，混合深度不能用同一外观判全部。"],"source":"D17:P0237–P0242；M061/M062/M067/M068:综合目标；国家卫生健康委2025烧伤规范；MedlinePlus:动脉血气"},{"id":"shock-burn-drill-severity","title":"面积边界与全身情况同时判","stem":"甲成人热烧伤总面积50%，Ⅲ度20%；乙总面积较小，但合并休克；丙仅少量浅表发红，无疱，生命体征稳定。","prompt":"比较甲乙严重程度，并说明丙还需怎样辨认深度、关键部位和计算面积。","answer":["甲满足2025分级总面积≥50%或Ⅲ度≥20%的特重度条件，边界值不能当作未达到。","乙即使面积不足50%，合并休克也进入特重评估；优先处理循环与气道风险，不能先算完面积才报告。","共性：面积、深度、部位和合并情况共同评估；丙需确定是否仅Ⅰ度红斑以及是否关键部位，Ⅰ度不计复苏TBSA。","错用项：不得把深度Ⅲ度等同严重程度第三档，两个分类回答的问题不同。"],"source":"D17:P0175–P0201及烧伤严重程度表；国家卫生健康委《突发事件烧伤伤员医疗救治规范（2025年版）》2.3"}],"references":[{"title":"国家卫生健康委：突发事件烧伤伤员医疗救治规范（2025年版）","url":"https://www.nhc.gov.cn/ylyjs/zcwj/202601/3c4f6b771aba4ce7bdb8112823f7825a.shtml"},{"title":"NICE：成人静脉液体治疗","url":"https://www.nice.org.uk/guidance/cg174/chapter/recommendations"},{"title":"ABA：烧伤深度、面积与转诊","url":"https://www.ameriburn.org/burn-care-team/resources/guidelines-for-burn-patient-referral"},{"title":"RCUK：高钾相关急救原则","url":"https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/special-circumstances-guidelines"},{"title":"MedlinePlus：动脉血气与常用参考范围","url":"https://medlineplus.gov/lab-tests/arterial-blood-gas-abg-test/"},{"title":"国家卫生健康委2025烧伤规范：原文公开发表本","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12948514/"}]},"thorax-breast":{"title":"乳腺、胸部损伤与肺外科","intro":"共背呼吸循环、伤口引流与功能恢复；再用乳腺皮瓣、胸腔压力和肺切除范围三个条件分支。","framework":[{"id":"thorax-breast-f-breath","title":"胸部病例先联通气与循环","cue":"呼吸突变、单侧呼吸音改变或胸部外伤","answer":"先比较呼吸功、氧合、气管胸壁与血压意识，识别需立即支持的危险。把镇痛、有效咳嗽、必要气道清除和循序活动连成一条恢复链。","why":"疼痛限制深呼吸和排痰，胸腔压力异常又可影响静脉回流。","source":"D16:P0104–P0171,P0220–P0257"},{"id":"thorax-breast-f-drain","title":"引流答案背目的—系统—液体—患者","cue":"乳腺负压管或胸腔引流管","answer":"先写管路目的，再核对连接固定、密闭、位置和通畅，记录液体色质量及装置变化。最后把这些记录与局部积液、呼吸和循环状态共同解释。","why":"乳腺负压使皮瓣贴合；胸管改变胸腔积气积液，两种系统不能互套。","source":"D16:P0063–P0075,P0153–P0167,P0234–P0248"},{"id":"thorax-breast-f-function","title":"术前训练是术后恢复的准备","cue":"拟行乳腺或肺部手术","answer":"乳腺术前评估自我形象、上肢活动及支持，肺部术前评估痰液感染、呼吸练习、营养和血栓风险。术后在伤口/皮瓣与心肺允许范围内恢复活动，并请患者复述或演示。","why":"练习目的不同：肩手功能防失用，呼吸训练服务排痰和肺扩张。","source":"D16:P0051–P0099,P0207–P0219,P0254–P0259"},{"id":"thorax-breast-f-pe","title":"按证据选择护理问题","cue":"需要从病例列P-E及协同问题","answer":"有氧合异常时分析气体交换受损，有疼痛及抑制咳嗽时写疼痛及其原因。乳腺术后补皮肤/上肢功能和身体意象，肺术后补排痰与活动能力；活动性出血、气胸、瘘等进入并发症监测。","why":"同一胸部切口并不代表问题相同，相关因素取决于切除范围和当前证据。","source":"D16:P0051–P0099,P0139–P0171,P0207–P0262"}],"contrasts":[{"id":"thorax-breast-breast-benign","title":"乳腺五病种：痛、肿块与溢液横向比较","axis":"diagnosis","common":"先描述疼痛是否周期性、肿块活动度和皮肤/乳头改变，再选择检查。","rows":[{"id":"thorax-breast-mastitis","name":"急性乳腺炎","cues":"哺乳背景，局部红肿热痛伴发热","content":"联系乳汁排出受阻和感染，注意是否已有波动或脓肿。血常规与超声帮助评价，处理包括改善排乳、抗感染及脓肿引流的评估。","mechanism":"淤积加感染产生炎症，脓腔形成后单靠药物可能不足。","numbers":"","avoid":"不能套用所有哺乳期乳痛都停乳或必须手术。","source":"D16:P0009–P0014"},{"id":"thorax-breast-hyperplasia","name":"乳腺囊性增生","cues":"经前加重、经后缓解的胀痛或结节感","content":"先抓与月经周期的关系，再结合触诊及影像。出现持续增大或可疑局灶改变仍需进一步评估，不能因周期性就忽视。","mechanism":"激素波动影响腺体和间质，可出现胀痛与结节感。","numbers":"","avoid":"","source":"D16:P0015–P0019"},{"id":"thorax-breast-fibroadenoma","name":"纤维腺瘤","cues":"边界较清、表面光滑、活动度大的无痛肿块","content":"良性特征提供鉴别方向，超声及必要取样确认。随访或处理依据大小、增长和评估结果，不能只凭能推动就定性。","mechanism":"局限的纤维与腺组织增生通常较易与周围区分。","numbers":"","avoid":"","source":"D16:P0020–P0024"},{"id":"thorax-breast-papilloma","name":"乳管内乳头状瘤","cues":"自发单侧乳头溢液，特别是血性","content":"小病变可不易扪及，围绕乳管来源安排影像或专科检查。血性溢液既可来自乳头状瘤也需排查恶性病变。","mechanism":"乳管内病变表面易出血，使溢液成为线索。","numbers":"","avoid":"","source":"D16:P0025–P0029"},{"id":"thorax-breast-breast-cancer","name":"乳腺癌","cues":"无痛硬块、边界不清，伴皮肤凹陷或乳头改变","content":"描述肿块与皮肤、胸壁和淋巴结关系，影像后按评估获取病理。酒窝、橘皮及乳头内陷是不同结构受累的线索，不是三项都齐才怀疑。","mechanism":"韧带牵拉形成凹陷，皮下淋巴回流受阻形成橘皮。","numbers":"","avoid":"","source":"D16:P0030–P0050"}],"question":"经前胀痛、活动性肿块、血性溢液分别把你引向什么分支？"},{"id":"thorax-breast-cancer-pattern","title":"乳癌与肺癌：按结构受累记表现","axis":"diagnosis","common":"原发局部、邻近侵犯、远处转移分别成组，表现只能提示进一步检查。","rows":[{"id":"thorax-breast-breast-special","name":"乳癌进展与特殊类型","cues":"固定肿块、皮肤改变或乳头反复糜烂","content":"晚期注意胸壁固定、皮肤破溃、卫星结节及骨肺肝转移症状。炎性乳癌可呈弥漫红肿而无清楚肿块，Paget病可表现乳头湿疹样改变。","mechanism":"浸润、淋巴阻塞和转移位置不同，形成不同症状。","numbers":"","avoid":"反复乳头皮损不可长期只按普通湿疹处理。","source":"D16:P0035–P0044"},{"id":"thorax-breast-lung-central","name":"肺癌位置与组织类型","cues":"咳嗽咯血、阻塞性改变或外周结节","content":"中央型靠近较大支气管，支气管镜可帮助取材；周围病灶可选择经胸取样等途径。组织类型与位置有常见联系，最终须病理确认而不是口诀定型。","mechanism":"病灶位置影响气道症状和取材可达性。","numbers":"","avoid":"","source":"D16:P0176–P0185,P0205–P0206"},{"id":"thorax-breast-lung-spread","name":"肺癌局侵与远处表现","cues":"声嘶、面颈静脉充盈、吞咽困难或骨痛","content":"喉返神经、上腔静脉、食管及交感神经受累分别对应声嘶、回流受阻、吞咽困难和Horner征。远处脑骨肝等症状与副瘤表现另分组，不能都归为肺部感染。","mechanism":"肿瘤侵犯结构、转移器官及分泌活性物质的方式不同。","numbers":"","avoid":"","source":"D16:P0186–P0197"}],"question":"同样声嘶，肺癌局侵与烧伤气道风险的情境有何不同？"},{"id":"thorax-breast-diagnostic-tools","title":"检查：发现、分期与确诊各有任务","axis":"labs","common":"影像定位形态，取样明确病理，功能和全身检查评价治疗耐受。","rows":[{"id":"thorax-breast-breast-tools","name":"乳腺影像与病理","cues":"肿块或可疑乳头皮肤改变","content":"超声帮助区分囊实及观察局部，钼靶可见形态和钙化，MRI解决特定范围问题。组织取样用于确定性质，检查选择结合年龄及具体病变。","mechanism":"形态异常不能替代细胞组织学，但病理取样也需准确定位。","numbers":"","avoid":"","source":"D16:P0045–P0050"},{"id":"thorax-breast-lung-tools","name":"肺癌分期与取材","cues":"胸部可疑占位或转移线索","content":"胸部CT看原发灶，PET-CT及按症状安排的脑/骨等检查帮助分期。标志物只能辅助，支气管镜、经胸或转移灶取材需与病灶位置匹配。","mechanism":"确诊回答是什么，分期回答扩展到哪里，两者决定治疗路线。","numbers":"","avoid":"","source":"D16:P0198–P0206"},{"id":"thorax-breast-chest-tools","name":"急胸伤评估","cues":"呼吸或循环明显不稳定","content":"临床先识别通气与循环危险，影像依稳定程度安排。胸腔引流记录、血气及生命体征用于连续评价，不把一次阴性影像当永久排除。","mechanism":"严重胸腔高压可在检查等待期迅速恶化。","numbers":"","avoid":"疑张力气胸且严重呼吸/循环受损时，不能为等影像延误专业减压。","source":"D16:P0147–P0167；NICE NG39"}],"question":"某一项检查分别能回答什么、不能回答什么？"},{"id":"thorax-breast-chest-types","title":"胸伤机制与急救目的","axis":"treatment","common":"外伤先保气道和循环；不同胸腔压力机制决定紧急处理目标。","rows":[{"id":"thorax-breast-closed","name":"闭合性气胸","cues":"外伤后胸痛气促，患侧通气下降","content":"封闭伤口不等于没有积气，按症状、范围和稳定程度选择观察或引流。严密看呼吸、循环及积气进展。","mechanism":"空气进入胸膜腔使肺受压，后续不一定持续进气。","numbers":"","avoid":"","source":"D16:P0123–P0128"},{"id":"thorax-breast-open","name":"开放性气胸","cues":"胸壁开放伤伴吸吮性漏气","content":"优先覆盖开放伤并持续观察呼吸循环，准备配合后续胸腔处理。覆盖后若迅速恶化，要警惕张力性改变并立即升级。","mechanism":"胸腔与外界相通损害通气，封闭后仍可能积气增压。","numbers":"","avoid":"","source":"D16:P0129–P0133,P0141；NICE NG39"},{"id":"thorax-breast-tension","name":"张力性气胸","cues":"单侧通气差并严重呼吸受损或低灌注","content":"立即呼叫专业急救并配合紧急减压和引流。护理重点为持续气道氧合和灌注评估，处理后仍需防复发。","mechanism":"活瓣使气体积聚增压，压迫肺并减少静脉回流。","numbers":"","avoid":"不提供自助穿刺步骤；不等完整典型征才报告。","source":"D16:P0134–P0148；NICE NG39"},{"id":"thorax-breast-ribs","name":"单处骨折与连枷胸","cues":"胸痛或胸壁反常运动","content":"单处骨折重镇痛、呼吸和合并伤评估；多根多处胸壁失稳时还需看肺挫伤和通气衰竭。固定方式及呼吸支持依专业评估，不能只背外部加压。","mechanism":"疼痛抑制呼吸，胸壁失稳和肺挫伤进一步影响换气。","numbers":"","avoid":"","source":"D16:P0112–P0122,P0143–P0152"}],"question":"为什么张力气胸的护理不能只写吸氧和观察？"},{"id":"thorax-breast-breast-care","title":"乳腺术后：皮瓣、引流和上肢分三路","axis":"nursing","common":"伤口贴合、有效引流与功能恢复需要互相配合。","rows":[{"id":"thorax-breast-flap","name":"伤口与皮瓣","cues":"乳腺切除或重建后","content":"比较皮瓣颜色、温度、贴合和伤口渗液，异常及时报告。患手发麻发凉或肿胀时，同时看包扎压迫和远端血运，不能只看伤口。","mechanism":"皮瓣灌注不足与包扎压迫可影响愈合及末梢循环。","numbers":"","avoid":"重建术式、敷料和加压方式不同，不能自行松解或统一加压。","source":"D16:P0051–P0062"},{"id":"thorax-breast-breast-drain","name":"乳腺负压引流","cues":"术后引流球或负压瓶","content":"确认负压状态、连接固定和通畅，记录颜色与量的趋势。局部波动或皮瓣不贴合时联系积液；拔除后仍观察积液及感染。","mechanism":"抽出血液和渗液帮助皮瓣与胸壁贴合，量少也可能是堵塞。","numbers":"","avoid":"不单用固定天数或一个量值决定拔管。","source":"D16:P0063–P0075"},{"id":"thorax-breast-arm","name":"上肢水肿与康复","cues":"腋窝治疗后沉重感、肿胀或上肢活动受限","content":"保护皮肤，及早报告红热痛和肿胀，按康复计划从手腕、肘到肩递进。配合伤口和重建限制调整范围，并照顾身体意象及后续治疗依从性。","mechanism":"淋巴通路改变可造成慢性水肿，过度制动又增加功能受限。","numbers":"","avoid":"不能保证完全预防，也不自行强力按摩肿胀肢体。","source":"D16:P0076–P0099；NCI:淋巴水肿"}],"question":"手发凉发麻与慢性上肢水肿应怎样分别观察？"},{"id":"thorax-breast-lung-care","title":"肺切除范围与胸管：共性中找特殊","axis":"nursing","common":"镇痛排痰、引流、体液和活动共同支持恢复；切除范围决定附加限制。","rows":[{"id":"thorax-breast-lung-posture","name":"肺段、肺叶与全肺体位","cues":"需制定肺切除术后体位","content":"清醒稳定后常用利于呼吸的体位；肺段/肺叶切除需保护残余肺扩张。全肺切除需特别避免纵隔过度移位，具体侧卧幅度及引流开放方式按手术团队计划执行。","mechanism":"残肺扩张与双侧胸腔压力平衡是不同目标。","numbers":"","avoid":"咯血或瘘、氧合不佳与不稳定患者不能照搬同一侧卧姿势。","source":"D16:P0223–P0229,P0246"},{"id":"thorax-breast-chest-system","name":"胸管状态与意外异常","cues":"引流气液、水柱变化或连接异常","content":"装置直立低位、管道固定不受压，联看水柱/气泡、液体与患者症状。脱出或断接时立即呼叫并按本装置应急流程处理；不把无波动直接视为可拔管。","mechanism":"堵塞、肺复张、呼吸状态和系统泄漏都可能改变装置表现。","numbers":"","avoid":"有漏气的胸管不能随意夹闭；不把常规挤管写成所有装置通则。","source":"D16:P0153–P0167,P0234–P0248；BTS2023:胸管"},{"id":"thorax-breast-lung-complication","name":"出血、瘘与液体负荷","cues":"术后鲜红引流增多、发热漏气或呼吸恶化","content":"鲜红引流增加伴低灌注需警惕活动性出血，持续漏气伴发热等联系支气管胸膜瘘。全肺切除后尤其注意输液与呼吸负荷，肺部感染、肺不张和血栓风险另列。","mechanism":"胸腔丢血与肺水肿都可气促，但循环和引流证据不同。","numbers":"","avoid":"不把所有术后气促都归为正常疼痛。","source":"D16:P0244–P0257"}],"question":"全肺切除为何不能照搬普通气胸持续引流和任意侧卧？"}],"drills":[{"id":"thorax-breast-drill-breast","title":"一张乳腺护理框架，三条证据","stem":"乳腺切除术后，患者担心外形改变；引流量突然减少但局部出现波动感，患手又诉发凉。","prompt":"分别写共性护理、三种问题的解释和不能套用的做法。","answer":["共性：核对引流连接、负压和通畅，比较液体趋势、伤口皮瓣及远端循环。","个性：量少伴波动提示积液/引流问题；手发凉提示需评估包扎压迫及血运；外形担忧需沟通、身体意象支持及康复教育。","及时报告局部积液和血运异常，按医嘱维护系统并记录处理反应。","错用项：不能把引流少直接认定可拔管，不能强力按摩患肢或自行拆压迫敷料。"],"source":"D16:P0051–P0099"},{"id":"thorax-breast-drill-lung","title":"同是胸管，目的不同","stem":"甲胸部外伤后单侧呼吸音明显下降，出现低血压；乙刚完成全肺切除，护士接班时发现引流开放计划未交清。","prompt":"分别写首要任务，并说明二人的胸管计划为何不能互抄。","answer":["共性：立即比较呼吸、氧合、意识和循环，核对管路及记录。","甲需优先警惕危及呼吸循环的胸伤并呼叫支持，不能为等影像或观察而延误专业急救。","乙先确认手术范围与胸腔压力管理计划，联系手术团队核实开放方式，注意体位和输液负荷。","错用项：不能将全肺切除特殊压力平衡套成普通气胸，也不能随意夹闭正在漏气的胸管。"],"source":"D16:P0134–P0175,P0223–P0262；NICE NG39；BTS2023"},{"id":"thorax-breast-drill-open","title":"开放伤的声音提示什么","stem":"胸部外伤患者胸壁有开放伤，呼吸时可闻漏气声，并出现发绀、烦躁和肢凉。","prompt":"列诊断线索、现场优先任务与引流后观察，说明错用项。","answer":["漏气伤口与呼吸受损支持开放性气胸方向，仍需评估合并肋骨、肺和血管损伤。","共性：立即呼叫支持、评估气道呼吸循环和外出血，专业流程下覆盖伤口并密切观察。","个性：覆盖后仍看张力性改变；后续胸管核对密闭、连接位置与气液变化，异常联看患者症状。","错用项：不能把覆盖伤口当最终治疗，也不能自行穿刺或随意夹闭漏气管。"],"source":"D16:P0129–P0175；M059:目标；NICE NG39"},{"id":"thorax-breast-drill-breast-diagnosis","title":"无痛乳块并非无风险","stem":"患者摸到逐渐增大的无痛乳块，边界不清且与周围组织不易推动；影像有可疑改变。","prompt":"说明鉴别证据、确诊途径和术后若留引流时的学习重点。","answer":["共性：描述肿块、皮肤乳头和区域淋巴结，结合影像及取样确定性质，提供心理支持。","个性：不规则固定性特征需警惕乳癌方向；周期性胀痛、活动光滑肿块和血性溢液则走不同鉴别分支。","如手术，另补皮瓣血供、负压引流和上肢功能/身体意象，而非只抄胸管护理。","错用项：不痛不代表良性，钼靶可疑也不等于已经完成病理确诊。"],"source":"D16:P0002–P0103；M057:目标"}],"references":[{"title":"NCI：乳腺癌手术及重建","url":"https://www.cancer.gov/types/breast/treatment/surgery"},{"title":"NCI：治疗相关淋巴水肿","url":"https://www.cancer.gov/about-cancer/treatment/side-effects/lymphedema"},{"title":"NICE：重大创伤胸部处理","url":"https://www.nice.org.uk/guidance/ng39/chapter/Recommendations"},{"title":"BTS：胸膜操作与引流","url":"https://www.brit-thoracic.org.uk/clinical-resources/clinical-statements/pleural-procedures/"}]},"urology-surgery":{"title":"泌尿外科：损伤、结石、梗阻与肿瘤","intro":"用血尿、疼痛、排尿改变识别入口，用感染、梗阻、出血和肾功能决定优先级；每一种管路和术式再加专属护理。","framework":[{"id":"urology-surgery-f-entry","title":"三症状连四种危险","cue":"血尿、腰腹痛或排尿困难","answer":"先描述血尿是否疼痛及间歇、疼痛放射和排尿变化，再核对感染、梗阻、活动性出血及肾功能。发热合并少尿/无尿、血压下降或外伤后进行性血尿需立即升级。","why":"疼痛缓解与血尿停止都不能证明梗阻或肿瘤病因消失。","source":"D18:P0002–P0057,P0143–P0159"},{"id":"urology-surgery-f-tubes","title":"每根管子背所在—目的—记录—移除","cue":"尿管、双J、肾造瘘或尿流改道","answer":"先分体内支架与体外引流，标清位置和目的，再写固定、通畅、感染及异常信号。体外管记录色质量，体内双J重在症状和返院移除，不能等无症状才处理。","why":"肾造瘘从肾盂向外引流，双J跨输尿管支撑引流，尿管排空膀胱；护理入口不同。","source":"D18:P0255–P0274,P0302–P0304；D19:P0186–P0209"},{"id":"urology-surgery-f-count","title":"尿量先扣冲洗，再联系肾功能","cue":"TURP或膀胱术后持续冲洗","answer":"分别记冲入量和引出量，实际尿量为总引流量减冲洗液量。结合尿色血块、耻骨上胀痛和生命体征判断堵塞或出血，不能仅根据袋量多判断尿量充足。","why":"冲洗液不是患者产生的尿液，流出减少也可能因管路阻塞。","source":"D18:P0264–P0268；D19:P0260–P0265"},{"id":"urology-surgery-f-pe","title":"同是泌尿疾病，相关因素分开","cue":"需要列护理问题","answer":"损伤以疼痛、失血/体液不足及焦虑为线；结石以疼痛、排尿异常及复发知识为线。BPH补夜尿影响睡眠，膀胱癌改道补身体意象与自护能力，协同问题按出血、感染、梗阻或代谢分别列。","why":"同名疼痛可由血肿、平滑肌痉挛或肿瘤造成，护理措施须回到原因。","source":"PDF24:PDF页1；D18:P0235–P0238"},{"id":"urology-surgery-f-prevent","title":"复发预防必须连成分与条件","cue":"排出结石或带管出院","answer":"结石送成分分析，并结合血尿代谢、感染和梗阻安排饮食与复查。饮水按心肾及尿量目标个体化，带管者必须说清异常就医和返院移除计划。","why":"尿量减少、过饱和、感染、异物和淤滞可共同成石，统一忌钙会错过真正原因。","source":"D18:P0299–P0309；D19:P0087–P0102,P0200–P0209"}],"contrasts":[{"id":"urology-surgery-trauma","title":"损伤部位：血尿相似，尿外渗和检查不同","axis":"diagnosis","common":"先处理生命危险，再定位肾、膀胱或尿道；血尿轻重不直接等于损伤程度。","rows":[{"id":"urology-surgery-renal-trauma","name":"肾损伤","cues":"腰腹外伤、腰痛血尿或肿块","content":"比较循环、血象、尿色和腰腹肿块，CT用于评价损伤。保守期间出现发热、加重腰痛或血象异常需重评尿外渗、感染及迟发出血。","mechanism":"肾实质/血管出血与集合系统漏尿可并存。","numbers":"","avoid":"不把所有肾损伤或肾术后统一要求固定长时间绝对卧床。","source":"D18:P0008–P0013,P0241–P0248；D19:P0010–P0015,P0062–P0085；EAU:肾损伤"},{"id":"urology-surgery-bladder-trauma","name":"膀胱损伤","cues":"骨盆伤后血尿、下腹痛、尿意但排出少","content":"腹膜内尿漏可表现腹膜炎，腹膜外多表现局部外渗。膀胱造影用于评价漏出，持续排空与是否修补依破裂类型决定。","mechanism":"尿液外漏位置决定腹部表现，膀胱持续充盈可影响愈合。","numbers":"","avoid":"","source":"D18:P0014–P0019,P0101–P0109,P0191–P0193；D19:P0016–P0021,P0037–P0040；EAU:膀胱损伤"},{"id":"urology-surgery-urethral-trauma","name":"尿道损伤","cues":"骑跨或骨盆伤，尿道口血、会阴肿胀或不能排尿","content":"前尿道与后尿道关联的受伤机制、出血和尿外渗部位不同。逆行尿道造影或内镜帮助评价，导尿或耻骨上引流由有经验团队决定。","mechanism":"通道损伤及周围血肿会改变尿液流向。","numbers":"","avoid":"不能反复盲插；也不能把完全禁止一切专业导尿写成无条件规则。","source":"D18:P0020–P0025,P0104–P0109,P0194–P0199；D19:P0022–P0027,P0041–P0061；EAU:尿道损伤"}],"question":"外伤后少量血尿是否一定比大量血尿轻？"},{"id":"urology-surgery-patterns","title":"结石、增生与肿瘤：症状按模式记","axis":"diagnosis","common":"症状提供方向，检查解决性质和范围；疼痛或出血停止都需解释。","rows":[{"id":"urology-surgery-stone-pattern","name":"结石及形成因素","cues":"腰部绞痛向下放射，伴血尿或恶心","content":"把尿液过饱和、尿量少、pH改变、抑制物少与局部淤滞/感染/异物分两组。药物可直接成石或改变代谢，绞痛与输尿管痉挛/梗阻相连。","mechanism":"腔内压力和共同神经支配可使腰痛伴胃肠症状。","numbers":"","avoid":"","source":"D19:P0087–P0111；D18:P0026–P0031"},{"id":"urology-surgery-bph-pattern","name":"良性前列腺增生","cues":"尿频夜尿、尿线弱、排尿迟缓或潴留","content":"储尿症状和排尿症状分组，夜尿还需评价睡眠。结合残余尿、指检和尿流等检查，排除肿瘤及其他原因后制定处理。","mechanism":"出口阻力上升可使膀胱排空不全，长期可影响上尿路。","numbers":"","avoid":"","source":"D18:P0032–P0037；D19:P0218–P0226"},{"id":"urology-surgery-bladder-cancer","name":"膀胱癌","cues":"无痛性间歇肉眼血尿","content":"血尿是重要线索，膀胱刺激征、梗阻及全身变化另列。按评估行膀胱镜/活检及分期检查，不能因血尿自行消退就停止查因。","mechanism":"肿瘤表面出血可间歇出现，并不随病灶消失。","numbers":"","avoid":"","source":"D18:P0038–P0043；D19:P0227–P0235"},{"id":"urology-surgery-kidney-cancer","name":"肾癌","cues":"血尿腰痛、占位或异常全身表现","content":"传统血尿疼痛肿块三联征并非早期必备，另记发热、贫血/红细胞增多、高钙及转移线索。同侧精索静脉曲张平卧不消失时也需评估。","mechanism":"肿瘤占位、静脉受累及副瘤作用可产生肾外表现。","numbers":"","avoid":"","source":"D18:P0044–P0050；D19:P0236–P0244"},{"id":"urology-surgery-prostate-cancer","name":"前列腺癌","cues":"异常指检、PSA或骨痛，伴或不伴排尿症状","content":"早期可无特异症状，指检硬结或不规则需进一步评估。PSA受多因素影响，是否取样和治疗需结合风险、影像及病理。","mechanism":"局部侵犯与骨转移产生不同表现，PSA不是肿瘤专属标志。","numbers":"","avoid":"PSA正常不能排除癌；不能把类似BPH症状直接定为良性。","source":"D18:P0051–P0056,P0076–P0078；D19:P0245–P0251"}],"question":"无痛血尿和绞痛血尿分别怎样展开，哪些危险仍共同检查？"},{"id":"urology-surgery-tools","title":"检查：成分、通畅、损伤和病理分别看","axis":"labs","common":"先写检查要回答的问题，再写结果意义。","rows":[{"id":"urology-surgery-urine-tools","name":"尿血与代谢检查","cues":"血尿、感染或复发结石","content":"尿常规/培养看出血与感染，血象追踪失血炎症，肌酐电解质评价肾功能。结石成分加血尿代谢用于预防，不能只凭尿pH决定全部饮食。","mechanism":"当前感染与长期成石机制需不同证据。","numbers":"","avoid":"","source":"D18:P0058–P0081；D19:P0112–P0124"},{"id":"urology-surgery-imaging-tools","name":"超声、CT及尿路成像","cues":"结石、积水、损伤或肿块","content":"超声看积水与部分病灶，CT用于进一步定位和范围评价，选择需考虑妊娠、辐射及造影。KUB并非能显示所有成分，IVU/其他尿路成像按具体问题安排。","mechanism":"结石成分、大小和周围结构影响显影与检查选择。","numbers":"","avoid":"不是所有患者必须完成同一套检查。","source":"D18:P0082–P0115；D19:P0125–P0139；NICE NG118"},{"id":"urology-surgery-scope-tools","name":"内镜、活检及功能检查","cues":"怀疑膀胱/前列腺病变或出口梗阻","content":"膀胱镜可直接观察并取样，前列腺相关病变按评估选择影像与活检。尿流和残余尿反映排空，不能靠一个流率数值单独确诊BPH。","mechanism":"解剖、组织性质和排空功能不是同一问题。","numbers":"","avoid":"","source":"D18:P0116–P0141；D19:P0223–P0251"}],"question":"为什么取到结石后还要送成分分析？"},{"id":"urology-surgery-stone-treatment","title":"治疗选择：部位、大小、感染梗阻一起决定","axis":"treatment","common":"把观察/排石、碎石、内镜和经皮途径与病情条件配对。","rows":[{"id":"urology-surgery-stone-watch","name":"非手术管理","cues":"小结石且适合观察，无感染性梗阻或肾功能危险","content":"镇痛后仍随访排出、梗阻和肾功能，适宜者可评估药物排石。饮水、活动和复查需具体化，不能疼痛一缓解就认定排石。","mechanism":"症状可在结石仍留存时减轻。","numbers":"","avoid":"发热感染合并梗阻、无尿或难控制疼痛不属于单纯居家多喝水分支。","source":"D18:P0160–P0180,P0212–P0234；D19:P0140–P0167；EAU:尿石症"},{"id":"urology-surgery-stone-tech","name":"ESWL、URL、PCNL与腹腔镜","cues":"已决定积极处理结石","content":"ESWL体外击碎后仍需排出，URL经输尿管镜处理，PCNL经皮进入肾内，腹腔镜用于部分选择情境。按位置、体积、密度、解剖和患者条件比较，失败或复杂情况需换路线。","mechanism":"入口与碎片排出路径不同，造成术前配合及术后观察差异。","numbers":"需积极去除的肾结石＞2cm时，PCNL为主要首选；肾下盏、解剖/出血风险及不能行PCNL者需另评估。不是所有＜2cm肾石都默认ESWL。","avoid":"不能按单一尺寸阈值无条件指定唯一术式。","source":"D18:P0212–P0234；D19:P0140–P0162；EAU:尿石症"},{"id":"urology-surgery-infected-obstruction","name":"感染性梗阻","cues":"发热寒战并有结石梗阻、少尿或无尿","content":"感染控制与紧急引流并行，可由团队选择输尿管支架或经皮引流。病情稳定和感染受控后再决定结石根治处理。","mechanism":"封闭感染系统中单靠抗菌药或镇痛不足以解决压力和感染源。","numbers":"","avoid":"不能让患者靠跳跃排石或先完成择期碎石流程。","source":"D18:P0143–P0159；D19:P0109,P0181；EAU:尿石症急症"}],"question":"感染性梗阻为何要把引流与根治结石分开？"},{"id":"urology-surgery-bph-care","title":"BPH：两类药、冲洗与并发症","axis":"nursing","common":"把解除梗阻与手术后液体、出血及排尿恢复分层。","rows":[{"id":"urology-surgery-bph-drugs","name":"非手术用药与潴留","cues":"尿频困难，拟使用α受体阻滞剂或5α还原酶抑制剂","content":"前者减轻平滑肌张力，注意体位性头晕；后者影响腺体相关激素途径，需说明起效与性功能等不良反应。急性潴留需专业排空评估，日常避免憋尿并处理便秘。","mechanism":"动态阻力与腺体体积均影响出口梗阻，治疗作用时间不同。","numbers":"","avoid":"不因症状缓解自行停药；不把急性潴留仅作为睡眠问题。","source":"D18:P0173–P0176,P0250；D19:P0252–P0259"},{"id":"urology-surgery-turp-irrigation","name":"术后膀胱冲洗","cues":"TURP后有血尿与冲洗医嘱","content":"核对流入流出、血块、尿色和耻骨上胀痛，真实尿量需扣冲洗。持续鲜红或流出受阻时联看生命体征并报告，维护通畅依流程而非暴力推注。","mechanism":"创面出血与血块阻塞可互相促进，袋量掩盖真实尿量。","numbers":"","avoid":"","source":"D18:P0264–P0267；D19:P0260–P0262"},{"id":"urology-surgery-turp-syndrome","name":"液体吸收相关综合征及其他并发症","cues":"术后意识改变、呼吸困难或容量/电解质异常","content":"联系冲洗液吸收、容量负荷和低钠，及时查电解质并配合处理；风险随手术技术和液体不同。另列出血、尿失禁、尿道狭窄和附睾炎，按出血、尿线变细、阴囊痛等证据区分。","mechanism":"吸收的液体改变容量和渗透压，其他并发症则源于创面、瘢痕或感染。","numbers":"","avoid":"不把旧式单极手术的全部风险无条件套给所有TURP。","source":"D18:P0275–P0284；D19:P0263–P0274"}],"question":"冲洗后袋中液体很多，为什么仍不能说明尿量正常？"},{"id":"urology-surgery-stone-aftercare","title":"结石处理后：术式带来不同管路与风险","axis":"nursing","common":"疼痛、发热、血尿、肾功能和排石趋势共同观察。","rows":[{"id":"urology-surgery-eswl","name":"ESWL与石街","cues":"体外碎石后需排出碎片","content":"记录排石及症状，按要求收集碎片分析，随访是否残留。碎片堆积成石街后若伴感染、梗阻或肾功能变化需及时复评和可能引流。","mechanism":"碎开不等于排净，输尿管可被多个碎片堵住。","numbers":"","avoid":"发热少尿时不能仅增加活动或大量饮水等待。","source":"D18:P0249,P0285–P0287；D19:P0168–P0181；EAU:尿石症"},{"id":"urology-surgery-nephrostomy","name":"肾造瘘、肾周管与双J","cues":"经皮/开放或输尿管镜术后","content":"体外肾造瘘看固定低位、引流和感染，肾周管看渗出；双J重在症状及移除计划。出现突增鲜红引流、发热腰痛或排尿恶化时联系出血、梗阻和感染，不自行夹管或拔管。","mechanism":"不同管路终点不同，出血和堵塞会造成流量突变。","numbers":"","avoid":"不按统一日数拔除所有管路，也不把双J当体外冲洗管。","source":"D18:P0255–P0263,P0288–P0290；D19:P0182–P0199"},{"id":"urology-surgery-stone-prevention","name":"复发与双J居家教育","cues":"准备出院或结石成分已知","content":"把充足尿量、饮食成分、盐和动物蛋白习惯与代谢结果配对，合理钙摄入不能统一取消。教患者观察发热、血块、持续腰痛及刺激征，并清楚复诊和支架移除安排。","mechanism":"尿液稀释及去除感染、异物、梗阻共同减少成石条件。","numbers":"","avoid":"心肾限水者不可照搬大量饮水；症状少不能无限期保留双J。","source":"D18:P0292–P0309；D19:P0200–P0209"}],"question":"体内双J与体外肾造瘘的出院交代哪几项不同？"},{"id":"urology-surgery-cancer-care","title":"膀胱及其他泌尿肿瘤：保留什么、改道到哪里","axis":"treatment","common":"先明确肿瘤部位、分期与术式，再决定管路、自护和功能训练。","rows":[{"id":"urology-surgery-bladder-instill","name":"保膀胱手术与灌注","cues":"电切后有膀胱灌注计划","content":"区分冲洗与药物灌注：冲洗维持流通，灌注为局部治疗。核对药物方案及保留要求，观察刺激症状、血尿和全身反应；异常及时联系团队。","mechanism":"目的不同，进入体内的液体不能用同一流速和记录方式管理。","numbers":"","avoid":"疑穿孔等情境不能照常执行既定灌注；不自行改药或保留时间。","source":"D18:P0181–P0183,P0269–P0274；D19:P0284–P0289"},{"id":"urology-surgery-diversion","name":"膀胱全切后两类尿流改道","cues":"回肠通道造口或原位新膀胱","content":"腹壁造口重在尿液收集、造口活力与周围皮肤；原位新膀胱重在规律排空、残余尿和排尿训练。两者均需关注感染、尿漏和肠段参与尿流后的电解质/代谢变化。","mechanism":"肠段黏膜与尿液接触会影响吸收，储尿与连续外引流的机制不同。","numbers":"","avoid":"原位新膀胱训练与肠造口排便训练不可互抄。","source":"D18:P0291–P0298；D19:P0278–P0299"},{"id":"urology-surgery-renal-prostate-treatment","name":"肾癌与前列腺癌治疗关联","cues":"已确诊肿瘤，需比较治疗","content":"肾肿瘤可评估部分切除或根治切除等，护理需联系保留肾功能。前列腺癌局部治疗与激素等系统治疗按风险分层，护理增加排尿、性功能及心理支持。","mechanism":"不同器官的切除与激素敏感性不同，术后目标不可用一张膀胱模板代替。","numbers":"","avoid":"不是所有肾肿瘤术前都必须穿刺，也不是所有前列腺癌都同一治疗。","source":"D18:P0206–P0211；D19:P0236–P0251"}],"question":"冲洗、灌注、尿流改道三者的目的分别是什么？"}],"drills":[{"id":"urology-surgery-drill-stone","title":"镇痛后仍要解决什么","stem":"患者输尿管结石，止痛后疼痛减轻，但寒战、发热且尿量继续下降；家属问能否多喝水后回家等排石。","prompt":"用共性骨架说明危险，给出本例个性分支及错用项。","answer":["共性：复核生命体征、尿量、肾功能、尿检/培养及影像梗阻，疼痛反应只是其中一项。","个性：感染合并梗阻是需紧急处理的分支，及时报告并配合抗感染及引流评估，根治结石时机另定。","记录药物、液体和引流反应，按实际肾功能安排饮水而非盲目增加。","错用项：镇痛有效不代表梗阻解除；不能靠跳跃排石替代感染源处理。"],"source":"D18:P0143–P0159；D19:P0109,P0181；EAU:尿石症"},{"id":"urology-surgery-drill-turp","title":"一袋液体，两笔账","stem":"TURP术后，本班冲洗液输入2400mL，引流袋共引出2800mL；患者新诉耻骨上胀痛，管内可见血块。","prompt":"计算本班记录的实际尿量，并列进一步核对及护理问题。","answer":["计算：实际尿量为2800－2400＝400mL；仍需结合记录时段、漏液与测量是否完整。","共性：核对流入流出、管路通畅、尿色血块及生命体征，观察疼痛和膀胱胀。","个性：TURP创面与冲洗使血块堵塞和出血成为重点，及时报告并按流程维护通畅，观察呼吸/意识及电解质相关变化。","错用项：不能把2800mL当尿量，也不能对阻塞尿管暴力推注。"],"source":"D18:P0264–P0280；D19:P0260–P0265"},{"id":"urology-surgery-drill-trauma","title":"肾损伤保守期怎样看变化","stem":"腰部外伤伴肉眼血尿患者初步稳定，随后腰痛加重、尿色更深且血红蛋白较前下降。","prompt":"写诊断依据、保守护理共性与升级条件，并说明出院教育。","answer":["共性：记录循环、尿量、血象、疼痛和肾功能，保护管路并配合液体治疗与复评。","个性：腰外伤与动态出血提示肾及合并伤需再评估，查迟发出血、血肿/尿漏等并及时报告，不仅调整止痛。","活动与复诊按损伤级别及恢复计划，教会再次腰痛、血尿、发热或晕厥时就医。","错用项：血尿轻重不能独立分级；不因初期稳定就停止观察，也不统一所有术后绝对卧床。"],"source":"D18:P0239–P0248,P0288–P0304；D19:P0062–P0085；M069:目标；EAU:创伤"},{"id":"urology-surgery-drill-bph","title":"夜尿之外还有哪条线","stem":"老年患者夜尿增加、尿线细、排尿等待且偶有溢尿，检查提示残余尿增加。","prompt":"按P-E、检查、治疗与术后可能护理列提纲。","answer":["排尿形态改变联系出口梗阻，夜尿影响睡眠，焦虑与治疗担忧需具体询问；残余尿提示排空问题但不单独定病因。","共性：评估尿路感染、潴留、肾功能与真实尿量，结合指检及相关检查排除其他原因。","个性：用药需比较α受体阻滞剂与5α还原酶抑制剂；若TURP，增加冲洗、出血、液体吸收及后续排尿恢复。","错用项：年龄大不等于一定良性；不能把溢尿当已排空，也不能用夜间少喝水代替梗阻评价。"],"source":"D18:P0032–P0037,P0173–P0176,P0264–P0284；D19:P0252–P0277；M071:目标"},{"id":"urology-surgery-drill-choice","title":"结石治疗选择要给理由","stem":"无发热的患者影像见肾盂多发结石，平时少饮水且动物性食物多。团队准备在体外碎石、软镜与经皮方案中选择。","prompt":"列选择信息、各方式差异和复发教育，说明还不能直接下什么结论。","answer":["需补结石总体负荷、位置密度、解剖、肾功能、感染及出血/妊娠等限制，不能只看最大直径。","个性：ESWL碎后要排出，软镜经自然腔道，PCNL经皮处理；需积极处理的肾石＞2cm时PCNL通常为主要首选，具体仍评估。","共性：疼痛与尿量观察、结石成分/代谢评估、个体化饮水饮食和复查。","错用项：喜欢肉食不能直接确定尿酸成分，不把所有小于2cm肾石统一为体外碎石。"],"source":"D18:P0212–P0234,P0299–P0309；D19:P0087–P0209；M070:目标；EAU:尿石症"}],"references":[{"title":"EAU：尿石症","url":"https://uroweb.org/guidelines/urolithiasis/chapter/guidelines"},{"title":"EAU：泌尿生殖系统创伤","url":"https://uroweb.org/guidelines/urological-trauma/chapter/urogenital-trauma-guidelines"},{"title":"NICE：肾与输尿管结石","url":"https://www.nice.org.uk/guidance/ng118/chapter/recommendations"}]},"hepatobiliary":{"title":"肝胆胰外科：梗阻、感染、切除与引流","intro":"共背疼痛、营养液体、引流皮肤及出血感染；再比较肝储备、胆道通畅和胰腺消化内分泌功能。","framework":[{"id":"hepatobiliary-f-chain","title":"腹痛黄疸发热要连器官功能","cue":"肝胆胰病或术后腹痛","answer":"先写疼痛部位放射、黄疸及感染表现，再联系意识、血压、尿量、氧合和凝血。诊断资料按局部病因与全身严重度两栏组织，不能见右上腹痛就统一成胆囊炎。","why":"梗阻、感染与胰酶相关炎症可共同影响循环及多个器官。","source":"D20:P0069–P0087,P0172–P0179,P0184–P0203"},{"id":"hepatobiliary-f-drain","title":"引流管必须连目的与性质","cue":"T管、PTCD、腹腔双套管或空肠管","answer":"先辨胆道减压、腹腔引流/灌洗与营养输入三种目的，再看固定、通畅、记录和皮肤。引流突然变血性、胆汁样或含肠内容物时，联看腹痛发热和循环，及时报告。","why":"消化液刺激皮肤并可造成体液损失，不同液体也提示不同通道异常。","source":"D20:P0144–P0166,P0196–P0203"},{"id":"hepatobiliary-f-reserve","title":"术前准备按肝功能、凝血、营养","cue":"拟行肝切除、胆道或胰腺手术","answer":"评估进食、体重、肝功能、凝血和水电解质，识别贫血及营养风险。黄疸者增加皮肤与凝血观察，肝储备差者增加脑病及液体负荷风险，胰病另看血糖。","why":"肝合成与代谢能力、胆汁排泄和胰腺功能分别影响手术耐受。","source":"D20:P0012–P0024,P0148–P0154,P0205–P0212"},{"id":"hepatobiliary-f-pe","title":"护理问题不能只有疼痛","cue":"需要列护理诊断及相关因素","answer":"肝癌连肿瘤痛、摄入不足与消耗、焦虑；AOSC连感染性高热及灌注不足。胰腺炎连渗出/呕吐/禁食和营养，胰腺癌补慢性痛、瘙痒皮肤及预感性悲哀；并发症按出血、瘘、感染和代谢另列。","why":"共性问题保留原因差异，才能决定干预重点。","source":"PDF26:PDF页1；D20:P0057–P0060,P0224–P0227"},{"id":"hepatobiliary-f-post","title":"术后变化按四种异常复盘","cue":"切除/介入后病情变化","answer":"先分出血与低灌注、感染与积液、胆/胰/肠液漏出、消化与血糖功能变化。为每条补当前证据、需要复核的化验/影像及引流营养护理，避免只写术后常规。","why":"同一发热可能是感染、炎症或介入反应，必须联系时间与伴随症状。","source":"D20:P0030–P0049,P0193–P0222"}],"contrasts":[{"id":"hepatobiliary-biliary-pattern","title":"胆道病：部位、感染和器官风险比较","axis":"diagnosis","common":"胆绞痛、发热和黄疸是线索组合，按梗阻位置和严重度展开。","rows":[{"id":"hepatobiliary-gallstone","name":"胆囊结石及胆囊炎","cues":"油腻餐后右上腹痛，向右肩背放射","content":"胆囊结石可间歇绞痛；合并炎症时持续痛、发热及Murphy征更支持胆囊炎。形成因素按胆汁过饱和、成核、排空不良及感染/代谢习惯归纳。","mechanism":"结石嵌顿与胆囊收缩增加张力，淤滞促进结晶及感染。","numbers":"","avoid":"无症状偶发现结石与症状性结石处理不同。","source":"D20:P0062–P0075,P0082–P0084；NICE CG188"},{"id":"hepatobiliary-duct-stones","name":"肝外与肝内胆管结石","cues":"黄疸、寒战高热或反复胆管炎","content":"肝外梗阻可出现腹痛、寒战发热、黄疸组合，观察尿便颜色及胆红素。肝内结石可反复感染并累及肝实质，注意肝脓肿及胆汁淤积背景。","mechanism":"胆汁流出受阻使管内压升高，并利于细菌扩散。","numbers":"","avoid":"","source":"D20:P0076–P0081"},{"id":"hepatobiliary-aosc","name":"急性重症胆管炎","cues":"胆道感染背景新发低血压或意识异常","content":"在腹痛发热黄疸之外，意识和灌注恶化提示严重感染/器官风险。应把复苏、抗感染与及时解除梗阻/引流连写，不能等所有五项表现齐全。","mechanism":"感染与管内压力共同促进全身炎症，形成休克和器官损害。","numbers":"","avoid":"降温后不代表感染源已控制。","source":"D20:P0085–P0087,P0167–P0183"}],"question":"为何同是右上腹痛，有的需要择期处理，有的需紧急感染源控制？"},{"id":"hepatobiliary-hep-pan-pattern","title":"肝癌、胰腺炎和胰腺癌的个性线索","axis":"diagnosis","common":"位置相近不等于疾病相同，病程、功能与检查应配对。","rows":[{"id":"hepatobiliary-liver-cancer","name":"肝癌","cues":"慢性肝病背景，肝区痛、消瘦或占位","content":"肿瘤证据与基础肝病及肝储备分别评价，AFP需与影像等组合。术前关心营养、凝血及肝功能，术后重点出血、胆漏、膈下积液及脑病。","mechanism":"肿瘤与肝硬化可共同影响合成、凝血与代谢。","numbers":"","avoid":"AFP单独升高不能完成全部确诊与治疗选择。","source":"D20:P0002–P0060"},{"id":"hepatobiliary-pancreatitis","name":"重症胰腺炎","cues":"持续上腹痛向背放射，呕吐并全身恶化","content":"病因考虑胆石、酒精及其他因素，不能因饮酒就停止查胆道。结合酶、影像与器官状态评价，治疗中关注液体渗出、呼吸循环、感染坏死和营养。","mechanism":"胰腺炎症及毛细血管渗漏可使局部病变影响全身。","numbers":"","avoid":"","source":"D20:P0184–P0203；NICE NG104"},{"id":"hepatobiliary-pancreatic-cancer","name":"胰腺癌","cues":"持续上腹/背痛，黄疸消瘦或消化变化","content":"营养摄入、消化吸收、血糖、胆道梗阻和疼痛分别评估。手术部位决定切除/重建范围，术后注意胰胆瘘、出血、感染和胃排空问题。","mechanism":"胰腺兼外分泌与内分泌，肿瘤或切除可同时影响消化和糖代谢。","numbers":"","avoid":"","source":"D20:P0204–P0227；NCI:胰腺癌"}],"question":"胰腺癌术后的血糖护理为何不能从胆囊术后模板直接复制？"},{"id":"hepatobiliary-tools","title":"六类胆道检查及肿瘤检查","axis":"labs","common":"检查前看禁食/镇静及出血风险，检查中看耐受，检查后看操作相关并发症。","rows":[{"id":"hepatobiliary-us-mrcp","name":"超声、MRCP与EUS","cues":"需要定位胆石或梗阻","content":"肝功能与超声常作初步检查，必要时MRCP看胆胰管，仍不清楚可评估EUS。MRCP注意金属设备安全，EUS需考虑内镜镇静和误吸风险。","mechanism":"非侵入成像与内镜超声的入路和风险不同。","numbers":"","avoid":"不是所有胆道检查统一禁食同一时长。","source":"D20:P0094–P0104,P0120–P0124；NICE CG188"},{"id":"hepatobiliary-ercp","name":"ERCP","cues":"需胆胰管成像、取样、取石或引流","content":"术前核对心肺、凝血、药物及禁食镇静安排，术中关注呼吸循环。术后把腹痛、发热、出血、胰酶及腹膜刺激征连看，评估胰腺炎或穿孔等。","mechanism":"经乳头操作既能治疗，也可刺激胰胆管或造成损伤。","numbers":"","avoid":"不将诊断性影像与有创治疗的风险等同。","source":"D20:P0105–P0109"},{"id":"hepatobiliary-ptc","name":"PTC/PTCD与T管造影","cues":"经皮胆道穿刺或留置T管需评估通畅","content":"PTC/PTCD前核对凝血等风险，之后观察出血、胆汁漏及引流。T管造影看残石和通畅，操作后按计划恢复引流并观察腹痛发热，不能自行拔管。","mechanism":"穿刺及造影入口不同，但压力过高或引流受阻都可能增加风险。","numbers":"","avoid":"","source":"D20:P0110–P0119,P0163"},{"id":"hepatobiliary-liver-tests","name":"AFP、影像与组织取样","cues":"怀疑肝占位或肿瘤","content":"AFP是辅助线索，影像形态、病史和肝功能共同参与评价。是否需要穿刺依影像诊断和治疗计划决定，并核对出血风险。","mechanism":"标志物缺乏绝对特异性，而侵入取样也有选择条件。","numbers":"","avoid":"","source":"D20:P0003–P0011；NCI:肝癌"}],"question":"EUS、ERCP和MRCP名称相近，为什么护理准备不能完全相同？"},{"id":"hepatobiliary-treatment","title":"治疗目标：切除、感染源控制与功能支持","axis":"treatment","common":"每项回答解决什么、保留什么，以及由此带来哪些护理重点。","rows":[{"id":"hepatobiliary-liver-tace","name":"肝切除与TACE","cues":"已制定局部肝癌治疗","content":"切除后看肝储备、出血、胆漏及积液；TACE把局部栓塞/药物治疗与穿刺通路护理联结。介入后发热疼痛恶心可见于栓塞反应，但仍须排查出血、感染或肝功能恶化。","mechanism":"肝实质切除和供血栓塞影响组织的方式不同。","numbers":"","avoid":"不能把所有介入后发热都判正常，也不统一套一个压迫卧床时长。","source":"D20:P0025–P0049；NCI:肝癌"},{"id":"hepatobiliary-duct-control","name":"胆囊切除、取石与减压","cues":"症状性胆石或感染梗阻","content":"胆囊切除处理胆囊来源病变，胆管取石/引流关注通畅和感染源。T管目的包括引流减压、支持胆道通畅评估及部分残石处理，不能只背管名。","mechanism":"胆囊与胆总管的位置和功能不同，术后管路也不同。","numbers":"","avoid":"","source":"D20:P0125–P0147,P0167–P0171"},{"id":"hepatobiliary-pan-nutrition","name":"胰腺炎营养与坏死处理","cues":"急性胰腺炎伴呕吐、营养风险或坏死","content":"不能把所有胰腺炎一律禁食，是否经口/肠内取决于耐受和明确限制。疑感染坏死由团队评估内镜/经皮及其他干预，护理维护引流与营养，抗菌药不作人人预防使用。","mechanism":"保留肠道营养与控制感染坏死是两条不同治疗线。","numbers":"","avoid":"无明确原因不长期禁食；肠外营养不是所有人的第一选择。","source":"D20:P0185–P0203；NICE NG104"},{"id":"hepatobiliary-pan-cancer-op","name":"胰腺癌手术与功能支持","cues":"胰头或体尾部肿瘤拟切除","content":"胰头手术可能涉及胆道和消化道重建，体尾切除范围不同。术后按实际切除补消化酶/营养及血糖管理，并监测重建相关漏和排空障碍。","mechanism":"不同胰组织与消化通道改变，造成不同功能缺损。","numbers":"","avoid":"","source":"D20:P0204–P0223；NCI:胰腺癌"}],"question":"同有黄疸，胆管引流与胰头切除后需增加哪些不同护理？"},{"id":"hepatobiliary-drain-care","title":"胆道与胰腺管路：目的不同，记录不同","axis":"nursing","common":"所有管路先标识固定、防牵拉受压，再核对输出性质与患者症状。","rows":[{"id":"hepatobiliary-t-tube","name":"T管全程","cues":"胆管切开后有T管","content":"观察胆汁颜色、清浊和量的趋势，突然无引流或增多需联看扭曲、梗阻及症状。试夹、造影和拔除需结合通畅与愈合计划，移除后继续看漏液和腹部体征。","mechanism":"外引流减压也造成胆汁流失，通畅与恢复不能单按留置天数判断。","numbers":"","avoid":"不自行夹管、冲洗或按固定天数拔除。","source":"D20:P0158–P0166"},{"id":"hepatobiliary-double-tube","name":"腹腔灌洗双套管与空肠营养管","cues":"胰坏死处理后同时留多条管","content":"区分灌入、负压引出与营养输入，分别记录量和性质，维护有效引流及体液平衡。营养管关注固定、冲管、输注耐受，出现腹胀腹泻要联系配方、速度和病情。","mechanism":"双套管用于处理局部渗出/坏死，空肠管供给营养，方向及护理目标相反。","numbers":"","avoid":"不混用管路，也不自行提高吸引负压。","source":"D20:P0193–P0199"},{"id":"hepatobiliary-fistula","name":"胆瘘、胰瘘与胃肠瘘","cues":"引流改变并腹痛发热或皮肤浸渍","content":"胆汁样、清亮或含食物的液体可提示不同漏出，但需要酶学/影像和临床确认。保持既定引流、记录丢失、保护皮肤并配合营养及感染处理，不能只换敷料。","mechanism":"消化液刺激皮肤并引起水电解质/营养损失及腹腔污染。","numbers":"","avoid":"不能单凭颜色确诊或自行堵住外漏。","source":"D20:P0038–P0040,P0200–P0203,P0217–P0222"},{"id":"hepatobiliary-organ-follow","name":"肝脑、血糖与排空","cues":"术后性格行为改变、血糖波动或进食不耐受","content":"肝切除后行为改变需警惕脑病并查诱因，避免自行镇静掩盖进展。胰术后血糖与消化、胃排空分开观察，持续呕吐腹胀需评估而非强行加餐。","mechanism":"肝解毒储备、胰内外分泌与消化道动力是不同功能。","numbers":"","avoid":"","source":"D20:P0041–P0043,P0214–P0223"}],"question":"胆汁样液体外漏时，为什么需要同时写引流、皮肤与营养？"}],"drills":[{"id":"hepatobiliary-drill-cholangitis","title":"退热以后还缺哪一步","stem":"胆管结石患者出现腹痛、黄疸和寒战，后转为反应迟钝、四肢冷。退热后体温下降，但尿量仍少。","prompt":"列优先问题、治疗共性与胆道个性，并写出不能用的判断。","answer":["共性：连续评估意识、循环、尿量、氧合、电解质和凝血，及时报告器官恶化。","个性：感染梗阻背景提示严重胆管炎风险，需配合复苏/抗感染与及时解除梗阻引流。","护理问题联系感染性高热、体液/灌注风险和疼痛；按当前证据排序。","错用项：退热不等于感染源已控制，五联征不齐也不能排除重症。"],"source":"D20:P0167–P0183；M073:病例目标"},{"id":"hepatobiliary-drill-tubes","title":"联合手术后先认管","stem":"胰周坏死引流并胆道处理后，患者同时有腹腔灌洗管、T管和空肠营养管。交班时引流性状变化且管周皮肤潮红。","prompt":"按共性和管路个性组织护理，再列需要报告的改变。","answer":["共性：核对三种管路标识、入口/出口和医嘱，固定防折叠，分项记录液体。","个性：T管看胆汁及胆道通畅；灌洗系统核对灌入引出与负压；空肠管核对营养配方、速度及耐受。","联系腹痛、发热、循环、酶学与液体性质评价瘘或感染，维护引流并保护皮肤。","错用项：不能把所有管接同一种负压，也不能仅因颜色变化自行认定瘘。"],"source":"D20:P0193–P0203,P0227；M074:病例目标"},{"id":"hepatobiliary-drill-liver","title":"肝占位：确诊与术前护理两条线","stem":"有慢性肝病的人出现肝区不适、进食减少和体重下降，影像见肝占位，AFP异常，团队拟进一步评估局部治疗。","prompt":"说明检查之间关系，并写术前共性、肝脏个性和介入后重点。","answer":["共性：评估营养、疼痛、心理及手术准备，记录基线功能。","个性：AFP需与影像和病史组合，同时查肝储备、凝血、液体状态；不能单凭标志物自行定治疗。","如选择TACE，增加穿刺点、肢端循环和栓塞反应观察；如切除，增加出血、胆漏、膈下积液及脑病。","错用项：不能把两种治疗的体位制动、引流和复查计划混为一个固定日程。"],"source":"D20:P0002–P0060；M072:病例目标"},{"id":"hepatobiliary-drill-pancreatic-cancer","title":"胰腺癌术后为什么还看血糖","stem":"胰腺切除重建后患者进食少、体重下降，血糖波动，腹腔引流持续异常；患者因反复治疗感到悲观。","prompt":"把共性护理与胰腺内外分泌、漏和心理问题分别列出。","answer":["共性：评价营养液体、疼痛、伤口引流及感染/出血，与患者讨论可完成的生活目标。","个性：胰组织减少可能影响血糖与消化，需要按计划监测血糖、消化耐受及相关支持，不能只增加饭量。","异常引流需结合酶学/影像、腹痛发热确认是否胰胆或胃肠漏，维护既定引流及皮肤并补营养。","错用项：不能把所有清亮引流直接叫胰瘘，不能忽略悲观和身体形象对自护的影响。"],"source":"D20:P0204–P0227；PDF26:胰腺癌；NCI:胰腺癌"}],"references":[{"title":"NICE：胆石症检查与管理","url":"https://www.nice.org.uk/guidance/cg188/chapter/recommendations"},{"title":"NICE：胰腺炎与营养","url":"https://www.nice.org.uk/guidance/ng104/chapter/recommendations"},{"title":"NCI：肝癌治疗","url":"https://www.cancer.gov/types/liver/what-is-liver-cancer/treatment"},{"title":"NCI：胰腺癌治疗","url":"https://www.cancer.gov/types/pancreatic/treatment"}]},"acute-abdomen":{"title":"急腹症：损伤、腹膜炎、梗阻与阑尾炎","intro":"把痛、吐、胀、排便排气和腹膜体征串成变化过程，再用失血、污染、缺血和特殊人群四条分支补个性。","framework":[{"id":"acute-abdomen-f-dynamic","title":"腹痛必须写出变化","cue":"急腹症初诊或病情转变","answer":"记录起始部位、转移放射、持续/阵发、间歇和范围，并比较腹膜刺激征。阵发痛转持续、暂缓后加重或范围扩展，都要联系新的缺血、穿孔或污染。","why":"不同结构受刺激产生不同痛型，镇痛后的主观改善也需客观复评。","source":"D21:P0003–P0013,P0167–P0175,P0278–P0299"},{"id":"acute-abdomen-f-loss","title":"液体损失不只在袋里","cue":"呕吐、梗阻、腹膜炎或创伤","answer":"把吐出/减压损失、腹腔肠腔渗出、出血和摄入不足分项记。用灌注、尿量、体重、血象及电解质/血气联系补液营养，不只写禁食补液四个字。","why":"第三间隙可造成有效循环不足，即使没有明显外流也会低灌注。","source":"D21:P0072–P0093,P0128–P0129,P0254–P0255"},{"id":"acute-abdomen-f-branch","title":"先判出血、感染还是肠缺血","cue":"低灌注、腹膜刺激或血性排出","answer":"实质脏器伤重点找出血和延迟出血，空腔伤重点找漏出污染，梗阻重点找血运障碍。三者可并存，出现持续恶化时及时报告并准备病因处理。","why":"不同病因都可休克，但止血、污染控制和解除缺血的重点不同。","source":"D21:P0016–P0071,P0256–P0265"},{"id":"acute-abdomen-f-tubes","title":"减压与腹腔引流分开记录","cue":"留置胃管或腹腔管","answer":"胃管写减压效果、固定通畅与呕吐误吸，腹腔管写渗血/胆汁/粪性液体及伤口。两者都看色质量和患者变化，突然少出伴腹胀发热需排查堵塞而非认定好转。","why":"胃管减少腔内积聚，腹腔管处理腔外液体，异常意义不同。","source":"D21:P0126–P0127,P0148–P0154,P0252–P0255"},{"id":"acute-abdomen-f-pe","title":"同一共性问题，相关因素不同","cue":"列护理诊断与并发症","answer":"疼痛分别联系创伤、腹膜炎、蠕动增强/缺血或阑尾炎症；体液不足分别联系出血、渗出或呕吐。营养、体温、焦虑恐惧及活动能力按证据补充，再分列脓肿、休克、肠瘘或再梗阻。","why":"用病因解释护理问题，才能把措施与目的对应起来。","source":"PDF28:PDF页1；D21:P0160–P0166,P0274–P0277,P0319–P0322"}],"contrasts":[{"id":"acute-abdomen-injury","title":"腹部损伤：实质与空腔共同评估、分别作答","axis":"diagnosis","common":"外伤史、连续灌注与腹部检查缺一不可，初次阴性不能覆盖之后变化。","rows":[{"id":"acute-abdomen-solid","name":"实质性脏器出血","cues":"外伤后面白、脉快、尿少或肩部牵涉痛","content":"肝脾等损伤以出血风险为主，腹痛和腹膜刺激可相对不突出。追踪血象、灌注和腹部液体，稳定后仍警惕迟发恶化。","mechanism":"腹腔内血液丢失导致循环不足，包膜下损伤可延迟破裂。","numbers":"","avoid":"","source":"D21:P0016–P0061"},{"id":"acute-abdomen-hollow","name":"空腔脏器漏出","cues":"持续剧痛、腹膜刺激、游离气或食物样腹穿液","content":"胃肠内容物漏出引起化学刺激与感染，腹膜炎可逐渐扩展。需将禁食/减压、抗感染和污染控制与循环支持并行考虑。","mechanism":"不同消化液和细菌负荷导致刺激强度及发生时间不同。","numbers":"","avoid":"没有游离气也不能单独排除肠损伤。","source":"D21:P0023–P0045,P0065–P0070"},{"id":"acute-abdomen-organ","name":"肝、脾、胰与肠的定位线索","cues":"已有腹部损伤但部位未明","content":"左上腹/左肩联系脾，右上腹/右肩联系肝；胰伤看上腹与酶及影像。肠/直肠伤看腹膜炎时序、直肠/会阴或瘘的线索，部位只作定位而非单征定诊。","mechanism":"相邻器官、膈肌牵涉及腹膜内外位置影响症状。","numbers":"","avoid":"","source":"D21:P0052–P0071"}],"question":"外伤后第一次腹穿阴性，为什么仍要追踪？"},{"id":"acute-abdomen-peritonitis","title":"腹膜炎与腹腔压力：局部体征连全身","axis":"diagnosis","common":"痛、腹膜刺激和全身反应相互印证，不以一个痛点决定病情。","rows":[{"id":"acute-abdomen-peritonitis-pattern","name":"急性化脓性腹膜炎","cues":"持续腹痛、腹胀，移动或咳嗽加重","content":"视腹式呼吸、触压痛反跳肌紧张、叩浊音/游离气线索、听肠鸣音并结合直肠检查。老幼衰弱者体征可轻，脉快而体温下降等变化反而需警惕。","mechanism":"炎症刺激使患者限制腹部运动，肠麻痹加重腹胀。","numbers":"","avoid":"","source":"D21:P0002–P0013"},{"id":"acute-abdomen-acs","name":"腹腔间隔室风险","cues":"腹部张力明显增加并呼吸、尿量或循环恶化","content":"不能只把腹胀视作舒适问题，需及时报告并配合腹内压及器官功能评估。记录腹围/张力、呼吸、尿量和循环趋势，按团队计划处理病因与减压。","mechanism":"高腹内压影响静脉回流、肾灌注和膈肌活动。","numbers":"","avoid":"仅凭腹胀外观不能确诊ACS，也不能只加减压药等待。","source":"D21:P0014–P0015；PDF28:PDF页1"}],"question":"腹胀如何从局部症状变成器官危险？"},{"id":"acute-abdomen-obstruction","title":"肠梗阻：七类用同一组维度比较","axis":"diagnosis","common":"每类都按痛、吐、胀、排出物、肠鸣与血运列出差异。","rows":[{"id":"acute-abdomen-mechanical","name":"单纯机械性","cues":"阵发绞痛伴呕吐、腹胀和排气便减少","content":"肠型/蠕动波及肠鸣亢进可支持机械阻力，单纯型无明确血运障碍。部分梗阻仍可有少量排便，必须结合病程。","mechanism":"阻力近端肠蠕动增强，积气积液产生症状。","numbers":"","avoid":"","source":"D21:P0167–P0195"},{"id":"acute-abdomen-strangulated","name":"绞窄性","cues":"持续剧痛、血性排出或腹膜刺激及灌注恶化","content":"比较痛型由阵发转持续、局部不对称胀、血性吐/引流/便、发热脉快及影像。任何恶化组合需重评缺血和手术，不等九项警报全部出现。","mechanism":"肠壁血供受损可造成坏死、出血和全身毒血症。","numbers":"","avoid":"","source":"D21:P0196–P0204,P0256–P0265"},{"id":"acute-abdomen-high-low","name":"高位与低位","cues":"已判断机械性梗阻，需定位和解释失衡","content":"高位呕吐常早而频繁、腹胀相对轻，重视上消化液丢失；低位呕吐可较晚、腹胀明显。电解质酸碱要据化验解释，不能仅按部位机械定代酸或代碱。","mechanism":"梗阻近端长度和积聚容量不同，影响吐胀顺序。","numbers":"","avoid":"","source":"D21:P0205–P0222"},{"id":"acute-abdomen-ileus","name":"麻痹性","cues":"术后炎症/代谢背景，全腹均匀胀而肠鸣弱","content":"可呈持续胀痛和溢出性呕吐，缺乏明确蠕动波。寻找炎症、电解质或药物等背景，仍需排除机械和缺血因素。","mechanism":"推进运动下降使肠内容物停留，不是固定堵塞点造成。","numbers":"","avoid":"","source":"D21:P0223–P0231"},{"id":"acute-abdomen-volvulus","name":"肠扭转与闭袢","cues":"突发剧痛，不对称腹胀或孤立扩张肠袢","content":"闭袢可能同时影响进出及血运，早期需警惕绞窄。结合影像与全身变化评估，不因尚有肠鸣或早期化验正常而等待。","mechanism":"扭转可扭曲肠系膜血管，进展快。","numbers":"","avoid":"","source":"D21:P0232–P0240"},{"id":"acute-abdomen-roundworm","name":"蛔虫性堵塞","cues":"脐周阵发痛，虫体/虫卵线索或条索样团块","content":"常需结合流行病学、排出物与影像判断，不能凭腹痛即驱虫。先评估梗阻程度和危险，再按专业方案处理。","mechanism":"虫团形成机械阻力，可能仍是不完全性。","numbers":"","avoid":"","source":"D21:P0241–P0249"}],"question":"有少量排便、肠鸣存在是否能排除梗阻或缺血？"},{"id":"acute-abdomen-appendicitis","title":"阑尾炎：病理进展与人群差异","axis":"diagnosis","common":"典型转移痛帮助识别，不典型位置和体征需要主动补问。","rows":[{"id":"acute-abdomen-appendix-stage","name":"单纯、化脓、坏疽与穿孔","cues":"转移性右下腹痛或腹痛范围变化","content":"由轻痛到持续加重联系炎症进展，穿孔后可暂缓又加重扩展。发热、腹膜刺激、脓肿及门静脉炎线索决定进一步检查和治疗评估。","mechanism":"腔内压力下降可短暂减痛，但漏出使炎症继续扩散。","numbers":"","avoid":"","source":"D21:P0278–P0294"},{"id":"acute-abdomen-appendix-person","name":"新生儿、小儿、妊娠与老年","cues":"右下腹表现不典型或病情与体征不相称","content":"小儿可全身症状突出、进展快，老年可能症状轻而病理重。妊娠时压痛位置及腹膜体征可改变，需结合产科与影像安全评估。","mechanism":"反应能力、解剖位置和炎症包裹能力不同。","numbers":"","avoid":"不把无转移痛或无强肌紧张作为排除条件。","source":"D21:P0295–P0299"}],"question":"穿孔时痛短暂减轻，为何不能判好转？"},{"id":"acute-abdomen-investigate","title":"检查结果要解释，不只报名称","axis":"labs","common":"炎症、出血、失衡、位置与内容物五类证据分别组织。","rows":[{"id":"acute-abdomen-blood-imaging","name":"血液及影像","cues":"腹痛伴出血、感染或梗阻疑虑","content":"血象追踪失血/炎症，电解质血气评价失衡，淀粉酶需结合病因而非独立确诊。超声/CT和平片按问题选用，分别看积液、脏器损伤、游离气及扩张肠袢。","mechanism":"不同检查回答性质、部位和严重度的不同部分。","numbers":"","avoid":"","source":"D21:P0072–P0093,P0185–P0249"},{"id":"acute-abdomen-aspirate","name":"腹穿液性质","cues":"已由专业团队决定诊断性腹穿","content":"不凝血支持腹腔内出血方向，混食物/胆汁或粪性液体提示不同漏出污染。血性液也可与绞窄或胰病有关，阴性结果不能独立排除病变。","mechanism":"腹腔液体成分反映漏出来源，但取样部位与时机影响结果。","numbers":"","avoid":"不能只凭颜色确诊，也不将空穿刺结果作为停止观察理由。","source":"D21:P0094–P0112"}],"question":"抽出血液、食物样液体或无液体，分别改变什么判断？"},{"id":"acute-abdomen-treat","title":"稳定支持与病因处理并行","axis":"treatment","common":"先保生命、纠正失衡、控制疼痛，再根据出血、污染或缺血升级。","rows":[{"id":"acute-abdomen-support","name":"减压、液体与镇痛","cues":"腹胀呕吐或急腹症待评估","content":"按病情安排经口限制、胃肠减压、液体电解质和营养，观察误吸及疗效。评估和医嘱下合理镇痛并持续复评，不能因疼痛缓解而停止诊断。","mechanism":"减压缓解腔内积聚，补液纠正灌注，但都不等于消除病因。","numbers":"","avoid":"不使用泻药或灌肠自行通梗阻；也不传播未确诊一律不得镇痛。","source":"D21:P0119–P0135,P0250–P0255,P0300–P0305"},{"id":"acute-abdomen-upgrade","name":"需要紧急升级的分支","cues":"出血/腹膜炎/绞窄或保守无改善","content":"出血重点为止血与循环支持，污染重点为感染源控制，绞窄重点为恢复血运并处理坏死。立即报告恶化并准备相应治疗，不机械沿用稳定保守模板。","mechanism":"支持治疗可能暂时改善数字而病因仍继续损伤。","numbers":"","avoid":"","source":"D21:P0043–P0045,P0113–P0118,P0256–P0266；WSES:梗阻"},{"id":"acute-abdomen-appendix-treat","name":"阑尾炎保守与手术","cues":"已诊断阑尾炎需选择方案","content":"非手术与手术依类型、并发症和团队计划决定，保守期持续看腹痛范围、发热和体征。脓肿、穿孔或恶化需重评并准备干预，不能只重复抗菌药观察。","mechanism":"局限炎症与广泛污染、脓肿的处理目标不同。","numbers":"","avoid":"","source":"D21:P0300–P0309；WSES:阑尾炎"}],"question":"什么证据会让稳定梗阻的护理计划立即改变？"},{"id":"acute-abdomen-aftercare","title":"术后护理：同是腹部手术，异常分支不同","axis":"nursing","common":"呼吸、液体营养、管路、伤口和安全活动共用框架；再加原器官与术式风险。","rows":[{"id":"acute-abdomen-wound-drain","name":"引流与腹膜变化","cues":"术后新发疼痛发热或引流异常","content":"鲜红引流增多伴低灌注警惕再出血，胆汁/粪性引流需评估漏出，骤少伴胀热需查堵塞。保持标识固定与既定通畅，记录并报告而非自行拔除。","mechanism":"术后腔外液体及其排出变化反映出血、污染和引流有效性。","numbers":"","avoid":"","source":"D21:P0136–P0157,P0270–P0272"},{"id":"acute-abdomen-recovery","name":"营养、活动与再梗阻","cues":"病情稳定进入恢复","content":"按术式和耐受推进经口/肠内营养，联系恶心、腹胀和肠功能。镇痛支持呼吸与循序活动，出院教患者识别腹痛腹胀、呕吐及停止排气等复发信号。","mechanism":"过度制动增加失用与血栓，强行进食又可掩盖不耐受。","numbers":"","avoid":"不把固定术后天数或单一排气作为所有人的唯一饮食标准。","source":"D21:P0142–P0159,P0267–P0273,P0310–P0312"},{"id":"acute-abdomen-appendix-after","name":"阑尾术后并发症与连续判断","cues":"术后腹痛发热、里急后重或伤口异常","content":"伤口红肿脓性渗出联系切口感染，持续腹痛发热及里急后重黏液便需评估盆腔脓肿。再列出血、粘连梗阻、残株炎和肠瘘，用症状与检查区别而非都称正常恢复。","mechanism":"感染位置和残留炎症部位不同，表现可偏直肠刺激或切口。","numbers":"","avoid":"","source":"D21:P0313–P0322"}],"question":"术后里急后重与伤口红肿分别提示哪条观察路线？"}],"drills":[{"id":"acute-abdomen-drill-delay","title":"第一次没抽到，不等于之后没危险","stem":"患者左上腹受撞击后初查未见明确腹腔出血，观察中后来突然头晕、面白、肢冷并出现腹痛加重。","prompt":"写首要重评、共性护理和损伤个性，并说明初查结果怎样使用。","answer":["共性：立即报告并连续评估意识、血压脉搏、尿量、腹部体征和血象，配合循环支持。","个性：外伤位置及延迟恶化需警惕实质脏器迟发出血，准备进一步影像/止血评估，同时不能忽视合并空腔伤。","记录变化时刻和已给液体/反应，以动态而非一次结果判断。","错用项：初次阴性腹穿或影像不能排除后续出血，不因之前腹痛可忍就继续放任活动。"],"source":"D21:P0016–P0071,P0113–P0166；M075:病例目标"},{"id":"acute-abdomen-drill-bowel","title":"同一梗阻计划，何时必须改","stem":"既往腹部手术患者阵发腹痛、呕吐和腹胀，原在接受非手术处理；现痛持续不缓、引流带血且手足变凉。","prompt":"列共性支持、个性危险和应升级事项。","answer":["共性：复核减压效果、损失量、电解质与灌注，防误吸并按医嘱支持。","个性：持续痛、血性引流和低灌注组合需重评肠绞窄/缺血，立即报告并准备病因处理和手术评估。","继续比较腹膜体征、血象、影像及尿量，记录镇痛后的客观变化。","错用项：不能仅加镇痛或继续等排便；仍有少量便也不能否定梗阻。"],"source":"D21:P0167–P0277；M077:病例目标"},{"id":"acute-abdomen-drill-appendix","title":"阑尾术后两次交班","stem":"阑尾术后患者因切口痛不敢活动；数日后新发下腹痛、发热、里急后重和多次黏液便。","prompt":"分别列前后护理重点，说明哪些共性保留、哪些个性新增。","answer":["前期共性：评估疼痛与稳定度，按计划镇痛并指导呼吸和渐进活动，同时观察伤口、进食与腹胀。","后期个性：直肠刺激表现伴发热需评估盆腔脓肿等感染，及时报告并配合检查和可能引流。","护理问题前期可为急性疼痛、活动受限；后期增加体温及感染相关协同问题，均需对应证据。","错用项：不能将新症状仍按不愿下床或普通恢复解释，也不能用灌肠自行处理。"],"source":"D21:P0300–P0322；M078:病例目标"},{"id":"acute-abdomen-drill-perforation","title":"出血与污染同时看","stem":"腹部外伤后患者全腹剧痛和腹膜刺激征明显，影像提示游离气，采集液体中可见消化道内容物，并伴低灌注。","prompt":"解释诊断证据，按共性与空腔损伤个性组织急诊护理。","answer":["共性：优先评估气道呼吸循环，建立并维护通路，记录灌注、尿量和损失并配合复苏。","个性：游离气及内容物支持空腔漏出污染方向，配合经口限制、减压、抗感染及及时污染控制/手术准备。","持续观察腹膜体征和器官状态，关注出血与感染可同时存在。","错用项：不能因为有腹膜炎就忽略失血，也不能仅靠退热和补液替代病因处理。"],"source":"D21:P0016–P0159；M064/M076:病例目标"}],"references":[{"title":"WSES：腹部急症指南入口","url":"https://www.wses.org.uk/scientific-resources/guidelines"},{"title":"NICE：重大创伤初始评估","url":"https://www.nice.org.uk/guidance/ng39/chapter/Recommendations"},{"title":"NICE：成人静脉液体治疗","url":"https://www.nice.org.uk/guidance/cg174/chapter/recommendations"}]},"gi-surgery":{"title":"食管、胃十二指肠与大肠手术","intro":"先背消化道手术共性：营养液体、呼吸镇痛、减压引流、吻合口与生活自护。再用重建位置、保肛与否和食物通过方式补差异。","framework":[{"id":"gi-surgery-f-nutrition","title":"营养问题从入口、消耗、吸收三处找","cue":"吞咽困难、消瘦、梗阻或消化道手术","answer":"食管病先看吃不进，胃肠病再看呕吐、出血和吸收，肿瘤与手术增加消耗。评估营养及水电解质风险，依据术式和耐受安排经口、肠内或肠外，不能只写高蛋白饮食。","why":"入口受限、消化道连续性和胃容量改变使营养途径与节奏不同。","source":"D22:P0084–P0116,P0134–P0149,P0164–P0181"},{"id":"gi-surgery-f-anastomosis","title":"吻合口护理先背三个目标","cue":"食管胃、胃肠或肠肠吻合后","answer":"维持有效减压及引流、支持组织营养灌注、及早识别漏与感染。观察胸腹痛、发热、呼吸循环和引流变化，异常时及时报告并按计划调整经口摄入。","why":"张力、血供、局部污染和营养共同影响愈合。","source":"D22:P0096–P0129,P0150–P0155,P0182–P0184"},{"id":"gi-surgery-f-breath","title":"疼痛、呼吸和活动一起答","cue":"胸腹切口痛，不敢咳嗽或活动","answer":"先评估镇痛效果，再指导有效咳嗽、呼吸练习及按耐受活动。维护相关管路并观察氧合、痰液和肺部变化，活动要服务呼吸与恢复而非只完成次数。","why":"切口痛抑制深呼吸和移动，分泌物滞留与制动增加并发症。","source":"D22:P0102–P0105,P0147,P0180"},{"id":"gi-surgery-f-stoma","title":"造口护理从活力到生活能力","cue":"有肠造口或拟造口","answer":"共背颜色活力、形态高度、排出与周围皮肤四项，换袋按揭、清、测、剪、贴、密封顺序。再把饮食、渗漏、心理、自我形象及外出生活纳入训练，请患者回演。","why":"适配尺寸随造口恢复改变，皮肤受损又会加重渗漏。","source":"D22:P0173,P0185–P0215"},{"id":"gi-surgery-f-pe","title":"按部位补护理诊断的原因","cue":"术前或术后需列问题","answer":"食管癌营养和体液不足联系吞咽受限；胃病联系摄入、出血、呕吐与术后容量变化。大肠造口补身体意象及知识/自护问题，焦虑要连其担忧；瘘、乳糜胸、残端破裂等作为并发症。","why":"同一营养失调有不同造成路径，治疗与宣教要对症。","source":"PDF30:PDF页1；D22:P0082–P0083,P0130–P0133,P0159–P0162,P0213–P0215"}],"contrasts":[{"id":"gi-surgery-cancer-pattern","title":"癌症部位：入口、排空和排便线索","axis":"diagnosis","common":"把早期线索、进展症状与确诊方法分开，不能等典型晚期表现才评估。","rows":[{"id":"gi-surgery-esophagus","name":"食管癌","cues":"哽噎、胸骨后不适进展为吞咽困难","content":"先描述固体到半流质受限的过程与体重、进水量。晚期胸背痛、声嘶或呛咳等还需评估侵犯和瘘，不用症状单独定分期。","mechanism":"管腔狭窄影响食物通过，邻近侵犯产生额外表现。","numbers":"","avoid":"","source":"D22:P0005–P0009,P0084–P0091"},{"id":"gi-surgery-stomach","name":"胃癌","cues":"上腹不适、消瘦、贫血或出血线索","content":"早期可无特异表现，贲门处可有哽噎，近幽门可有潴留呕吐。病变位置与进食通过问题相连，需胃镜取样评价。","mechanism":"不同胃区影响入口、储存或出口，症状不完全一样。","numbers":"","avoid":"","source":"D22:P0010–P0013"},{"id":"gi-surgery-colon","name":"右、左半结肠癌","cues":"排便习惯改变、血便、贫血或包块","content":"右侧常以贫血消耗和包块线索突出，左侧更需关注狭窄梗阻及排便改变。仍需结合检查，不能按左右口诀排除不典型。","mechanism":"肠腔、内容物和肿瘤生长方式影响表现。","numbers":"","avoid":"","source":"D22:P0014–P0017"},{"id":"gi-surgery-rectum","name":"直肠癌","cues":"黏液血便、里急后重、便细或排不净","content":"直肠刺激与狭窄分组，指检及肠镜病理重要。局部侵犯可出现泌尿、阴道或骶前疼痛等表现，不能长期只按痔疮。","mechanism":"直肠储排功能和邻近器官关系决定症状。","numbers":"","avoid":"","source":"D22:P0018–P0021"}],"question":"为什么排便习惯改变与贫血都可能指向大肠病变？"},{"id":"gi-surgery-ulcer","title":"溃疡及三种并发症","axis":"diagnosis","common":"把原有节律性痛与新出现的穿孔、出血或出口梗阻分开。","rows":[{"id":"gi-surgery-ulcer-simple","name":"胃与十二指肠溃疡","cues":"反复上腹痛与进食节律有关","content":"胃溃疡常偏餐后痛，十二指肠溃疡常见空腹/夜间痛或进食暂缓。胃镜与幽门螺杆菌检查帮助确定病变及病因，节律不典型也不能排除。","mechanism":"酸相关损伤及病变部位影响症状节律。","numbers":"","avoid":"","source":"D22:P0022–P0025"},{"id":"gi-surgery-ulcer-perf","name":"急性穿孔","cues":"突发剧痛、板状腹或游离气","content":"联系腹膜刺激和漏出污染，立即评估全身状态并准备专业处理。影像及腹腔液体帮助诊断，支持治疗与污染控制并行。","mechanism":"消化液进入腹腔引起化学及感染性腹膜炎。","numbers":"","avoid":"不自行进食、灌肠或等待痛完全不能忍才就医。","source":"D22:P0026–P0031；WSES:溃疡急症"},{"id":"gi-surgery-ulcer-bleed","name":"大出血","cues":"呕血黑便伴乏力、脉快或低灌注","content":"评估气道、循环、血象及持续出血，配合复苏和止血定位。内镜、介入或手术按情况选择，不能用一次血红蛋白或固定出血量独断严重度。","mechanism":"急性失血可在血象尚未充分变化时已影响循环。","numbers":"","avoid":"","source":"D22:P0032–P0035；WSES:溃疡急症"},{"id":"gi-surgery-pylorus","name":"瘢痕性幽门梗阻","cues":"反复大量宿食样呕吐，吐后暂轻","content":"看潴留、营养和水电解质损失，结合内镜/影像评价出口。术前减压和纠正失衡针对潴留风险，不能把所有呕吐都归为普通消化不良。","mechanism":"胃排空受阻使前次食物潴留，胃酸丢失可影响酸碱。","numbers":"","avoid":"","source":"D22:P0036–P0039,P0141"}],"question":"原有空腹痛变为宿食呕吐时，护理重点如何改变？"},{"id":"gi-surgery-investigate","title":"检查：筛查、确诊与并发症评价","axis":"labs","common":"先区分要找肿瘤、出血、梗阻还是术后漏。","rows":[{"id":"gi-surgery-scope","name":"内镜、病理与隐血","cues":"疑食管胃肠肿瘤或慢性出血","content":"内镜看病变并取样，病理用于明确性质；隐血用于出血/筛查线索。直肠指检可获取低位病变资料，但阴性不能排除更高位置病变。","mechanism":"筛查线索不等于病理确诊，取样又需选对部位。","numbers":"","avoid":"隐血阳性不等于癌，阴性也不是所有肿瘤的排除。","source":"D22:P0007–P0024"},{"id":"gi-surgery-post-tests","name":"术后检查与造口评估","cues":"发热、气促、异常引流或造口改变","content":"血象、生化、相关液体及影像围绕疑出血、感染或漏来安排。造口另看颜色活力、形态、排出与皮肤，不能以袋里有便替代局部评估。","mechanism":"局部变化与全身反应联合才能评价并发症。","numbers":"","avoid":"","source":"D22:P0094–P0129,P0150–P0158,P0185–P0203"}],"question":"为什么术后白细胞高不能单独证明吻合口瘘？"},{"id":"gi-surgery-operations","title":"术式比较：食物怎么走、粪便从哪出","axis":"treatment","common":"先画重建路线，再回答术后风险与护理差异，不把手术名只当缩写。","rows":[{"id":"gi-surgery-billroth","name":"毕Ⅰ与毕Ⅱ","cues":"胃大部切除需比较重建","content":"毕Ⅰ为残胃接十二指肠，毕Ⅱ为残胃接空肠并关闭十二指肠残端。二者都减少胃容量和产酸相关组织，但毕Ⅱ增加输入输出袢及残端相关观察。","mechanism":"通路改建影响胆胰液与食物混合和排空。","numbers":"","avoid":"术式选择结合病变、张力及重建条件，不能只按胃/十二指肠病名绝对指定。","source":"D22:P0042–P0060,P0150–P0158"},{"id":"gi-surgery-rectal-ops","name":"Miles、Dixon与Hartmann","cues":"直肠癌拟手术或需解释造口","content":"Miles切除涉及肛门，需永久性造口；Dixon保留肛门并重建连续性。Hartmann封闭远端并使近端造口，后续是否恢复另评估；原位肛门存在不代表仍能正常排便。","mechanism":"肿瘤位置、括约肌受累、耐受与急诊风险共同影响重建。","numbers":"","avoid":"不能仅凭一个距离阈值判断保肛，也不把Hartmann一律称永远无法恢复。","source":"D22:P0061–P0081"},{"id":"gi-surgery-esoph-rebuild","name":"胃代食管与结肠代食管","cues":"食管切除后需重建","content":"胃或结肠被用于恢复通路，术后需维护减压、呼吸及吻合口。结肠代食管增加肠段相关准备和通畅/存活观察，反流与进食后胸闷需结合重建理解。","mechanism":"重建器官的位置与运动方向改变食物通过和胸腔空间。","numbers":"","avoid":"","source":"D22:P0009,P0087–P0116"},{"id":"gi-surgery-nutrition-treatment","name":"术后营养途径","cues":"吞咽/胃容量或吻合风险改变","content":"能否经口与何时推进依据术式、耐受和并发症风险，不能全部固定禁食。经口受限时结合肠内/肠外计划支持，并记录腹胀、腹泻、呕吐和营养达成。","mechanism":"营养不足妨碍愈合，而过快推进可导致不耐受。","numbers":"","avoid":"","source":"D22:P0106–P0116,P0146,P0179"}],"question":"比较毕Ⅱ与Dixon：哪一个重点是输入袢，哪一个重点是盆腔吻合？"},{"id":"gi-surgery-complications","title":"术后并发症：按位置与内容物比较","axis":"nursing","common":"先看呼吸循环，再将液体来源、腹胸症状与进食关系连起来。","rows":[{"id":"gi-surgery-esoph-leak","name":"食管吻合口瘘、乳糜胸与出血","cues":"食管术后气促发热、引流改变或低灌注","content":"吻合瘘联系高热、胸部感染和引流异常；乳糜胸可在进食后出现乳糜样引流增多。鲜血增多合并循环变化需考虑出血，三种情况都需及时报告及相应检查处理。","mechanism":"吻合破坏、胸导管损伤与血管出血分别改变不同液体。","numbers":"","avoid":"乳白外观只能提示，不能仅凭颜色确诊；不按固定术后日数排除瘘。","source":"D22:P0117–P0129"},{"id":"gi-surgery-gastric-leak","name":"十二指肠残端、吻合口与胃排空","cues":"胃切除后右上腹剧痛、腹膜炎或持续潴留","content":"毕Ⅱ需想到十二指肠残端漏，吻合口问题则联系腹膜污染/脓肿。持续腹胀呕吐还需分胃排空障碍、吻合口或输入/输出袢梗阻，不能都叫胃瘫。","mechanism":"关闭残端及不同肠袢的解剖使异常内容物与部位不同。","numbers":"","avoid":"","source":"D22:P0150–P0155"},{"id":"gi-surgery-dumping","name":"早期与晚期倾倒","cues":"胃或食管手术后进餐相关不适","content":"早期多为餐后短时间出现心悸头晕、腹泻等，联系快速排空及液体转移。晚期更需联系反应性低血糖，比较时间、症状与血糖，饮食采用少量分餐并减少快速吸收糖。","mechanism":"早期渗透及体液变化与晚期胰岛素反应机制不同。","numbers":"早期常在餐后30分钟内；晚期常在餐后1–3小时，结合血糖判别。","avoid":"进食后平卧不适用于有明显反流/误吸风险的所有术式；不能把所有出汗心悸都判倾倒。","source":"D22:P0156–P0162；NIDDK:倾倒综合征"},{"id":"gi-surgery-colorectal-leak","name":"大肠吻合口与盆腔感染","cues":"术后新发腹痛、发热或异常引流","content":"联看腹膜刺激、循环、血象及引流，考虑吻合漏或局部感染并及时报告。维护既定引流，配合营养、抗感染与进一步处理，不把所有发热只看切口。","mechanism":"肠内容物污染可在深部而不先表现为表面伤口异常。","numbers":"","avoid":"","source":"D22:P0182–P0184"}],"question":"同样餐后不适，胃排空障碍与倾倒如何从时间、呕吐和血糖分开？"},{"id":"gi-surgery-stoma","title":"肠癌准备与造口生活训练","axis":"nursing","common":"准备须适合病情，护理需让患者会观察、会操作、会求助。","rows":[{"id":"gi-surgery-bowel-prep","name":"肠道准备与定位","cues":"拟行大肠手术/造口","content":"营养、肠道准备及药物按手术方案进行，梗阻和衰弱者需另评估。造口定位考虑站坐卧、皱褶、瘢痕、腹直肌与患者可见可触及程度，纳入患者参与。","mechanism":"准备可减少特定风险，但压力、脱水及不合适位置会增加伤害。","numbers":"","avoid":"直肠癌合并梗阻不自行高压灌肠，不能人人同一泻药量。","source":"D22:P0164–P0175"},{"id":"gi-surgery-bag","name":"换袋与尺寸适配","cues":"更换造口装置","content":"一手保护皮肤轻柔揭除，清洁后测量并按现状裁剪，贴合密封后检查渗漏。观察颜色、形态、排出和皮肤，随水肿消退复测，不能长期沿用一次模板。","mechanism":"底盘过大刺激皮肤，过紧可能损伤黏膜，渗漏又影响粘贴。","numbers":"","avoid":"","source":"D22:P0185–P0196"},{"id":"gi-surgery-stoma-danger","name":"造口异常与居家饮食","cues":"发暗、出血、回缩、脱垂或排出异常","content":"颜色发暗/黑变、多量出血、明显回缩或不排出伴腹痛需及时就医。饮食分阶段调整，观察产气、纤维耐受和水分，鼓励患者掌握换袋、外出用品及心理适应。","mechanism":"造口血供、开口和粘贴状态影响排出，改变饮食也改变气体和粪便。","numbers":"","avoid":"不自行涂止血粉或按坏死比例决定保守/手术；不同类型造口不套同一饮食限制。","source":"D22:P0197–P0220"}],"question":"造口袋换得会，还需证明哪些居家能力？"}],"drills":[{"id":"gi-surgery-drill-esophagus","title":"吞咽困难的术前共性与重建个性","stem":"患者吞咽逐渐受限、进食和饮水下降，影像提示食管病变，拟进一步取样并评估重建手术。","prompt":"写检查目的及术前重点；若改用结肠重建，应增加哪些思考？","answer":["共性：评估营养、水电解质、呼吸功能、疼痛和心理，记录体重与摄入变化。","内镜取样明确性质，分期及功能检查决定治疗耐受，不能只凭哽噎就确定癌的全部分期。","个性：食管阻塞增加误吸与插管困难，减压管不能强行进入；结肠重建增加肠段准备与术后肠段存活通畅观察。","错用项：不能将胃代与结肠代护理完全互抄，也不把进食受限只答为鼓励多吃。"],"source":"D22:P0005–P0009,P0084–P0133；M079:病例目标"},{"id":"gi-surgery-drill-dumping","title":"毕Ⅱ后的甜饮料不适","stem":"胃大部切除毕Ⅱ重建后，患者喝甜饮不久出现头晕、心悸、出汗和腹泻；另一次相似不适发生较晚，血糖偏低。","prompt":"解释两次可能机制、护理共性及不能套用项。","answer":["共性：评估循环、意识、症状与进餐时间，排除其他危险，必要时核对血糖。","第一次联系快速排空及体液转移的早期倾倒方向；第二次联系胰岛素反应相关低血糖，不仅看出汗命名。","个性：少量分餐、减少快速吸收糖并调整营养，记录诱因和效果；晚期按低血糖方案处理与教育。","错用项：不是所有餐后不适都是倾倒，若持续潴留呕吐仍需评估梗阻/排空；不能将所有患者饭后平卧。"],"source":"D22:P0042–P0060,P0150–P0162；M080:病例目标；NIDDK:倾倒"},{"id":"gi-surgery-drill-colon","title":"从排便改变到造口自护","stem":"患者长期排便习惯改变并有血便、消瘦，检查考虑大肠病变；术前担心造口，术后家属会换袋但患者始终不看造口。","prompt":"写诊断检查、术前共性与造口个性，并说明怎样验收学习效果。","answer":["诊断：结合部位症状安排指检、肠镜取样及相关分期，不能把隐血或影像单项当最终病理。","共性：营养、心理、围术期准备、伤口引流与循序活动；肠道准备需考虑梗阻和个体耐受。","个性：造口定位和生活方式共同讨论，分阶段支持身体意象，指导患者亲自观察、测量、换袋与辨渗漏。","验收：能演示并说清发暗、多量出血、腹痛不排出等求助信号；错用项是只要求家属记住换袋步骤。"],"source":"D22:P0014–P0021,P0163–P0220；M081:病例目标"},{"id":"gi-surgery-drill-ulcer","title":"旧溃疡，新梗阻","stem":"有反复上腹痛病史的人，近日改为餐后胀满并反复呕吐前次食物，进食减少且乏力。团队拟评价出口梗阻及营养液体状态。","prompt":"把原病、并发症与术前护理三层分开，再比较毕Ⅰ/毕Ⅱ重建路线。","answer":["原病节律和当前宿食呕吐属于不同信息，后者需评价胃排空/出口梗阻；内镜影像与化验分别明确病变和失衡。","共性：评估误吸、出入量、营养及电解质，按计划减压和纠正失衡。","个性：毕Ⅰ残胃接十二指肠，毕Ⅱ残胃接空肠并关闭十二指肠残端，后者术后增加残端和肠袢问题。","错用项：不能把大量呕吐仅答为普通消化不良，也不能无视潴留让患者继续加餐。"],"source":"D22:P0022–P0060,P0134–P0162；M080:术前目标"}],"references":[{"title":"NIDDK：倾倒综合征","url":"https://www.niddk.nih.gov/health-information/digestive-diseases/dumping-syndrome"},{"title":"WSES：溃疡穿孔出血与腹部急症","url":"https://www.wses.org.uk/scientific-resources/guidelines"},{"title":"NCI：癌症治疗方式","url":"https://www.cancer.gov/about-cancer/treatment/types"}]},"orthopedics":{"title":"骨折、关节脱位与椎间盘病变","intro":"共背生命危险、神经血管、固定有效、皮肤保护和分期功能。再按损伤部位、固定方式与神经受压位置补特有体征和禁忌。","framework":[{"id":"orthopedics-f-life","title":"先救生命，再保肢体","cue":"严重创伤、开放伤或多个部位损伤","answer":"先看气道呼吸、出血和循环，再保护伤口和患肢，配合影像与复位固定。搬运保持稳定与轴线，避免骨折端和脊柱再次损伤。","why":"股骨或骨盆等可大量失血，局部骨折之外仍有全身危险。","source":"D23:P0003–P0022,P0038–P0054"},{"id":"orthopedics-f-distal","title":"固定前后都查远端五组","cue":"骨折、复位、石膏或牵引后","answer":"比较疼痛、感觉、运动、肤色皮温/回填和脉搏，记录基线与之后变化。进行性加重痛或被动牵拉痛要及时报告，不能等脉搏消失才行动。","why":"外压与筋膜室压力可先损伤组织灌注，早期大动脉搏动仍存在。","source":"D23:P0021–P0022,P0057–P0058,P0068；BOASt2025"},{"id":"orthopedics-f-fixed","title":"固定有效与皮肤神经一起背","cue":"使用石膏、牵引或内固定","answer":"固定要维持位置和稳定，避免牵拉、局部压痕和随意改动。同步查皮肤受压、针眼及神经血管，区分治疗方式的特有风险而不是只写保持清洁。","why":"治疗本身既保护损伤，也可能因压迫、感染或过度牵引造成新伤。","source":"D23:P0061–P0100"},{"id":"orthopedics-f-rehab","title":"功能训练按目标递进","cue":"长期固定或术后康复","answer":"早期维护允许部位的肌肉收缩和未固定关节，中后期逐步增加关节活动、肌力与生活任务。负重、髋关节限制及脊柱支具需由稳定性、术式和康复计划决定。","why":"完全不动易失用，但过早或方向不当又可能破坏固定/重建。","source":"D23:P0101–P0111,P0179–P0182,P0211–P0222"},{"id":"orthopedics-f-pe","title":"把疼痛、移动、皮肤和体像连原因","cue":"需要列护理诊断","answer":"骨折痛联系损伤/痉挛，脱位痛联系关节组织和神经受压，腰椎痛联系神经根。移动障碍、皮肤风险和焦虑/体像按证据补充，休克、脂栓、筋膜室和血栓等另列协同监测。","why":"同为不能活动，骨性不稳定、关节脱位和神经压迫要求不同护理。","source":"M082/M084/M085:诊断导图；D23:P0048–P0049,P0203–P0204"}],"contrasts":[{"id":"orthopedics-fracture-signs","title":"骨折及早晚并发症","axis":"diagnosis","common":"局部体征、全身危险和后续制动风险分层回忆。","rows":[{"id":"orthopedics-fracture-local","name":"一般与特有体征","cues":"外伤后痛肿和活动受限","content":"痛、肿、功能下降为一般表现；畸形、异常活动和骨擦感为特有线索。结合影像判断，未出现特有体征也不能排除。","mechanism":"移位骨端改变形态和稳定性，软组织出血引起肿痛。","numbers":"","avoid":"不主动制造骨擦音或反常活动来验证。","source":"D23:P0003–P0015"},{"id":"orthopedics-early-comp","name":"早期：出血、脂栓与邻近损伤","cues":"严重骨折后循环或呼吸神经异常","content":"大骨折警惕失血，长骨损伤后新发呼吸/神经变化需评估脂肪栓塞等。合并内脏、动脉或脊髓损伤按部位主动寻找，不能全归为骨折痛。","mechanism":"骨髓脂肪进入循环、血管出血和局部断端损伤机制不同。","numbers":"","avoid":"","source":"D23:P0017–P0022"},{"id":"orthopedics-late-comp","name":"晚期：卧床、骨关节与缺血","cues":"固定和卧床进入恢复期","content":"卧床风险包括肺部感染、压力损伤及静脉血栓；局部还需记感染、关节僵硬、创伤性关节炎和异位骨化。骨不愈合/坏死、急性骨萎缩及缺血挛缩需结合持续痛、功能及影像随访。","mechanism":"制动、关节面不平、血供不足及感染分别影响不同结构。","numbers":"","avoid":"","source":"D23:P0023–P0033"}],"question":"有脉搏或没有畸形，为什么都不能直接判安全？"},{"id":"orthopedics-fracture-sites","title":"七类四肢骨折：部位决定危险","axis":"diagnosis","common":"每类按常见人群/畸形、血管神经、愈合风险及护理重点比较。","rows":[{"id":"orthopedics-humerus","name":"肱骨干与髁上","cues":"上臂或肘部骨折","content":"肱骨干尤其下段关注桡神经与垂腕；髁上骨折注意肱动脉和前臂缺血。复位固定前后都记录感觉、运动与循环，不能只检查骨折处。","mechanism":"神经血管与骨的毗邻关系使高危部位不同。","numbers":"","avoid":"","source":"D23:P0117–P0127"},{"id":"orthopedics-forearm","name":"尺桡双骨与桡骨远端","cues":"前臂畸形或老年跌倒撑地","content":"尺桡双骨折关注旋转对位、神经血管和筋膜室，孟氏/盖氏还伴邻近关节脱位。桡骨远端伸直型可见银叉样/枪刺样畸形，恢复需兼顾腕功能。","mechanism":"双骨旋转关系及腕端移位方向影响功能。","numbers":"","avoid":"","source":"D23:P0128–P0138"},{"id":"orthopedics-femur","name":"股骨颈与股骨干","cues":"髋部跌倒或强大外伤","content":"股骨颈特别注意血供、愈合和缺血坏死，嵌插型能暂时走路也不能排除。股骨干重点为大出血及远端神经血管，后续活动负重取决于固定与方案。","mechanism":"近端血供与长骨周围失血环境不同。","numbers":"","avoid":"","source":"D23:P0139–P0148"},{"id":"orthopedics-tibia","name":"胫腓骨干","cues":"小腿骨折或固定后剧痛","content":"近端关注血管神经，中段等部位注意筋膜室压力，下段血供及软组织条件影响愈合。开放伤与持续疼痛需动态看，不能只按骨折线位置估计风险。","mechanism":"小腿筋膜室空间有限，胫骨部分区域软组织覆盖与血供较差。","numbers":"","avoid":"","source":"D23:P0149–P0155"}],"question":"同样不能走，股骨颈和股骨干首先要额外想到什么？"},{"id":"orthopedics-dislocation","title":"肩、肘、髋脱位","axis":"diagnosis","common":"都可痛、畸形、弹性固定和活动受限，但姿态及神经血管风险不同。","rows":[{"id":"orthopedics-shoulder","name":"肩关节脱位","cues":"肩外伤后方肩、关节盂空虚","content":"Dugas征等可作线索，结合影像与神经血管检查。复位后按固定与康复计划逐步活动，注意再脱位和僵硬。","mechanism":"肱骨头离开关节盂使轮廓改变，周围软组织同时受损。","numbers":"","avoid":"不由学生或患者自行手法复位。","source":"D23:P0161–P0180"},{"id":"orthopedics-elbow","name":"肘关节脱位","cues":"肘部肿痛、肘后三角关系改变","content":"与髁上骨折时骨性关系区别，并查看肱动脉、正中/尺神经。复位后活动腕手与后续屈伸旋转须服从稳定性和固定计划。","mechanism":"关节位置改变可能牵压邻近神经血管。","numbers":"","avoid":"","source":"D23:P0164–P0181"},{"id":"orthopedics-hip-dislocation","name":"髋关节脱位","cues":"强大外伤后下肢姿态异常","content":"后脱位常见屈曲、内收内旋和短缩，前脱位方向不同。需急诊专业评价与复位，并警惕合并骨折、神经损伤及股骨头血供问题。","mechanism":"股骨头移位方向决定姿势，血管神经可被牵拉。","numbers":"","avoid":"髋脱位与髋置换术后防脱位不是同一病例。","source":"D23:P0165–P0182"}],"question":"肘后三角、方肩和内收内旋短缩分别引向什么？"},{"id":"orthopedics-spine-pattern","title":"腰椎神经根与危险改变","axis":"diagnosis","common":"腰痛需要联系放射路径、感觉运动及括约肌，而不只看疼痛评分。","rows":[{"id":"orthopedics-lumbar","name":"腰椎间盘突出","cues":"腰痛向下肢放射，咳嗽用力加重","content":"观察感觉、肌力、反射与直腿抬高相关表现，和影像结合判断。坐姿、用力方式与功能受限是教育入口，不以单一阳性体征确诊。","mechanism":"神经根受压/炎症产生相应放射痛和神经功能改变。","numbers":"","avoid":"","source":"D23:P0184–P0199"},{"id":"orthopedics-cauda","name":"马尾与进行性神经缺损","cues":"会阴感觉改变、大小便功能异常或肌力进展下降","content":"及时报告并转入紧急神经评估，不按普通慢性腰痛继续练习。记录发生时刻、感觉运动和排泄变化，与此前状态比较。","mechanism":"中央压迫可能累及多条神经及括约肌功能。","numbers":"","avoid":"不能仅给予热敷按摩或让患者在疼痛下强行锻炼。","source":"D23:P0189,P0201–P0202"}],"question":"出现会阴麻木后，原来的腰痛护理计划哪部分必须改变？"},{"id":"orthopedics-tests","title":"影像与床旁神经血管检查","axis":"labs","common":"骨性结构、软组织与实际功能相互补充。","rows":[{"id":"orthopedics-xray","name":"X线、CT与MRI","cues":"需明确骨折、移位或脊柱神经问题","content":"X线用于骨折及复位固定评价，复杂骨性结构可需CT。MRI更适合特定软组织、椎管和神经问题，检查选择按损伤疑点而非全套。","mechanism":"不同成像方式对骨和软组织的显示能力不同。","numbers":"","avoid":"","source":"D23:P0034–P0037,P0196–P0199"},{"id":"orthopedics-neurovascular","name":"连续床旁检查","cues":"固定前后或疼痛发生变化","content":"记录感觉、运动、循环和疼痛的前后差异，必要时配合压力等专业评估。全身还看失血感染及呼吸神经变化，不能局部片子正常就结束。","mechanism":"影像是某一时点结构资料，灌注及压力可继续变化。","numbers":"","avoid":"","source":"D23:P0057–P0058,P0084–P0088；BOASt2025"}],"question":"复位后影像满意，为何还要重新检查手足感觉和循环？"},{"id":"orthopedics-treatment","title":"急救、复位固定与减压","axis":"treatment","common":"保护、稳定、功能恢复共同考虑，但先排可逆的生命和肢体危险。","rows":[{"id":"orthopedics-fracture-treatment","name":"骨折三原则与开放伤","cues":"确诊骨折或开放污染","content":"复位恢复对位，固定保护稳定，功能训练支持恢复；具体内外固定随类型决定。开放伤保护覆盖、减少重复暴露，结合感染及血管风险处理，不自行把污染骨端塞回。","mechanism":"软组织损伤与骨稳定同样决定愈合。","numbers":"","avoid":"不能把所有内固定都解释为必须二次取出。","source":"D23:P0038–P0054；BOASt:开放骨折"},{"id":"orthopedics-compartment","name":"筋膜室危险","cues":"进行性不相称痛、被动牵拉痛或感觉改变","content":"立即报告并配合解除外部压迫及专科评估，确诊时需及时专业减压。连续记录神经血管和镇痛反应，不能只增加镇痛或等齐全部晚征。","mechanism":"压力升高降低组织灌注，缺血水肿可相互加重。","numbers":"","avoid":"不按摩热敷，也不因有脉搏而拖延。","source":"D23:P0022,P0058；BOASt2025"},{"id":"orthopedics-spine-treatment","name":"腰椎非手术与手术","cues":"根性痛或神经功能受损","content":"一般根据疼痛、功能、缺损及治疗反应评估保守或手术，危险缺损另走急诊分支。腰围牵引、药物与锻炼都需明确目的和适用条件，不以一种方法覆盖全部病程。","mechanism":"减轻负荷、控制症状与解除压迫的治疗目标不同。","numbers":"","avoid":"","source":"D23:P0200–P0214"}],"question":"为何固定和锻炼不能相互取代？"},{"id":"orthopedics-nursing","title":"固定方式与手术后的特有护理","axis":"nursing","common":"共性为保护位置、皮肤神经血管、避免失用，再增加装置/术式特有观察。","rows":[{"id":"orthopedics-cast","name":"石膏干固前后与拆除","cues":"石膏固定后或拟拆除","content":"未干固时平托防压痕并保护形状，干固后看清洁干燥、边缘压迫、疼痛和渗液。拆除后皮肤护理与活动循序进行；躯干石膏伴反复呕吐/呼吸受限需评估石膏综合征。","mechanism":"局部压力可损伤皮肤及循环，长时间固定造成肌关节失用。","numbers":"","avoid":"不塞异物搔痒，不自行剪改；持续痛恶臭不能只忍耐。","source":"D23:P0061–P0082"},{"id":"orthopedics-traction","name":"牵引：有效与损伤两张清单","cues":"颅骨、枕颌或下肢牵引","content":"有效性看轴线、身体位置、反牵引和重锤悬空，移动后复核。安全性看针眼皮肤与神经血管；颅骨增加意识，枕颌增加气道，下肢增加腓总神经/足背伸观察。","mechanism":"牵引方向和反力维持复位，局部压迫或感染可能成为新损伤。","numbers":"","avoid":"不自行增减重量、松绳或把偏移钢针推回。","source":"D23:P0083–P0100"},{"id":"orthopedics-staged-exercise","name":"骨折分期训练与髋置换","cues":"进入骨折恢复或髋重建后","content":"早期做允许的肌肉等长和未固定关节，中后期增加范围、肌力与步行任务。髋置换要先核实入路、负重和防脱位要求，床椅高度、转身和穿衣按个体计划教。","mechanism":"固定愈合与软组织重建需要保护，但完全制动又损害功能。","numbers":"","avoid":"不把所有髋置换统一屈髋角度、卧床和负重天数。","source":"D23:P0101–P0111,P0139–P0148,P0229；NICE CG124"},{"id":"orthopedics-spine-care","name":"脊柱搬运、颈椎准备与腰术后","cues":"疑脊柱不稳或椎间盘手术","content":"脊柱搬运翻身保持轴线，由团队协作避免扭转。颈椎术前配合由术式决定呼吸吞咽与体位训练，术后看气道吞咽及神经；腰术后看下肢神经、漏液及计划内活动。","mechanism":"颈部操作可影响气道吞咽，腰部则重根性和括约肌变化，动作不稳可加重神经损伤。","numbers":"","avoid":"颈前路准备不由患者自行推压气管；不照搬固定头高或长卧床处理所有脑脊液漏。","source":"D23:P0041,P0211–P0230"},{"id":"orthopedics-lumbar-rehab","name":"腰术后与居家保护","cues":"神经状态稳定进入康复","content":"按手术计划进行下肢与腰背功能训练，观察运动后神经症状并防失用。搬物时屈膝、重物靠近身体，交替姿势及体重管理，复述会阴/排泄或进行性无力的就医信号。","mechanism":"负荷分配与神经活动影响疼痛和恢复，强行运动可能加重症状。","numbers":"","avoid":"不规定每个人同一天起练同一强度，也不把脑脊液漏仅当伤口潮湿。","source":"D23:P0211–P0225"}],"question":"颅骨、枕颌和下肢牵引为何不能只背“重锤悬空”？"},{"id":"orthopedics-cervical","title":"颈椎术前适应与术后生活：按前后路比较","axis":"nursing","common":"先明确前路/后路、减压与融合固定方式，以及呼吸、吞咽和神经基线；训练、支具和活动由手术及康复团队制定。","rows":[{"id":"orthopedics-cervical-breath","name":"术前呼吸与安全准备","cues":"颈髓功能受影响、长期吸烟或肺功能较弱，拟行颈椎手术","content":"练习适宜的深呼吸与有效咳嗽，评估能否耐受并支持戒烟。肌力或步态不稳者增加防跌倒、防烫伤与日常辅助，让患者说明需协助的活动。","mechanism":"呼吸准备服务术后通气与排痰，感觉运动改变增加意外伤害。","numbers":"","avoid":"明显神经或呼吸恶化时不能只继续常规练习。","source":"D23:P0227–P0228；人卫《外科护理学》扫描本：印刷767–769页（PDF775–777）；CUH:颈椎术后恢复"},{"id":"orthopedics-cervical-anterior","name":"前路：气管食管牵拉适应","cues":"拟行颈前路，术前问到适应性训练","content":"训练计划涉及气管、食管牵拉适应，目的是为前路暴露与术后吞咽、呼吸问题作准备。是否采用及具体方式由团队评估指导；出现疼痛、头晕、恶心或呼吸吞咽不适应停止并报告。","mechanism":"前路经过气管食管旁，牵拉、软组织肿胀和神经受影响可造成术后吞咽/声音变化。","numbers":"","avoid":"不自行按压或推移气管食管，不把前路专项训练套给后路病人。","source":"D23:P0227–P0228；人卫《外科护理学》扫描本：印刷767–769页（PDF775–777）；RNOH:前路吞咽与声音"},{"id":"orthopedics-cervical-posterior","name":"后路：俯卧位适应","cues":"拟行颈后路，需要评估术中体位耐受","content":"在专业评估下进行与术中俯卧位相关的适应，关注颈部稳定、呼吸通畅和压力部位。训练强度与时长依心肺及神经状态调整，不以忍耐不适作为达标。","mechanism":"长时间俯卧和头颈位置会影响通气及局部压力。","numbers":"","avoid":"脊柱不稳、心肺不耐受或新发神经症状者不能自行练习俯卧。","source":"D23:P0227–P0228；人卫《外科护理学》扫描本：印刷767–769页（PDF775–777）"},{"id":"orthopedics-cervical-discharge","name":"术后保护、活动与返院信号","cues":"颈椎手术后准备出院或有支具","content":"翻身转移保持头颈躯干协调，支具是否需要、佩戴及清洁按个体计划；查贴合与皮肤，不能妨碍呼吸吞咽。逐步增加步行和允许的肢体活动，避免突然扭转和超出许可的负重，工作休息注意姿势交替与颈肩支持。","mechanism":"融合稳定、软组织恢复和神经状态决定活动范围，过度制动与过度用力都可能妨碍恢复。","numbers":"","avoid":"不把低枕、长期卧床、所有患者同一颈部操或相同支具天数作为通则。","source":"D23:P0227–P0228；人卫《外科护理学》扫描本：印刷767–769页（PDF775–777）；CUH:术后恢复及颈托"},{"id":"orthopedics-cervical-red-flags","name":"前路术后呼吸、吞咽与神经红旗","cues":"颈部肿胀、吞咽/声音改变加重，或新发神经症状","content":"留意颈部肿胀、呼吸困难、饮水呛咳及声音变化，进展性或伴呼吸受损需紧急评价。新发肢体无力麻木、步态或大小便变化也要及时报告，结合伤口和引流排查血肿、气道或神经问题。","mechanism":"血肿/水肿可压迫气道，吞咽不协调可误吸，神经变化可能提示受压或损伤。","numbers":"","avoid":"不因术后轻度咽部不适常见而忽略进行性恶化，也不自行拆线放血肿。","source":"D23:P0227–P0228；人卫《外科护理学》扫描本：印刷767–769页（PDF775–777）；CUH:颈椎术后恢复"}],"question":"术前问适应性训练时，哪些属于共性呼吸准备，哪些必须先知道前路或后路？"}],"drills":[{"id":"orthopedics-drill-compartment","title":"有脉搏，仍然紧急","stem":"小腿骨折固定后痛越来越重，被动活动足趾明显加痛，伴麻木，但足背动脉仍可触及。","prompt":"按共性骨架与部位个性列优先判断和护理，指出错用项。","answer":["共性：立即复核固定前后疼痛、感觉、运动、皮温肤色、回填与脉搏，及时报告。","个性：小腿空间与新发不相称痛/牵拉痛提示筋膜室或压迫危险，配合专业解除压迫及进一步评估。","记录发生时刻和变化，并保护患肢及稳定，处理后继续比较。","错用项：有脉搏不能排除早期问题，不能只加镇痛、按摩或热敷。"],"source":"D23:P0022,P0057–P0058,P0149–P0155；BOASt2025"},{"id":"orthopedics-drill-hip","title":"股骨颈：从术式到生活动作","stem":"老年人跌倒后髋痛，影像示移位股骨颈骨折；团队拟手术，患者担心术后不能走路，家属准备让其长期卧床。","prompt":"写术前共性与股骨颈个性，列术后必须核实的康复信息。","answer":["共性：疼痛、全身耐受、皮肤和神经血管、营养及心理评估，保护搬运并预防卧床并发症。","个性：股骨颈血供与愈合/坏死风险影响术式选择，不能把所有老年髋痛按普通挫伤。","术后先核对固定或置换、手术入路、负重和防脱位要求，再训练转移、助行器及生活动作；无禁忌时应积极推进安全活动。","错用项：不统一长期卧床，也不把某一种置换入路禁忌套给所有患者。"],"source":"D23:P0139–P0148,P0157–P0160,P0229；M083:病例目标；NICE CG124"},{"id":"orthopedics-drill-lumbar","title":"腰腿痛的病因与神经红旗","stem":"久坐工作者弯腰搬物后腰腿放射痛加重，肌力较前下降；次日新诉会阴感觉异常。","prompt":"分别写原有评估、变化后的优先级和后续教育。","answer":["共性：比较疼痛路径、感觉肌力反射及影像，评估移动、焦虑和生活能力。","个性：原有表现可引向神经根问题，新发会阴改变需紧急评估马尾等风险，不能继续按一般腰痛锻炼。","后续稳定后再按方案用支具/功能训练，教屈膝搬物、姿势交替和再次恶化就医信号。","错用项：不能靠单一抬腿试验确诊，也不能用按摩热敷代替进行性缺损处理。"],"source":"D23:P0184–P0230；M085/M086:目标"},{"id":"orthopedics-drill-dislocation","title":"三处关节，同一框架不同体征","stem":"三位外伤患者分别呈方肩、肘部骨性关系异常和下肢屈曲内收内旋短缩；均痛且不敢活动。","prompt":"用共性步骤比较三种可能损伤、复位后护理与禁止事项。","answer":["共性：保护固定，评估远端神经血管并配合影像，交专业团队复位，之后重新记录功能与循环。","个性：方肩引向肩脱位，肘骨性关系引向肘脱位，髋姿态引向后脱位方向；仍需排合并骨折。","固定后肩注意再脱位与僵硬，肘关注血管神经与后续活动，髋需按合并伤安排牵引/负重。","错用项：不能由学生自行手法复位，也不能同一固定时长用于三个关节。"],"source":"D23:P0161–P0183；M084:诊断目标"},{"id":"orthopedics-drill-cervical","title":"适应性训练必须先问手术入路","stem":"两位颈椎病患者拟手术，甲为前路，乙为后路。两人都问是否照同一视频进行术前适应，甲术后又出现逐渐加重的声音改变和吞咽不适。","prompt":"比较训练目的与适用条件，再列术后教育和需要立即报告的情况。","answer":["共性：评估呼吸/吞咽及神经基线，练习适宜深呼吸有效咳嗽并重视安全、戒烟与心理准备。","个性：甲涉及前路气管食管牵拉适应，乙涉及后路俯卧位耐受；是否实施及方法须团队评估，不能照视频自行推压气管或勉强俯卧。","术后保护头颈协调，支具、活动和负重按方案；教会清洁皮肤、循序活动及姿势交替，避免突然扭转。","甲症状进行性加重需联系团队评估；若伴呼吸困难、明显颈肿或新发肢体/排泄异常，应紧急报告。错用项是把所有声嘶都当麻醉后正常现象。"],"source":"D23:P0227–P0228；人卫《外科护理学》扫描本：印刷767–769页（PDF775–777）；CUH/RNOH:颈前路恢复"}],"references":[{"title":"BOASt：急性筋膜室综合征","url":"https://www.boa.ac.uk/resource/boast-10-pdf.html"},{"title":"BOASt：开放性骨折","url":"https://www.boa.ac.uk/resource/boast-4-pdf.html"},{"title":"NICE：髋部骨折及活动","url":"https://www.nice.org.uk/guidance/cg124/chapter/recommendations"},{"title":"NICE：创伤初始评估","url":"https://www.nice.org.uk/guidance/ng39/chapter/Recommendations"},{"title":"NHS：马尾综合征急诊线索","url":"https://www.nbt.nhs.uk/our-services/a-z-services/neurosurgery/neurosurgery-patient-information/same-day-emergency-clinic-sdec-cauda-equina-syndrome-sec"},{"title":"CUH：颈椎减压术后恢复与危险信号","url":"https://www.cuh.nhs.uk/patient-information/post-operative-recovery-following-cervical-decompression-surgery/"},{"title":"CUH：硬颈托护理","url":"https://www.cuh.nhs.uk/patient-information/wearing-a-cervical-hard-collar-a-guide-to-collar-care-for-patients-relatives-and-carers/"},{"title":"RNOH：颈前路术后吞咽与声音","url":"https://www.rnoh.nhs.uk/patients-and-visitors/patient-information-guides/adult-speech-and-language-therapy-swallowing-and-voice-after-anterior-cervical-spine-surgery-patients-guide"}]}};
